SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: task; Type: TABLE; Schema: ingest; Owner: -
--

CREATE TABLE ingest.task (
    facet text NOT NULL,
    subject text NOT NULL,
    security_id uuid,
    status ingest.task_status DEFAULT 'due'::ingest.task_status NOT NULL,
    priority numeric DEFAULT 0 NOT NULL,
    round smallint DEFAULT 1 NOT NULL,
    next_due_at timestamp with time zone DEFAULT now() NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    last_asked_at timestamp with time zone,
    last_answered_at timestamp with time zone,
    asked_with text,
    last_outcome ingest.outcome,
    last_error text,
    version integer DEFAULT 0 NOT NULL,
    watermark date,
    lease_id uuid,
    lease_expires_at timestamp with time zone,
    run_id text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: claim(text, integer, interval, text); Type: FUNCTION; Schema: ingest; Owner: -
--

CREATE FUNCTION ingest.claim(p_facet text, p_limit integer, p_lease interval, p_run_id text) RETURNS SETOF ingest.task
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ingest', 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare v_lease uuid := gen_random_uuid();
begin
  perform ingest.reap();
  return query
  with picked as (
    select t.facet, t.subject
      from ingest.task t
     where t.facet = p_facet
       and t.status in ('due','backoff')
       and t.next_due_at <= now()
     order by t.round, t.priority desc, t.subject
     limit p_limit
       for update skip locked
  )
  update ingest.task t
     set status = 'leased', lease_id = v_lease, lease_expires_at = now() + p_lease,
         run_id = p_run_id, attempts = t.attempts + 1, last_asked_at = now(), updated_at = now()
    from picked p
   where t.facet = p.facet and t.subject = p.subject
  returning t.*;
end $$;


--
-- Name: complete(text, text, ingest.outcome, text, date, text); Type: FUNCTION; Schema: ingest; Owner: -
--

CREATE FUNCTION ingest.complete(p_facet text, p_subject text, p_outcome ingest.outcome, p_asked_with text DEFAULT NULL::text, p_watermark date DEFAULT NULL::date, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ingest', 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare f ingest.facet%rowtype;
begin
  select * into f from ingest.facet where facet = p_facet;
  if not found then raise exception 'unknown facet %', p_facet; end if;

  if p_outcome = 'answered' then
    update ingest.task
       set status = 'fresh', next_due_at = now() + f.ttl, last_answered_at = now(),
           last_outcome = p_outcome, last_error = null, asked_with = coalesce(p_asked_with, asked_with),
           watermark = coalesce(p_watermark, watermark),
           lease_id = null, lease_expires_at = null, updated_at = now()
     where facet = p_facet and subject = p_subject;

  elsif p_outcome in ('dead_subject','unsupported_venue') then
    raise exception
      'a settled absence goes through ingest.mark_absent(), which requires the attempt that proves it';

  else
    -- throttled / transport / empty / parser_killed: back off and mark NOTHING. An empty answer is
    -- only ever evidence about a subject once it has been asked ALONE with the provider proven
    -- healthy, and that proof lives in `ingest.attempt`.
    update ingest.task
       set status = 'backoff', next_due_at = now() + f.backoff,
           last_outcome = p_outcome, last_error = left(p_error, 500),
           asked_with = coalesce(p_asked_with, asked_with),
           lease_id = null, lease_expires_at = null, updated_at = now()
     where facet = p_facet and subject = p_subject;
  end if;
end $$;


--
-- Name: cool_down(text, interval); Type: FUNCTION; Schema: ingest; Owner: -
--

CREATE FUNCTION ingest.cool_down(p_provider text, p_for interval DEFAULT NULL::interval) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ingest', 'pg_catalog', 'pg_temp'
    AS $$
declare b ingest.provider_budget%rowtype; until timestamptz;
begin
  select * into b from ingest.provider_budget where provider_code = p_provider for update;
  if not found then raise exception 'unknown provider %', p_provider; end if;
  until := now() + coalesce(p_for, b.cooldown);
  -- NEVER SHORTEN AN EXISTING COOLDOWN. Two runs meeting the same throttle would otherwise have the
  -- second one's shorter nap overwrite the first one's, and the pause a provider asked for is a
  -- floor, not a suggestion.
  until := greatest(until, coalesce(b.cooldown_until, until));
  update ingest.provider_budget set cooldown_until = until where provider_code = p_provider;
  return until;
end $$;


--
-- Name: FUNCTION cool_down(p_provider text, p_for interval); Type: COMMENT; Schema: ingest; Owner: -
--

COMMENT ON FUNCTION ingest.cool_down(p_provider text, p_for interval) IS 'Pause a provider that is refusing us. Never shortens a cooldown already in force.';


--
-- Name: mark_absent(text, text, bigint, text); Type: FUNCTION; Schema: ingest; Owner: -
--

CREATE FUNCTION ingest.mark_absent(p_facet text, p_subject text, p_attempt_id bigint, p_asked_with text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ingest', 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare f ingest.facet%rowtype; a ingest.attempt%rowtype;
begin
  select * into f from ingest.facet where facet = p_facet;
  if not found then raise exception 'unknown facet %', p_facet; end if;

  select * into a from ingest.attempt where attempt_id = p_attempt_id;
  if not found then raise exception 'no attempt % to justify marking % absent', p_attempt_id, p_subject; end if;
  if not a.isolated then
    raise exception
      'refusing to mark % absent: attempt % did not ask it ALONE, and a run-wide tally is never evidence about one subject',
      p_subject, p_attempt_id;
  end if;
  if a.control_answered is distinct from true then
    raise exception
      'refusing to mark % absent: attempt % did not prove the provider healthy with a control subject',
      p_subject, p_attempt_id;
  end if;

  -- MARKING MUST RETRACT. The mark excludes the subject from the backlog, so nothing else will ever
  -- remove the stale number it stops producing.
  if f.retract_sql is not null then
    execute f.retract_sql using p_subject;
    update ingest.attempt set rows_retracted = rows_retracted + 1 where attempt_id = p_attempt_id;
  end if;

  update ingest.task
     set status = 'absent', next_due_at = now() + f.absent_ttl,
         last_outcome = a.outcome, asked_with = coalesce(p_asked_with, asked_with),
         lease_id = null, lease_expires_at = null, updated_at = now()
   where facet = p_facet and subject = p_subject;
end $$;


--
-- Name: reap(); Type: FUNCTION; Schema: ingest; Owner: -
--

CREATE FUNCTION ingest.reap() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ingest', 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare n int;
begin
  with expired as (
    update ingest.task
       set status = 'backoff',
           last_outcome = 'lease_expired',
           next_due_at = now() + (select backoff from ingest.facet f where f.facet = task.facet),
           lease_id = null, lease_expires_at = null, updated_at = now()
     where status = 'leased' and lease_expires_at < now()
     returning run_id, facet
  )
  select count(*) into n from expired;

  update ingest.attempt a
     set finished_at = now(), outcome = 'lease_expired',
         error = coalesce(a.error, 'the run holding this attempt died without finishing it')
   where a.finished_at is null and a.started_at < now() - interval '10 minutes';
  return n;
end $$;


--
-- Name: requeue_symbol_keyed(uuid); Type: FUNCTION; Schema: ingest; Owner: -
--

CREATE FUNCTION ingest.requeue_symbol_keyed(p_security_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ingest', 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare n int;
begin
  with cleared as (
    update ingest.task t
       set status = 'due', next_due_at = now(), last_outcome = null, updated_at = now()
      from ingest.facet f
     where f.facet = t.facet
       and f.key_kind = 'symbol'
       and t.security_id = p_security_id
       and t.status = 'absent'
    returning 1
  ) select count(*) into n from cleared;
  return n;
end $$;


--
-- Name: requeue_version(text, integer); Type: FUNCTION; Schema: ingest; Owner: -
--

CREATE FUNCTION ingest.requeue_version(p_facet text, p_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ingest', 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare n int;
begin
  with bumped as (
    update ingest.task
       set status = 'due', next_due_at = now(), version = p_version, updated_at = now()
     where facet = p_facet and version < p_version
    returning 1
  ) select count(*) into n from bumped;
  return n;
end $$;


--
-- Name: spend(text, integer); Type: FUNCTION; Schema: ingest; Owner: -
--

CREATE FUNCTION ingest.spend(p_provider text, p_n integer DEFAULT 1) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ingest', 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare b ingest.provider_budget%rowtype;
begin
  select * into b from ingest.provider_budget where provider_code = p_provider for update;
  if not found then raise exception 'unknown provider %', p_provider; end if;
  if not b.enabled then return false; end if;
  if b.cooldown_until is not null and b.cooldown_until > now() then return false; end if;

  if b.quota_day < current_date then
    update ingest.provider_budget set used_today = 0, quota_day = current_date
     where provider_code = p_provider;
    b.used_today := 0;
  end if;

  if b.daily_quota is not null and b.used_today + p_n > b.daily_quota then return false; end if;

  update ingest.provider_budget set used_today = used_today + p_n where provider_code = p_provider;
  return true;
end $$;


--
-- Name: sync_population(text); Type: FUNCTION; Schema: ingest; Owner: -
--

CREATE FUNCTION ingest.sync_population(p_facet text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ingest', 'market', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  f ingest.facet%rowtype;
  n int;
begin
  select * into f from ingest.facet where facet = p_facet;
  if not found then raise exception 'unknown facet %', p_facet; end if;

  -- SERIALISE PER FACET. Two syncs racing would each see the other's rows as absent and assign the
  -- same round twice; `on conflict do nothing` keeps the table correct but the ordering would not
  -- be. An advisory lock held to the end of the transaction is cheaper than reasoning about it.
  perform pg_advisory_xact_lock(hashtext('ingest.sync_population:' || p_facet));

  -- ONE STATEMENT, NO TEMPORARY TABLE. The first draft materialised the population into a
  -- `create temporary table _pop on commit drop`, which works exactly once per transaction and
  -- then fails with "relation _pop already exists" — and a facet's asset syncs before every claim,
  -- so the second sync in any transaction would have died. Its own behaviour test found it.
  --
  -- The casts in `pop` ARE the shape check: a population query returning the wrong columns fails
  -- here rather than three CTEs later with a message about a type, and the handler names the facet
  -- so an operator knows which control row to look at.
  begin
    execute format($f$
      with pop as (
        select subject::text as subject, security_id::uuid as security_id,
               priority::numeric as priority, entity_rank::numeric as entity_rank
          from (%s) p
      ),
      new as (
        select p.* from pop p
          left join ingest.task t on t.facet = $1 and t.subject = p.subject
         where t.subject is null
      ),
      held as (
        select t.security_id, count(*) as n from ingest.task t where t.facet = $1 group by t.security_id
      ),
      inserted as (
        insert into ingest.task (facet, subject, security_id, priority, round)
        select $1, n.subject, n.security_id, n.priority,
               -- `round` is a smallint. A filer with more than 32,767 outstanding filings would
               -- wrap; clamping parks it at the back of the queue, which is where it belongs.
               least(32767,
                     coalesce(h.n, 0)
                     + row_number() over (partition by n.security_id
                                              order by n.entity_rank, n.subject))::smallint
          from new n
          left join held h on h.security_id is not distinct from n.security_id
        on conflict (facet, subject) do nothing
        returning 1
      )
      select count(*)::int from inserted
    $f$, f.population_sql)
    into n using p_facet;
  exception when others then
    raise exception
      'facet %: population_sql must return (subject, security_id, priority, entity_rank) — %',
      p_facet, sqlerrm;
  end;

  return n;
end $_$;


--
-- Name: FUNCTION sync_population(p_facet text); Type: COMMENT; Schema: ingest; Owner: -
--

COMMENT ON FUNCTION ingest.sync_population(p_facet text) IS 'Enqueue the subjects a facet owes that are not already in the ledger, assigning a stored round so the queue is breadth-first across entities and cannot renumber as it drains.';


--
-- Name: aggregate_performance(text, text, text[], text[], text[], text[], text[], text[], text[], text[], text[], text[], text[], text[], numeric, numeric); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.aggregate_performance(p_period text DEFAULT '1y'::text, p_group_by text DEFAULT 'sector_id'::text, p_country text[] DEFAULT NULL::text[], p_sector text[] DEFAULT NULL::text[], p_industry text[] DEFAULT NULL::text[], p_msci_tier text[] DEFAULT NULL::text[], p_msci_region text[] DEFAULT NULL::text[], p_ftse_tier text[] DEFAULT NULL::text[], p_income_group text[] DEFAULT NULL::text[], p_wb_region text[] DEFAULT NULL::text[], p_app_region text[] DEFAULT NULL::text[], p_cap_band text[] DEFAULT NULL::text[], p_style text[] DEFAULT NULL::text[], p_security_type text[] DEFAULT ARRAY['equity'::text], p_min_market_cap_usd numeric DEFAULT NULL::numeric, p_max_market_cap_usd numeric DEFAULT NULL::numeric) RETURNS TABLE(bucket text, change_pct numeric, change_pct_equal numeric, total_return_pct numeric, constituents integer, total_return_constituents integer, bucket_securities integer, weight_covered numeric, top_contributor text, top_contributor_share numeric, as_of timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
with filtered as (
  select
    f.security_id,
    f.symbol,
    f.market_cap_usd,
    case p_group_by
      when 'sector_id'      then f.sector_id
      when 'industry'       then f.industry
      when 'industry_code'  then f.industry_code
      when 'country_iso2'   then f.country_iso2
      when 'msci_tier'      then f.msci_tier
      when 'msci_region'    then f.msci_region
      when 'ftse_tier'      then f.ftse_tier
      when 'ftse_region'    then f.ftse_region
      when 'income_group'   then f.income_group
      when 'wb_region'      then f.wb_region
      when 'app_region_id'  then f.app_region_id
      when 'cap_band'       then f.cap_band
      when 'style'          then f.style
      when 'security_type'  then f.security_type_code
      -- No `else`: an unrecognised group_by buckets everything as NULL and is dropped below, so a
      -- typo returns nothing rather than silently grouping the whole universe into one row.
    end as bucket
  from market.security_facets f
  where (p_security_type      is null or f.security_type_code = any(p_security_type))
    and (p_country            is null or f.country_iso2       = any(p_country))
    and (p_sector             is null or f.sector_id          = any(p_sector))
    -- Matches EITHER spelling: the stable code is what a saved filter should carry, but a
    -- caller holding a display name must not silently get an empty bucket.
    and (p_industry           is null or f.industry = any(p_industry) or f.industry_code = any(p_industry))
    and (p_msci_tier          is null or f.msci_tier          = any(p_msci_tier))
    and (p_msci_region        is null or f.msci_region        = any(p_msci_region))
    and (p_ftse_tier          is null or f.ftse_tier          = any(p_ftse_tier))
    and (p_income_group       is null or f.income_group       = any(p_income_group))
    and (p_wb_region          is null or f.wb_region          = any(p_wb_region))
    and (p_app_region         is null or f.app_region_id      = any(p_app_region))
    and (p_cap_band           is null or f.cap_band           = any(p_cap_band))
    and (p_style              is null or f.style              = any(p_style))
    and (p_min_market_cap_usd is null or f.market_cap_usd    >= p_min_market_cap_usd)
    and (p_max_market_cap_usd is null or f.market_cap_usd    <= p_max_market_cap_usd)
),
joined as (
  -- LEFT join: securities with no performance row must still count toward `bucket_securities` and
  -- toward the DENOMINATOR of `weight_covered`. An inner join would make coverage identically 1
  -- and the guard would be decorative.
  select
    fl.bucket,
    fl.security_id,
    fl.symbol,
    fl.market_cap_usd,
    p.change_pct,
    p.total_return_pct,
    p.as_of,
    -- The row's INFLUENCE on the weighted mean. Null unless it has both factors.
    case when p.change_pct is not null and fl.market_cap_usd is not null
         then fl.market_cap_usd * p.change_pct end as contribution
  from filtered fl
  left join market.performance p
    on p.scope = 'instrument' and p.scope_id = fl.symbol and p.period = p_period
)
select
  j.bucket,
  round(
    sum(j.contribution) filter (where j.contribution is not null)
    / nullif(sum(j.market_cap_usd) filter (where j.contribution is not null), 0)
  , 4) as change_pct,
  round(avg(j.change_pct) filter (where j.change_pct is not null), 4) as change_pct_equal,
  round(
    sum(j.market_cap_usd * j.total_return_pct) filter (where j.total_return_pct is not null and j.market_cap_usd is not null)
    / nullif(sum(j.market_cap_usd) filter (where j.total_return_pct is not null and j.market_cap_usd is not null), 0)
  , 4) as total_return_pct,
  count(*) filter (where j.change_pct is not null)::integer       as constituents,
  count(*) filter (where j.total_return_pct is not null)::integer as total_return_constituents,
  count(*)::integer                                               as bucket_securities,
  round(
    sum(j.market_cap_usd) filter (where j.change_pct is not null)
    / nullif(sum(j.market_cap_usd), 0)
  , 4) as weight_covered,
  -- The single security supplying the most of this number, and how much of it. Ordered by ABSOLUTE
  -- contribution: a large negative mover is just as much "what this number is made of" as a large
  -- positive one, and signed ordering would hide it behind the positives.
  (array_agg(j.symbol order by abs(j.contribution) desc nulls last)
     filter (where j.contribution is not null))[1] as top_contributor,
  round(
    max(abs(j.contribution)) filter (where j.contribution is not null)
    / nullif(sum(abs(j.contribution)) filter (where j.contribution is not null), 0)
  , 4) as top_contributor_share,
  max(j.as_of) as as_of
from joined j
where j.bucket is not null
group by j.bucket;
$$;


--
-- Name: FUNCTION aggregate_performance(p_period text, p_group_by text, p_country text[], p_sector text[], p_industry text[], p_msci_tier text[], p_msci_region text[], p_ftse_tier text[], p_income_group text[], p_wb_region text[], p_app_region text[], p_cap_band text[], p_style text[], p_security_type text[], p_min_market_cap_usd numeric, p_max_market_cap_usd numeric); Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON FUNCTION market.aggregate_performance(p_period text, p_group_by text, p_country text[], p_sector text[], p_industry text[], p_msci_tier text[], p_msci_region text[], p_ftse_tier text[], p_income_group text[], p_wb_region text[], p_app_region text[], p_cap_band text[], p_style text[], p_security_type text[], p_min_market_cap_usd numeric, p_max_market_cap_usd numeric) IS 'Weighted returns for ANY filtered slice of the universe, grouped by any facet. Returns cap-weighted AND equal-weighted means, plus everything needed to interrogate the number: constituents, bucket_securities, weight_covered (completeness) and top_contributor/top_contributor_share (concentration). The two are different questions — measured 2026-08-19, developed large-cap value IT returned +327.40% at 98% coverage, of which 240 points came from two companies. No dynamic SQL: p_group_by is a case over a whitelist.';


--
-- Name: apply_cik_map(jsonb); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.apply_cik_map(p_map jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  v_updated integer := 0;
begin
  if p_map is null or jsonb_typeof(p_map) <> 'object' then
    raise exception 'apply_cik_map expects a json object of ticker -> cik';
  end if;

  with pairs as (
    select upper(key) as ticker, (value #>> '{}')::integer as cik
      from jsonb_each(p_map)
     -- A ticker whose value is not a number is a malformed entry, not a filer. Rejecting it here
     -- keeps one bad row from aborting the statement — migrations and this function alike apply
     -- in a single transaction.
     where jsonb_typeof(value) = 'number'
  ),
  -- Every symbol a security may legitimately be keyed on, each carrying its precedence.
  candidates as (
    -- 1. The ticker identifier. What the function has always used; unchanged.
    select i.security_id, p.cik, 1 as precedence
      from market.security_identifier i
      join pairs p on p.ticker = upper(i.value)
     where i.kind_code = 'ticker'
    union all
    -- 2. The symbol a US venue actually lists the security under. Consulted only as a fallback.
    select l.security_id, p.cik, 2 as precedence
      from market.listing l
      join market.exchange e on e.exch_code = l.exch_code
      join pairs p on p.ticker = upper(l.symbol)
     where l.symbol is not null
       and e.country_iso2 = 'US'
  ),
  -- The best available precedence per security: a ticker match is never overruled by a listing.
  best as (
    select security_id, min(precedence) as precedence
      from candidates
     group by security_id
  ),
  resolved as (
    select c.security_id,
           min(c.cik)            as cik,
           count(distinct c.cik) as rivals
      from candidates c
      join best b
        on b.security_id = c.security_id
       and b.precedence  = c.precedence
     group by c.security_id
  )
  update market.security s
     set cik = r.cik
    from resolved r
   where r.security_id = s.security_id
     -- Two symbols pointing at two different companies is not a tie-break, it is a refusal.
     and r.rivals = 1
     -- IDEMPOTENT AND CHEAP TO RE-RUN. Without this every invocation rewrites every matched row,
     -- which is the WAL cost of a full table update on a resource that runs monthly for nothing.
     and s.cik is distinct from r.cik;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


--
-- Name: FUNCTION apply_cik_map(p_map jsonb); Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON FUNCTION market.apply_cik_map(p_map jsonb) IS 'Applies SEC''s ticker -> CIK map in ONE statement, keyed on the ticker identifier and falling back to a US listing symbol. The fallback exists because OpenFIGI spells Berkshire''s B share BRK/B while SEC and the market spell it BRK-B, which left a 12.46% holding with no SEC filings or segments at all. Only US venues are consulted and an ambiguous match is refused: a wrong CIK silently attributes another company''s filings.';


--
-- Name: apply_nse_symbol_map(jsonb); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.apply_nse_symbol_map(p_map jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  v_updated integer := 0;
begin
  if p_map is null or jsonb_typeof(p_map) <> 'object' then
    raise exception 'apply_nse_symbol_map expects a json object of isin -> nse symbol';
  end if;

  with pairs as (
    select upper(key) as isin, (value #>> '{}') as symbol
      from jsonb_each(p_map)
     -- A non-string value is a malformed entry, not a listing. Rejecting it here keeps one bad row
     -- from aborting the statement, which applies in a single transaction.
     where jsonb_typeof(value) = 'string'
       and length(value #>> '{}') > 0
  ),
  resolved as (
    select i.security_id, min(p.symbol) as symbol, count(distinct p.symbol) as rivals
      from market.security_identifier i
      join pairs p on p.isin = upper(i.value)
      join market.security s on s.security_id = i.security_id
     where i.kind_code = 'isin'
       -- SCOPED TO INDIA. An ISIN is globally unique, so this cannot currently mis-hit — but NSE
       -- lists only Indian companies, and a filer id is per (security, regulator): writing one for
       -- a security in another jurisdiction would advertise a filing route that does not exist.
       and s.country_iso2 = 'IN'
     group by i.security_id
  )
  insert into market.security_filer (security_id, source_code, filer_id, as_of)
  select r.security_id, 'nse', r.symbol, now()
    from resolved r
   -- Two symbols for one ISIN is not a tie to break with min(); NSE's list has none today, which
   -- is exactly when this costs nothing to assert.
   where r.rivals = 1
  on conflict (security_id, source_code) do update
    set filer_id = excluded.filer_id,
        as_of    = excluded.as_of
    -- IDEMPOTENT. Without this every run rewrites every row, and `history_walked_at` lives on this
    -- table — an unnecessary update is WAL for nothing on a resource that runs on a TTL.
    where market.security_filer.filer_id is distinct from excluded.filer_id;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


--
-- Name: FUNCTION apply_nse_symbol_map(p_map jsonb); Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON FUNCTION market.apply_nse_symbol_map(p_map jsonb) IS 'Applies NSE''s published ISIN -> trading-symbol map in ONE statement. Exists because market.listing.symbol holds a vendor abbreviation for 406 of 645 Indian equities (SUEL for SUZLON, HUVR for HINDUNILVR), and NSE answers an unknown symbol with an empty 200 — so the resource reported success while asking the wrong question.';


--
-- Name: backlogs_to_sample(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.backlogs_to_sample() RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
  select c.relname
    from pg_class c
    join pg_namespace ns on ns.oid = c.relnamespace
   where ns.nspname = 'market'
     and c.relkind in ('v', 'm')
     and c.relname like 'pending\_%'
   order by c.relname
$$;


--
-- Name: begin_refresh(text, interval, interval, interval); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.begin_refresh(p_resource text, p_min_interval interval DEFAULT '00:05:00'::interval, p_inflight_ttl interval DEFAULT '00:02:00'::interval, p_error_backoff interval DEFAULT '00:01:00'::interval) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_temp'
    AS $$
begin
  if not pg_try_advisory_xact_lock(hashtext('market.refresh:' || p_resource)) then
    return false;
  end if;

  -- RECORD THE TTL BEFORE THE SKIP CHECK, NOT AFTER IT — and that ordering is the whole point.
  --
  -- `min_interval` exists so the stalled-resource alert can judge a resource by its OWN schedule: a
  -- 7-day TTL over quarterly filings is correctly quiet for a week, and a flat 12-hour rule flags it
  -- beside resources that have genuinely stopped. But the write started out below, after both early
  -- returns, so a resource that SKIPPED never recorded anything — and the skipping ones are exactly
  -- the ones the TTL is needed for. Measured 2026-09-04, one deploy after shipping it: 18 of 46
  -- resources had a TTL, all of them ones that had actually claimed, and the alert went on flagging
  -- `fund-holdings`, `derive-classifications` and six others against the 12-hour fallback.
  --
  -- A self-defeating fix, in other words: the evidence was collected only where it was not needed.
  -- The TTL is a property of the CALLER's intent, not of whether this particular call won the race,
  -- so it is recorded whenever we are serialised enough to write it safely — which is here, inside
  -- the advisory lock, before any decision about skipping.
  --
  -- `is distinct from` so a steady-state call writes nothing: this runs on every invocation of every
  -- resource, most of which skip.
  update market.refresh_log
     set min_interval = p_min_interval
   where resource = p_resource
     and min_interval is distinct from p_min_interval;

  if exists (
    select 1 from market.refresh_log
     where resource = p_resource
       and (
         -- A successful refresh finished recently enough.
         (ok and finished_at is not null and finished_at > now() - p_min_interval)
         -- …or another refresh is still in flight (and hasn't obviously died).
         or (finished_at is null and started_at > now() - p_inflight_ttl)
         -- …or the LAST attempt failed and is still cooling off. Without this a
         -- persistently broken upstream would be re-hit on every single trigger,
         -- and the trigger is reachable by anyone holding the public anon key.
         or (not ok and finished_at is not null and finished_at > now() - p_error_backoff)
       )
  ) then
    return false;
  end if;

  insert into market.refresh_log (resource, started_at, finished_at, ok, error, min_interval)
       values (p_resource, now(), null, false, null, p_min_interval)
  on conflict (resource) do update
     set started_at = now(), finished_at = null, ok = false, error = null,
         min_interval = excluded.min_interval;

  return true;
end $$;


--
-- Name: clear_symbol_caches(uuid); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.clear_symbol_caches(p_security_id uuid) RETURNS void
    LANGUAGE sql
    AS $$
  update market.security set
    industry_missing_at         = null,
    profile_missing_at          = null,
    performance_missing_at      = null,
    fundamentals_missing_at     = null,
    statements_missing_at       = null,
    prices_missing_at           = null,
    quarters_missing_at         = null,
    provider_country_missing_at = null,
    corporate_actions_missing_at = null,
    dividends_missing_at        = null,
    price_history_missing_at    = null,
    daily_history_missing_at    = null,
    share_stats_missing_at      = null,
    estimates_missing_at        = null,
    profile_detail_missing_at   = null
  where security_id = p_security_id;
$$;


--
-- Name: cron_next(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.cron_next() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare
  n      integer;
  pos    integer;
  target text;
begin
  select count(*) into n from market.cron_resource where enabled;
  if n = 0 then
    return null;
  end if;

  update market.cron_cursor
     set position = (position + 1) % n, advanced_at = now()
   where only_row
  returning position into pos;

  select resource into target
    from (select resource, row_number() over (order by position) - 1 as rn
            from market.cron_resource where enabled) q
   where rn = pos;

  return target;
end $$;


--
-- Name: cron_post(text); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.cron_post(p_resource text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare key text; base text;
begin
  if p_resource is null then return 'no enabled resources'; end if;

  select decrypted_secret into key  from vault.decrypted_secrets where name = 'service_role_key';
  select decrypted_secret into base from vault.decrypted_secrets where name = 'functions_base_url';
  if key is null or key = '' or base is null or base = '' then
    return 'vault secrets missing — nothing posted for ' || p_resource;
  end if;

  perform net.http_post(
    url     := base || '/market-refresh',
    body    := jsonb_build_object('resource', p_resource),
    headers := jsonb_build_object(
                 'Content-Type',  'application/json',
                 'apikey',        key,
                 'Authorization', 'Bearer ' || key),
    timeout_milliseconds := 120000
  );
  return p_resource;
end $$;


--
-- Name: cron_sample(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.cron_sample() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
begin
  return market.cron_post('observability-sample');
end $$;


--
-- Name: cron_tick(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.cron_tick() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
begin
  return market.cron_post(market.cron_next());
end $$;


--
-- Name: derive_classifications(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.derive_classifications() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'public'
    AS $$
declare n integer;
begin
  -- Sector, from the sector SPDRs' current holdings.
  insert into market.security_taxonomy (security_id, node_id, source_code, as_of)
  select h.security_id, tn.node_id, 'sec-nport', h.as_of
  from market.fund_holding_current h
  join market.security_identifier fi
    on fi.security_id = h.fund_id and fi.kind_code = 'ticker'
  join market.tracked_fund tf
    on tf.symbol = fi.value and tf.kind = 'sector' and tf.represents_code is not null
  join market.taxonomy_node tn
    on tn.taxonomy_id = 'muffin' and tn.code = tf.represents_code
  -- A fund holds itself, cash and futures; none of those is a constituent of its own sector.
  join market.security s on s.security_id = h.security_id and s.security_type_code = 'equity'
  where h.security_id <> h.fund_id
  on conflict (security_id, node_id, source_code) do update set as_of = excluded.as_of;
  get diagnostics n = row_count;

  -- Country, from the country ETFs. Written to market.security.country_iso2 only where the filing
  -- did NOT already say — the filing's own invCountry is the better source when present.
  update market.security s
     set country_iso2 = tf.represents_code
  from market.fund_holding_current h
  join market.security_identifier fi
    on fi.security_id = h.fund_id and fi.kind_code = 'ticker'
  join market.tracked_fund tf
    on tf.symbol = fi.value and tf.kind = 'country' and tf.represents_code is not null
  where s.security_id = h.security_id
    and s.country_iso2 is null
    and h.security_id <> h.fund_id;

  return n;
end $$;


--
-- Name: derive_security_metrics(integer); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.derive_security_metrics(p_limit integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  v_written integer := 0;
  v_extra   integer := 0;
begin
  -- The page, chosen by an INDEXED predicate. `derived_at is null` is served by
  -- `security_statement_underived_idx`; the NOT EXISTS this replaces had to be evaluated per row.
  create temporary table _src on commit drop as
  select st.security_id, st.statement, st.period_ending, st.currency, st.source_code,
         coalesce(st.period_type, 'annual') as period_type,
         st.data
    from market.security_statement st
   where st.derived_at is null
   order by st.as_of
   limit p_limit;

  create temporary table _touched on commit drop as
  with ins as (
    insert into market.security_metric
      (security_id, metric_code, period_type, as_of, value, currency_code, source_code, fetched_at)
    select
      src.security_id,
      f.metric_code,
      case when lower(src.period_type) in ('fy', 'annual') then 'annual'
           when lower(src.period_type) like 'q%'           then 'quarter'
           else lower(src.period_type) end,
      src.period_ending,
      (src.data ->> f.field)::numeric,
      src.currency,
      src.source_code,
      now()
    from _src src
    join market.metric_source_field f
      on f.source_code = src.source_code
     and f.statement   = src.statement
    where jsonb_typeof(src.data -> f.field) = 'number'
    on conflict (security_id, metric_code, period_type, as_of) do update
      set value = excluded.value,
          currency_code = excluded.currency_code,
          source_code = excluded.source_code,
          fetched_at = excluded.fetched_at
      -- A FILING BEATS A PROVIDER'S SUMMARY. Without this the resource that ran last wins and the
      -- served number depends on cron ordering — 17 years of XBRL quietly replaced by 4 periods of
      -- yfinance, with nothing to show for it but a shorter chart.
      where market.source_priority(excluded.source_code)
         >= market.source_priority(market.security_metric.source_code)
    returning security_id, period_type, as_of
  )
  select security_id, period_type, as_of from ins;

  get diagnostics v_written = row_count;

  insert into market.security_metric
    (security_id, metric_code, period_type, as_of, value, currency_code, source_code, fetched_at)
  select ocf.security_id, 'free_cash_flow', ocf.period_type, ocf.as_of,
         ocf.value - abs(capex.value), ocf.currency_code, 'derived', now()
    from market.security_metric ocf
    join (select distinct security_id, period_type, as_of from _touched) t
      on t.security_id = ocf.security_id and t.period_type = ocf.period_type and t.as_of = ocf.as_of
    join market.security_metric capex
      on capex.security_id = ocf.security_id
     and capex.period_type = ocf.period_type
     and capex.as_of       = ocf.as_of
     and capex.metric_code = 'capital_expenditure'
   where ocf.metric_code = 'operating_cash_flow'
     and not exists (
       select 1 from market.security_metric x
        where x.security_id = ocf.security_id and x.period_type = ocf.period_type
          and x.as_of = ocf.as_of and x.metric_code = 'free_cash_flow'
          and x.source_code <> 'derived')
  on conflict (security_id, metric_code, period_type, as_of) do update
    set value = excluded.value, source_code = excluded.source_code, fetched_at = excluded.fetched_at
    where market.source_priority(excluded.source_code)
       >= market.source_priority(market.security_metric.source_code);
  get diagnostics v_extra = row_count;
  v_written := v_written + v_extra;

  insert into market.security_metric
    (security_id, metric_code, period_type, as_of, value, currency_code, source_code, fetched_at)
  select ltd.security_id, 'total_debt', ltd.period_type, ltd.as_of,
         ltd.value + coalesce(std.value, 0), ltd.currency_code, 'derived', now()
    from market.security_metric ltd
    join (select distinct security_id, period_type, as_of from _touched) t
      on t.security_id = ltd.security_id and t.period_type = ltd.period_type and t.as_of = ltd.as_of
    left join market.security_metric std
      on std.security_id = ltd.security_id
     and std.period_type = ltd.period_type
     and std.as_of       = ltd.as_of
     and std.metric_code = 'short_term_debt'
   where ltd.metric_code = 'long_term_debt'
  on conflict (security_id, metric_code, period_type, as_of) do update
    set value = excluded.value, source_code = excluded.source_code, fetched_at = excluded.fetched_at
    where market.source_priority(excluded.source_code)
       >= market.source_priority(market.security_metric.source_code);
  get diagnostics v_extra = row_count;
  v_written := v_written + v_extra;

  -- MARK WHAT WAS PROCESSED, keyed at the statement's own grain. Without this the page cannot
  -- advance and every call returns the same rows — the defect migration 92 exists to correct.
  update market.security_statement st
     set derived_at = now()
    from _src s
   where st.security_id    = s.security_id
     and st.statement      = s.statement
     and st.period_ending  = s.period_ending
     and st.period_type    = s.period_type;

  drop table _touched;
  drop table _src;
  return v_written;
end;
$$;


--
-- Name: FUNCTION derive_security_metrics(p_limit integer); Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON FUNCTION market.derive_security_metrics(p_limit integer) IS 'Turns raw filing jsonb into the chartable series, one PAGE at a time. The source set is an anti-join over what is already derived, so a page advances and a re-fetched statement is re-derived; the derived passes join the page''s OWN rows rather than a time window, so a settled backlog does no work.';


--
-- Name: derive_segment_classification(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.derive_segment_classification() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare written integer := 0;
begin
  -- ONE AXIS PER (SECURITY, METRIC), AND THE DENOMINATOR IS THE WHOLE SPLIT.
  --
  -- 1. UNIONING THE AXES IS THE DOUBLE COUNT THIS SCHEMA IS BUILT TO PREVENT. AWS is disclosed
  --    twice — `amzn:AmazonWebServicesMember` on the product axis and
  --    `amzn:AmazonWebServicesSegmentMember` on the business axis, same 128,725,000,000 — so
  --    taking both put 257,450,000,000 of cloud into a denominator that also counted it twice, and
  --    reported information technology at 0.3066 where the truth is 0.1796. The shares still
  --    summed to 1.0, which is exactly why it survived a first reading.
  --
  -- 2. A DENOMINATOR OF ONLY THE MAPPED MEMBERS INVENTS CERTAINTY. Amazon's profit is disclosed by
  --    business segment, two of those three segments are GEOGRAPHIC and deliberately have no
  --    concept, so dividing by the mapped total alone reported information technology at 1.0000 —
  --    "Amazon is 100% a technology company by profit". Dividing by the whole split gives 47/79 =
  --    0.5949, both the honest number and the well-known one.
  --
  -- The axis is chosen per METRIC because a filer may disclose revenue on one and profit on
  -- another. Most mapped members wins, then the axis's declared priority, then the name so the
  -- choice is deterministic.
  with latest as (
    -- ONE AGGREGATE, NOT A CORRELATED SUBQUERY PER ROW. Same answer, 191,098 fewer scans.
    select security_id, axis, metric_code, max(period_ending) as pe
    from market.security_segment
    where partition_id = 1 and period_type = 'annual'
    group by 1, 2, 3
  ),
  candidate as (
    select
      c.security_id, c.axis, g.metric_code,
      count(*) filter (where sc.node_id is not null) as mapped_members,
      max(a.priority) as axis_priority
    from market.security_segment g
    -- THE SPINE, NOT THE VIEW. Whole-table access is what migration 158 materialised it for.
    join market.security_segment_spine c
      on c.security_id = g.security_id and c.axis = g.axis and c.member_code = g.member_code
    join market.segment_axis a on a.axis = g.axis
    left join market.segment_concept sc on sc.code = c.concept_code
    where g.partition_id = 1 and g.period_type = 'annual'
      and c.kind in ('product', 'business')
    group by c.security_id, c.axis, g.metric_code
  ),
  chosen as (
    select distinct on (security_id, metric_code) security_id, metric_code, axis
    from candidate
    where mapped_members > 0
    order by security_id, metric_code, mapped_members desc, axis_priority desc, axis
  ),
  -- The split's FULL total, including members nobody has mapped. This is the denominator.
  split_total as (
    select g.security_id, g.metric_code, sum(greatest(g.value, 0)) as total
    from market.security_segment g
    join chosen ch
      on ch.security_id = g.security_id and ch.metric_code = g.metric_code and ch.axis = g.axis
    join latest l
      on l.security_id = g.security_id and l.axis = g.axis and l.metric_code = g.metric_code
    where g.partition_id = 1 and g.period_type = 'annual' and g.period_ending = l.pe
    group by g.security_id, g.metric_code
  ),
  -- Several members can map to one node (a filer disclosing "AWS" and "Cloud services"
  -- separately), so collapse before dividing — and before the insert, or the statement carries the
  -- same conflict key twice and Postgres rejects the whole thing with SQLSTATE 21000.
  by_node as (
    -- CLAMPED AT THE NODE, NOT THE MEMBER. A business line that nets a loss contributes nothing,
    -- and summing only its profitable members would report a division as earning money the company
    -- did not make. The DENOMINATOR clamps per member instead, because members nobody has mapped
    -- have no node to net into — the asymmetry is deliberate and keeps every weight in [0, 1].
    select g.security_id, g.metric_code, sc.node_id, greatest(sum(g.value), 0) as value
    from market.security_segment g
    join chosen ch
      on ch.security_id = g.security_id and ch.metric_code = g.metric_code and ch.axis = g.axis
    join market.security_segment_spine c
      on c.security_id = g.security_id and c.axis = g.axis and c.member_code = g.member_code
    join market.segment_concept sc on sc.code = c.concept_code
    join latest l
      on l.security_id = g.security_id and l.axis = g.axis and l.metric_code = g.metric_code
    where g.partition_id = 1 and g.period_type = 'annual' and sc.node_id is not null
      and g.period_ending = l.pe
    group by g.security_id, g.metric_code, sc.node_id
  ),
  emitted as (
    insert into market.security_taxonomy (security_id, node_id, source_code, weight, as_of)
    select
      n.security_id, n.node_id,
      case n.metric_code when 'revenue' then 'segment-revenue' else 'segment-profit' end,
      -- CLAMPED AT ZERO IN BOTH THE NUMERATOR AND THE DENOMINATOR (`greatest` above). A segment
      -- can lose money, and a negative in the denominator makes a share EXCEED 1 — with cloud +48
      -- and retail -8 an unclamped share is 48/40 = 1.2. A negative weight would also sort a
      -- loss-making division above a profitable one under `order by weight desc`.
      round(n.value / nullif(t.total, 0), 4),
      now()
    from by_node n
    join split_total t
      on t.security_id = n.security_id and t.metric_code = n.metric_code
    where n.metric_code in ('revenue', 'operating_income')
      and t.total > 0
    -- `do update`, not `do nothing`: these rows are DERIVED, so a recomputation must replace them.
    -- The memberships that upsert `do nothing` are editorial choices a redeploy must not revert; a
    -- share of revenue is arithmetic and has no curation to protect.
    on conflict (security_id, node_id, source_code)
      do update set weight = excluded.weight, as_of = excluded.as_of
    returning 1
  )
  select count(*) into written from emitted;

  -- AN UPSERT CANNOT RETRACT. A security whose segments stopped mapping to a node keeps the weight
  -- written last time, for ever, looking freshly derived — the same defect the performance cache
  -- had, where a period the refresh stopped producing outlived the fix that stopped producing it.
  --
  -- THE SPINE HERE TOO. This `not exists` is correlated over `security_taxonomy`, so reading the
  -- view made it the third whole-table evaluation in one statement.
  delete from market.security_taxonomy st
   where st.source_code in ('segment-revenue', 'segment-profit')
     and not exists (
       select 1 from market.security_segment_spine c
       join market.segment_concept sc on sc.code = c.concept_code
       where c.security_id = st.security_id and sc.node_id = st.node_id
         and c.kind in ('product', 'business')
     );

  return written;
end $$;


--
-- Name: FUNCTION derive_segment_classification(); Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON FUNCTION market.derive_segment_classification() IS 'Derives weighted sector/industry membership from a filer''s own segment disclosure. Reads market.security_segment_spine rather than security_segment_current: this is whole-table access, which is what migration 158 materialised the spine for, and reading the view made the function exceed the PostgREST role''s 8-second timeout once the segment backlog grew (silently, for four days). The arithmetic is unchanged.';


--
-- Name: derive_sic_classification(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.derive_sic_classification() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare written integer := 0;
begin
  with emitted as (
    insert into market.security_taxonomy (security_id, node_id, source_code, as_of)
    select s.security_id, tn.node_id, 'sic', now()
    from market.security s
    join market.taxonomy_node tn
      on tn.taxonomy_id = 'sic' and tn.code = lpad(s.sic, 4, '0')
    where s.sic is not null
    -- `do nothing`: the row carries no derived value to refresh, so re-writing it every day would
    -- churn `as_of` and the WAL for nothing.
    on conflict (security_id, node_id, source_code) do nothing
    returning 1
  )
  select count(*) into written from emitted;

  -- A registrant whose SIC changed keeps the old node otherwise — an upsert cannot retract.
  delete from market.security_taxonomy st
   using market.taxonomy_node tn, market.security s
   where st.source_code = 'sic'
     and tn.node_id = st.node_id
     and s.security_id = st.security_id
     and (s.sic is null or tn.code <> lpad(s.sic, 4, '0'));

  return written;
end $$;


--
-- Name: FUNCTION derive_sic_classification(); Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON FUNCTION market.derive_sic_classification() IS 'Links each registrant to the SIC node SEC assigned it. Pure SQL. Deletes the link when the registrant''s SIC changes, because an upsert cannot retract.';


--
-- Name: derive_ttm(uuid, integer); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.derive_ttm(p_security_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 400) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare v_written integer := 0;
begin
  insert into market.security_metric
    (security_id, metric_code, period_type, as_of, value, currency_code, source_code, fetched_at)
  select
    q.security_id, q.metric_code, 'ttm', q.as_of, q.ttm_value, q.currency_code, 'derived', now()
  from (
    select
      m.security_id,
      m.metric_code,
      m.as_of,
      m.currency_code,
      sum(m.value)   over w as ttm_value,
      count(*)       over w as quarters,
      min(m.as_of)   over w as window_start
    from market.security_metric m
    join market.metric mt on mt.code = m.metric_code and mt.is_flow
    where m.period_type = 'quarter'
      and (
        p_security_id is not null
          -- BOUNDED BY THE BACKLOG, not by a bare `limit` over the rows. A `limit` on the outer
          -- select would take the same first N rows on every call; this takes N SECURITIES that
          -- are actually out of date, and they leave the set once derived.
          or m.security_id in (select security_id from market.pending_ttm limit p_limit)
      )
      and (p_security_id is null or m.security_id = p_security_id)
    window w as (
      partition by m.security_id, m.metric_code
      order by m.as_of
      rows between 3 preceding and current row
    )
  ) q
  -- EXACTLY FOUR QUARTERS, INSIDE 370 DAYS. Four rows spanning two years sum to a number that
  -- looks like a TTM and is not; a missing quarter must read as no TTM, not as a smaller year.
  where q.quarters = 4
    and q.as_of - q.window_start <= 370
  on conflict (security_id, metric_code, period_type, as_of) do update
    set value = excluded.value,
        currency_code = excluded.currency_code,
        fetched_at = excluded.fetched_at
    where market.source_priority(excluded.source_code)
       >= market.source_priority(market.security_metric.source_code);

  get diagnostics v_written = row_count;
  return v_written;
end;
$$;


--
-- Name: FUNCTION derive_ttm(p_security_id uuid, p_limit integer); Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON FUNCTION market.derive_ttm(p_security_id uuid, p_limit integer) IS 'Rolling four-quarter sums for flow metrics. Paged over market.pending_ttm because the whole-universe form timed out once the quarterly series reached 1.39M rows — a page here is a set of SECURITIES that are out of date, never a `limit` over rows, which would return the same page for ever.';


--
-- Name: finish_refresh(text, boolean, text); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.finish_refresh(p_resource text, p_ok boolean, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'market', 'pg_temp'
    AS $$
  update market.refresh_log
     set finished_at = now(), ok = p_ok, error = p_error
   where resource = p_resource;
$$;


--
-- Name: prune_news(integer); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.prune_news(p_days integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare v_deleted integer := 0;
begin
  -- The join rows go with the article via `on delete cascade`, so pruning the article is enough.
  -- Deleting the LINKS first and the articles second would leave orphans on any partial failure.
  delete from market.news_article
   where published_at < now() - make_interval(days => p_days);
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;


--
-- Name: FUNCTION prune_news(p_days integer); Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON FUNCTION market.prune_news(p_days integer) IS 'Drops articles older than the retention window; the security links cascade. The provider only reaches back about a month, so a weekly refresh adds a fresh quarter-set each time — unbounded, that compounds for ever for data whose value decays in days.';


--
-- Name: prune_observability(integer); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.prune_observability(p_days integer DEFAULT 400) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare
  cutoff timestamptz := now() - make_interval(days => p_days);
  n integer := 0; d integer;
begin
  delete from market.refresh_run     where started_at < cutoff;  get diagnostics d = row_count; n := n + d;
  delete from market.backlog_sample  where sampled_at < cutoff;  get diagnostics d = row_count; n := n + d;
  delete from market.universe_sample where sampled_at < cutoff;  get diagnostics d = row_count; n := n + d;
  delete from market.coverage_sample where sampled_at < cutoff;  get diagnostics d = row_count; n := n + d;
  return n;
end $$;


--
-- Name: refresh_facets(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.refresh_facets() RETURNS TABLE(rows_refreshed bigint, refreshed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog'
    AS $$
begin
  -- THE SYMBOL MAP FIRST. `security_facets` is what the screener reads and the symbol map is what
  -- every chart reads; refreshing them in one call is what stops the second one being forgotten.
  refresh materialized view concurrently market.symbol_security;
  refresh materialized view concurrently market.security_facets;
  return query
    select count(*)::bigint, max(f.refreshed_at) from market.security_facets f;
end;
$$;


--
-- Name: refresh_segment_spine(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.refresh_segment_spine() RETURNS TABLE(rows_refreshed bigint, duration_ms integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog'
    SET max_parallel_workers_per_gather TO '0'
    SET max_parallel_maintenance_workers TO '0'
    AS $$
declare t0 timestamptz := clock_timestamp();
begin
  -- CONCURRENTLY so the refresh does not take an ACCESS EXCLUSIVE lock on the thing every
  -- aggregate reads. It needs the unique index above, and it cannot run inside a transaction
  -- block — which is why this is its own RPC rather than a step in a larger one.
  refresh materialized view concurrently market.security_segment_spine;
  return query
    -- `extract(milliseconds from ...)` ALREADY INCLUDES THE SECONDS field, so adding
    -- `1000 * extract(seconds ...)` double-counts it: a measured 6,454 ms call reported 12,436.
    -- A number that is not what its name says is the failure mode this schema is mostly about.
    select count(*)::bigint,
           (extract(epoch from clock_timestamp() - t0) * 1000)::integer
      from market.security_segment_spine;
end;
$$;


--
-- Name: sample_backlog(text, timestamp with time zone); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.sample_backlog(p_backlog text, p_sampled_at timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare
  n  bigint;
  t0 timestamptz := clock_timestamp();
begin
  -- Only a discovered backlog, so this cannot be turned into "count any relation you name" by a
  -- caller. It is SECURITY DEFINER and reachable over the API by service_role.
  if not exists (select 1 from market.backlogs_to_sample() b where b = p_backlog) then
    raise exception 'not a backlog: %', p_backlog;
  end if;

  execute format('select count(*) from market.%I', p_backlog) into n;

  insert into market.backlog_sample (sampled_at, backlog, depth, duration_ms, error)
       values (p_sampled_at, p_backlog, n,
               extract(epoch from clock_timestamp() - t0) * 1000, null)
  on conflict (sampled_at, backlog) do update
     set depth = excluded.depth, duration_ms = excluded.duration_ms, error = null;

  return n;
end $$;


--
-- Name: sample_backlog_estimate(text, timestamp with time zone); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.sample_backlog_estimate(p_backlog text, p_sampled_at timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare
  plan jsonb;
  n    bigint;
  t0   timestamptz := clock_timestamp();
begin
  if not exists (select 1 from market.backlogs_to_sample() b where b = p_backlog) then
    raise exception 'not a backlog: %', p_backlog;
  end if;

  -- EXPLAIN without ANALYZE: the planner's estimate. No execution, no scan.
  execute format('explain (format json) select 1 from market.%I', p_backlog) into plan;
  n := (plan -> 0 -> 'Plan' ->> 'Plan Rows')::bigint;

  insert into market.backlog_sample (sampled_at, backlog, depth, duration_ms, error, estimated)
       values (p_sampled_at, p_backlog, n,
               extract(epoch from clock_timestamp() - t0) * 1000,
               'exact count timed out; planner estimate', true)
  on conflict (sampled_at, backlog) do update
     set depth = excluded.depth, duration_ms = excluded.duration_ms,
         error = excluded.error, estimated = true;

  return n;
end $$;


--
-- Name: sample_coverage(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.sample_coverage() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare
  ts timestamptz := now();
  n  integer;
begin
  insert into market.coverage_sample (
    sampled_at, dimension, bucket, security_type_code, securities, segment_capable, complete,
    present_facets, applicable_facets,
    with_symbol, with_sector, with_industry, with_price, with_performance,
    with_profile, with_fundamentals, with_statements, with_metrics,
    priced_3d, priced_7d, priced_30d,
    with_price_history, with_daily_history, with_news, with_leadership, with_insider,
    with_filings, with_dividends, with_share_stats, with_estimates, with_quarters,
    with_sic, with_segments, with_segment_geography, with_weighted_industry)
  select ts, dimension, bucket, security_type_code, securities, segment_capable, complete,
         present_facets, applicable_facets,
         with_symbol, with_sector, with_industry, with_price, with_performance,
         with_profile, with_fundamentals, with_statements, with_metrics,
         priced_3d, priced_7d, priced_30d,
         with_price_history, with_daily_history, with_news, with_leadership, with_insider,
         with_filings, with_dividends, with_share_stats, with_estimates, with_quarters,
         with_sic, with_segments, with_segment_geography, with_weighted_industry
    from market.coverage_current
  on conflict (sampled_at, dimension, bucket, security_type_code) do nothing;

  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: sample_quality(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.sample_quality() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare
  ts    timestamptz := now();
  taken integer := 0;
begin
  perform set_config('statement_timeout', '30s', true);

  -- The invariants, as trends rather than a nightly bit.
  insert into market.universe_sample (sampled_at, metric, value)
  select ts, 'defect.' || defect, n from market.data_defect
  on conflict do nothing;
  get diagnostics taken = row_count;

  insert into market.universe_sample (sampled_at, metric, value)
  select ts, 'out_of_range.' || metric_code, n from market.metric_out_of_range
  on conflict do nothing;

  -- THE UNIT-FLIP TRIPWIRE. p50 and p99 per metric — 149 ms for all 16 codes, measured. The
  -- fraction/percent confusion has hit this schema THREE times: OpenBB returning performance as a
  -- fraction, the shared `pct()` that rendered NVIDIA at a 46% dividend yield, and
  -- `surprise_percent`. Every one was invisible per row and obvious in the aggregate. A p50 that
  -- moves 100x between two samples is a unit change, and this catches the whole CLASS rather than
  -- one metric at a time.
  insert into market.universe_sample (sampled_at, metric, value)
  select ts, 'dist.' || metric_code || '.' || stat, v from (
    select metric_code, 'p50' as stat, percentile_cont(0.5) within group (order by value) as v
      from market.security_metric where period_type = 'ttm' group by metric_code
    union all
    select metric_code, 'p99', percentile_cont(0.99) within group (order by value)
      from market.security_metric where period_type = 'ttm' group by metric_code
  ) q where v is not null
  on conflict do nothing;

  -- PROVENANCE. Measured sec-xbrl 2,114,386 / derived 693,306 / yfinance 614,212 / sec 3,896.
  -- A sudden shift means a provider changed behaviour or a resource stopped writing — neither of
  -- which any count of rows can show, because the total barely moves while the mix does.
  insert into market.universe_sample (sampled_at, metric, value)
  select ts, 'provenance.' || source_code, count(*) from market.security_metric
   group by source_code
  on conflict do nothing;

  return taken;
end $$;


--
-- Name: sample_universe(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.sample_universe() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog', 'pg_temp'
    AS $$
declare
  r     record;
  n     bigint;
  ts    timestamptz := now();
  taken integer := 0;
  newest timestamptz;
begin
  perform set_config('statement_timeout', '30s', true);

  -- ESTIMATED rows, exact on-disk size. `reltuples` is -1 for a relation never analysed
  -- (Postgres 14+ distinguishes that from a genuine zero), so it is skipped rather than recorded
  -- as -1. Exact counting all 63 tables was 10,252 ms cold and bought nothing a gauge needs.
  for r in
    select c.relname as tbl, c.reltuples as est, pg_total_relation_size(c.oid) as bytes
      from pg_class c join pg_namespace ns on ns.oid = c.relnamespace
     where ns.nspname = 'market' and c.relkind = 'r'
     order by c.relname
  loop
    if r.est >= 0 then
      insert into market.universe_sample (sampled_at, metric, value)
           values (ts, 'rows_estimate.' || r.tbl, r.est) on conflict do nothing;
      taken := taken + 1;
    end if;
    insert into market.universe_sample (sampled_at, metric, value)
         values (ts, 'bytes.' || r.tbl, r.bytes) on conflict do nothing;
    taken := taken + 1;
  end loop;

  -- Negative-cache populations. EXACT, and they have to be: a 20% jump is an alert, and an
  -- estimate's error bar is wider than that.
  for r in
    select c.relname as tbl, a.attname as col
      from pg_class c join pg_namespace ns on ns.oid = c.relnamespace
      join pg_attribute a on a.attrelid = c.oid
     where ns.nspname = 'market' and c.relkind = 'r'
       and a.attnum > 0 and not a.attisdropped and a.attname like '%\_missing\_at'
     order by c.relname, a.attname
  loop
    begin
      execute format('select count(*) from market.%I where %I is not null', r.tbl, r.col) into n;
      insert into market.universe_sample (sampled_at, metric, value)
           values (ts, format('missing.%s.%s', r.tbl, r.col), n) on conflict do nothing;

      -- ABOUT TO LAPSE. The negative caches expire at 30 days, so a mark older than 23 days is
      -- work returning to a backlog within the week. Without this the backlog simply jumps and
      -- nothing explains it.
      execute format(
        'select count(*) from market.%I where %I is not null and %I < now() - interval ''23 days''',
        r.tbl, r.col, r.col) into n;
      insert into market.universe_sample (sampled_at, metric, value)
           values (ts, format('expiring.%s.%s', r.tbl, r.col), n) on conflict do nothing;
      taken := taken + 2;
    exception when others then null;
    end;
  end loop;

  -- FRESHNESS. The age in hours of the newest row per timestamped table, discovered rather than
  -- listed — 449 ms for all of them, slowest 141 ms. An AGE rather than a timestamp so a panel
  -- can threshold it without knowing when it was sampled.
  for r in
    select c.relname as tbl, a.attname as col
      from pg_class c join pg_namespace ns on ns.oid = c.relnamespace
      join pg_attribute a on a.attrelid = c.oid
     where ns.nspname = 'market' and c.relkind = 'r'
       and a.attnum > 0 and not a.attisdropped and a.attname in ('as_of', 'fetched_at')
     order by c.relname, a.attname
  loop
    begin
      execute format('select max(%I) from market.%I', r.col, r.tbl) into newest;
      if newest is not null then
        insert into market.universe_sample (sampled_at, metric, value)
             values (ts, format('fresh_hours.%s.%s', r.tbl, r.col),
                     extract(epoch from (ts - newest)) / 3600.0) on conflict do nothing;
        taken := taken + 1;
      end if;
    exception when others then null;
    end;
  end loop;

  -- The newest price bar. Its own entry because `security_price` keys on `date`, not `as_of`, and
  -- because it is the single most load-bearing freshness number here. Cheap only since migration
  -- 130 indexed (date, security_id): this was 9,366 ms before it and is 0.475 ms after.
  begin
    select max(date)::timestamptz into newest from market.security_price;
    if newest is not null then
      insert into market.universe_sample (sampled_at, metric, value)
           values (ts, 'fresh_hours.security_price.date',
                   extract(epoch from (ts - newest)) / 3600.0) on conflict do nothing;
      taken := taken + 1;
    end if;
  exception when others then null;
  end;

  -- STALENESS AS THE APP SEES IT. `performance.stale_after` is the pipeline's own judgement about
  -- when a number stops being good; this is how much of it has passed that point. 76,209 today.
  begin
    select count(*) into n from market.performance where stale_after < now();
    insert into market.universe_sample (sampled_at, metric, value)
         values (ts, 'stale.performance', n) on conflict do nothing;
    taken := taken + 1;
  exception when others then null;
  end;

  -- GROWTH. Whether the universe is still being extended — i.e. whether `promote-wave` and the
  -- fund ingest are doing anything. A flat line here with a healthy backlog means promotion has
  -- stopped, which nothing else reports.
  begin
    select count(*) into n from market.security where first_seen_at > now() - interval '7 days';
    insert into market.universe_sample (sampled_at, metric, value)
         values (ts, 'growth.securities_7d', n) on conflict do nothing;
    select count(*) into n from market.security where first_seen_at > now() - interval '30 days';
    insert into market.universe_sample (sampled_at, metric, value)
         values (ts, 'growth.securities_30d', n) on conflict do nothing;
    taken := taken + 2;
  exception when others then null;
  end;

  -- THE SCHEDULER ITSELF. With GitHub Actions gone, pg_cron is the only thing driving the
  -- pipeline and its failure is silent — the data just stops. `minutes_since_tick` is what the
  -- "scheduler has gone silent" alert watches; the rotation fires every 5 minutes, so anything
  -- past 30 means it has stopped.
  begin
    insert into market.universe_sample (sampled_at, metric, value)
    select ts, m, v from (
      select 'scheduler.ticks_1h' as m, ticks_1h::numeric as v from market.scheduler_health()
      union all select 'scheduler.failed_1h', failed_1h from market.scheduler_health()
      union all select 'scheduler.minutes_since_tick', minutes_since_tick from market.scheduler_health()
    ) s where v is not null
    on conflict do nothing;
    taken := taken + 3;
  exception when others then null;   -- no pg_cron in the test image
  end;

  -- EXACT, because market-verify.yml asserts floors on exactly these.
  insert into market.universe_sample (sampled_at, metric, value)
  select ts, m, v from (
    select 'equities' as m, count(*)::numeric as v from market.security where security_type_code = 'equity'
    union all select 'identifiers.isin',   count(*) from market.security_identifier where kind_code = 'isin'
    union all select 'identifiers.ticker', count(*) from market.security_identifier where kind_code = 'ticker'
    union all select 'identifiers.cusip',  count(*) from market.security_identifier where kind_code = 'cusip'
    union all select 'tracked_funds.enabled',  count(*) from market.tracked_fund where enabled = true
    union all select 'tracked_funds.ingested', count(*) from market.tracked_fund where last_report_date is not null
  ) s
  on conflict do nothing;

  -- BREADTH, WHICH IS THE NUMBER THAT GATES THE SEGMENT FEATURE. Companies REACHED, not facts
  -- written: while `pending_segments` was ordered by fund weight the queue walked one company's
  -- whole 20-year history before starting the next, so 440 parsed filings belonged to fourteen
  -- securities — and every other signal (`written`, `remaining`, `ok`, the reconciliation guard)
  -- said healthy, because the rows being written were correct. They were the wrong rows first.
  -- Nothing here could see it, because nothing counted companies.
  --
  -- `count(distinct security_id)` over `security_segment` measured 486 ms at 1.92M rows, which is
  -- affordable twice an hour. It is EXACT rather than a `reltuples` estimate because the whole
  -- point is a small integer (14 against 3,500) where a few percent of error is the entire signal.
  begin
    insert into market.universe_sample (sampled_at, metric, value)
    select ts, m, v from (
      select 'segments.companies' as m, count(distinct security_id)::numeric as v
        from market.security_segment
      union all
      select 'segments.filings_parsed', count(*)
        from market.security_filing where segments_parsed_at is not null
      union all
      select 'segments.comparable_concepts', count(*) from (
        select 1 from market.security_segment_spine
         where concept_code is not null
         group by concept_code having count(distinct security_id) >= 2) c
    ) s
    on conflict do nothing;
    taken := taken + 3;
  exception when others then null;   -- the spine may not exist yet on a partially-applied database
  end;

  return taken + 6;
end $$;


--
-- Name: scheduler_health(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.scheduler_health() RETURNS TABLE(ticks_1h bigint, failed_1h bigint, minutes_since_tick numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'cron', 'pg_catalog', 'pg_temp'
    AS $$
begin
  return query
  select
    count(*) filter (where start_time > now() - interval '1 hour'),
    count(*) filter (where start_time > now() - interval '1 hour' and status <> 'succeeded'),
    round(extract(epoch from (now() - max(start_time))) / 60.0, 1)
  from cron.job_run_details;
exception when others then
  -- No pg_cron (the migration-test image). Report nothing rather than failing the sampler.
  return;
end $$;


--
-- Name: security_statement_requeue(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.security_statement_requeue() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.as_of is distinct from old.as_of or new.data is distinct from old.data then
    new.derived_at := null;
  end if;
  return new;
end;
$$;


--
-- Name: set_debt_terms(jsonb); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.set_debt_terms(p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_temp'
    AS $$
declare
  n integer;
begin
  update market.security s
     set maturity_date    = r.maturity_date,
         coupon_rate      = r.coupon_rate,
         coupon_kind_code = r.coupon_kind_code,
         in_default       = r.in_default,
         debt_terms_as_of = r.as_of
    from jsonb_to_recordset(p_rows) as r(
           security_id uuid,
           maturity_date date,
           coupon_rate numeric,
           coupon_kind_code text,
           in_default boolean,
           as_of timestamptz
         )
   where s.security_id = r.security_id
     -- NEVER let an older filing overwrite a newer one. Funds are ingested in whatever order the
     -- backlog offers, and two funds holding the same bond file at different quarter-ends, so
     -- without this the stored terms would flap depending on which fund ran last.
     and (s.debt_terms_as_of is null or r.as_of >= s.debt_terms_as_of);

  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: source_priority(text); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.source_priority(p_code text) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select coalesce((select priority from market.data_source where code = p_code), 0);
$$;


--
-- Name: sync_sec_filer(); Type: FUNCTION; Schema: market; Owner: -
--

CREATE FUNCTION market.sync_sec_filer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'market', 'pg_catalog'
    AS $$
begin
  if new.cik is not null then
    insert into market.security_filer (security_id, source_code, filer_id)
         values (new.security_id, 'sec', new.cik::text)
    on conflict (security_id, source_code) do update set filer_id = excluded.filer_id;
  else
    -- A CLEARED CIK MUST RETRACT. Leaving the row would keep the security reading `held` against a
    -- registration we no longer believe in, and an upsert cannot retract.
    delete from market.security_filer
     where security_id = new.security_id and source_code = 'sec';
  end if;
  return new;
end $$;


