--
-- Name: COLUMN security.figi_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.figi_missing_at IS 'When OpenFIGI last returned no US listing for this security. Excludes it from pending_ticker for 30 days so a permanent non-answer does not crowd out resolvable ones.';


--
-- Name: COLUMN security.profile_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.profile_missing_at IS 'When the profile provider last returned nothing for this security. Excludes it from pending_profile for 30 days so an unanswerable symbol does not crowd out answerable ones.';


--
-- Name: COLUMN security.local_symbol_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.local_symbol_missing_at IS 'When the local-listing lookup last found nothing addressable. Excludes it from pending_local_symbol for 30 days.';


--
-- Name: COLUMN security.performance_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.performance_missing_at IS 'When the price provider last returned no series for this security. Excludes it from pending_performance for 30 days.';


--
-- Name: COLUMN security.market_cap; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.market_cap IS 'From yfinance equity/profile, captured by security-profiles. Reported in the security''s own currency, which is why the column carries no unit conversion.';


--
-- Name: COLUMN security.yahoo_symbol_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.yahoo_symbol_missing_at IS 'When the ISIN search last failed to return a listing on this security''s home market. Excludes it from pending_yahoo_symbol for 30 days — a security can gain a listing, so this is not permanent.';


--
-- Name: COLUMN security.prices_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.prices_missing_at IS 'When the price provider last returned no series for this security. Excludes it from pending_prices for 30 days — the same negative cache every other backlog needs, and for the same reason.';


--
-- Name: COLUMN security.provider_country_iso2; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.provider_country_iso2 IS 'Operating HQ country from equity/profile.hq_country, resolved to ISO-2. Kept BESIDE the filed country_iso2 (incorporation, from N-PORT) rather than overwriting it — Alibaba is incorporated in KY and operates in CN, and both are true.';


--
-- Name: COLUMN security.provider_country_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.provider_country_missing_at IS 'The profile answered for this security and carried no resolvable hq_country. Without this the security re-enters pending_profile every run for ever.';


--
-- Name: COLUMN security.corporate_actions_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.corporate_actions_missing_at IS 'Tiingo answered about this security and had nothing, or does not carry it. Symbol-keyed: the request is made BY the US ticker, so a corrected symbol invalidates it.';


--
-- Name: COLUMN security.coupon_rate; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.coupon_rate IS 'Annualised coupon percent from N-PORT annualizedRt. 0.0 is a REAL zero-coupon bond, not a missing value — do not test it for truthiness.';


--
-- Name: COLUMN security.debt_terms_as_of; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.debt_terms_as_of IS 'Which filing these terms came from. A floating-rate note''s annualizedRt is a snapshot at the filing date, not a fixed property of the instrument.';


--
-- Name: COLUMN security.dividends_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.dividends_missing_at IS 'Negative cache for `security-dividends`. SYMBOL-KEYED: yfinance is asked by the same symbol the prices use, so a corrected symbol must clear it.';


--
-- Name: COLUMN security.statement_currency_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.statement_currency_missing_at IS 'We asked SEC for this company''s filings and it had none, so its statements will keep their null currency. Keyed on the US TICKER, not the provider symbol — a corrected symbol must NOT clear it. 30 days, because a company can begin filing.';


--
-- Name: COLUMN security.price_history_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.price_history_missing_at IS 'We asked for this security''s long weekly history and the provider had none. Symbol-keyed, so market.clear_symbol_caches must clear it — a corrected symbol is a different question.';


--
-- Name: COLUMN security.cik; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.cik IS 'SEC filer id, from company_tickers.json matched on the US ticker. NOT unique — share classes share a filer (GOOG and GOOGL are both 1652044).';


--
-- Name: COLUMN security.xbrl_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.xbrl_missing_at IS 'We asked SEC for this filer''s company facts and got nothing usable. Keyed on the CIK, so a corrected provider SYMBOL says nothing about it and must not clear it.';


--
-- Name: COLUMN security.symbol_repair_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.symbol_repair_at IS 'When this security was last considered for a symbol repair — set whether or not one was found, so a security whose spelling is simply right is not re-tried every run. Keyed on the CIK-free provider symbol, and cleared by nothing: a repair that failed once can be retried after the window.';


--
-- Name: COLUMN security.quarters_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.quarters_missing_at IS 'Set when the provider was asked for QUARTERLY statements alone and returned none. Swiss and some other issuers report semi-annually, so this is an ordinary permanent answer rather than a fault.';


--
-- Name: COLUMN security.reporting_currency; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.reporting_currency IS 'The currency the company reports its accounts in — NOT the currency its listing trades in. BHP and Shell quote AUD and GBP and report USD. Promoted from security_fundamentals.raw->>''currency'' (yfinance), which is measured to be the reporting currency.';


--
-- Name: COLUMN security.profile_detail_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.profile_detail_missing_at IS 'Set when `equity/profile` was asked about this symbol ALONE and returned no descriptive fields. Distinct from `profile_missing_at`, which is about the sector.';


--
-- Name: COLUMN security.insider_fetched_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.insider_fetched_at IS 'When Form 4 filings were last fetched for this security. A CURSOR, not a negative cache — deliberately not a `%_missing_at` column, because "no insider trades this week" is never a permanent fact about a company.';


--
-- Name: COLUMN security.filings_fetched_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.filings_fetched_at IS 'When the SEC filing index was last read for this security. A CURSOR, not a negative cache — companies keep filing, so an absence is never permanent.';


--
-- Name: COLUMN security.management_fetched_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.management_fetched_at IS 'When the officer list was last read. A CURSOR at six months — a board is the slowest-moving fact here, and an absence is never permanent.';


--
-- Name: COLUMN security.eps_history_fetched_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.eps_history_fetched_at IS 'When deep EPS history was last fetched. A CURSOR at 90 days — a new quarter arrives four times a year, and the provider allows 25 calls a DAY in total, so re-asking sooner would spend the whole budget on securities that cannot have changed.';


--
-- Name: COLUMN security.daily_history_from; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.daily_history_from IS 'Earliest DAILY bar obtained by security-daily-history. Null means the deep backfill has not run for this security. Not derived from security_price on read: that is a whole-table scan on every backlog evaluation.';


--
-- Name: COLUMN security.daily_history_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.daily_history_missing_at IS 'We asked for deep daily history for this symbol and the provider returned nothing. 30-day negative cache.';


--
-- Name: COLUMN security.price_history_from; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.price_history_from IS 'Earliest WEEKLY bar held for this security. A stored marker rather than a scan: asking security_price directly costs 7.9s cold, against 8ms here. Written by security-price-history; backfilled once by migration 140.';


--
-- Name: COLUMN security.filing_history_fetched_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.filing_history_fetched_at IS 'When SEC''s submissions API was last walked for this filer''s COMPLETE filing history. A cursor, not a negative cache — companies keep filing.';


--
-- Name: COLUMN security.sic; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.sic IS 'SEC''s Standard Industrial Classification for the filer, from the submissions response we already fetch for the filing history. A real four-level hierarchy, and the only industry code that comes from the registrant rather than a provider''s opinion.';


--
-- Name: COLUMN security.wikidata_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.wikidata_missing_at IS 'Wikidata has no industry tags for this security''s ISIN. Re-asked after 30 days, because an entry can be created.';


--
-- Name: COLUMN security.price_targets_fetched_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security.price_targets_fetched_at IS 'When analyst price-target actions were last fetched. A CURSOR, not a negative cache: an absence of ratings this week says nothing permanent about the company, so this is deliberately not a `%_missing_at` column.';


--
-- Name: security_identifier; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_identifier (
    kind_code text NOT NULL,
    value text NOT NULL,
    security_id uuid NOT NULL,
    source_code text
);


--
-- Name: security_provider_symbol; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_provider_symbol (
    security_id uuid NOT NULL,
    provider_code text NOT NULL,
    symbol text NOT NULL
);


--
-- Name: security_symbol; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_symbol AS
 SELECT s.security_id,
    COALESCE(( SELECT l.provider_symbol
           FROM market.listing l
          WHERE ((l.security_id = s.security_id) AND l.is_primary)
         LIMIT 1), ps.symbol, t.value) AS symbol
   FROM ((market.security s
     LEFT JOIN LATERAL ( SELECT i.value
           FROM market.security_identifier i
          WHERE ((i.security_id = s.security_id) AND (i.kind_code = 'ticker'::text))
          ORDER BY i.value
         LIMIT 1) t ON (true))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
  WHERE (COALESCE(( SELECT l.provider_symbol
           FROM market.listing l
          WHERE ((l.security_id = s.security_id) AND l.is_primary)
         LIMIT 1), ps.symbol, t.value) IS NOT NULL);


--
-- Name: VIEW security_symbol; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_symbol IS 'The one symbol a security is known by: its PRIMARY LISTING first, then the local line, then the US/OTC ticker. The OTC line is last deliberately — it is what OpenFIGI returns for a US lookup and is usually the least traded of the three.';


--
-- Name: security_taxonomy; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_taxonomy (
    security_id uuid NOT NULL,
    node_id uuid NOT NULL,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL,
    weight numeric
);


--
-- Name: COLUMN security_taxonomy.weight; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_taxonomy.weight IS 'How much of the company this classification accounts for, 0..1 — revenue share for `segment-revenue`, operating-income share for `segment-profit`. NULL for a provider opinion, which asserts a category without quantifying it.';


--
-- Name: taxonomy_node; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.taxonomy_node (
    node_id uuid DEFAULT gen_random_uuid() NOT NULL,
    taxonomy_id text NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    parent_id uuid,
    level integer DEFAULT 1 NOT NULL,
    icon text,
    sort_order integer DEFAULT 0 NOT NULL
);


--
-- Name: tracked_fund; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.tracked_fund (
    symbol text NOT NULL,
    name text,
    kind text,
    enabled boolean DEFAULT true NOT NULL,
    cik text,
    series_id text,
    last_accession text,
    last_report_date date,
    last_ingested_at timestamp with time zone,
    notes text,
    added_at timestamp with time zone DEFAULT now() NOT NULL,
    represents_code text,
    retired_at timestamp with time zone
);


--
-- Name: COLUMN tracked_fund.represents_code; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.tracked_fund.represents_code IS 'What this fund stands for: a market.sectors id when kind=''sector'', an ISO-2 country code when kind=''country''. NULL = the fund contributes holdings but classifies nothing.';


--
-- Name: COLUMN tracked_fund.retired_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.tracked_fund.retired_at IS 'When this fund was found to have stopped filing N-PORT. Set instead of deleting, so the holdings it contributed keep their provenance and the row documents why it is no longer refreshed.';


--
-- Name: country_sector_performance; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.country_sector_performance AS
 WITH constituent AS (
         SELECT DISTINCT ON (s.security_id) s.security_id,
            COALESCE(s.provider_country_iso2, s.country_iso2) AS country_iso2,
            tn.code AS sector_id,
            sym.symbol,
            h.weight,
            tf.symbol AS fund_symbol
           FROM (((((((market.security s
             JOIN market.security_taxonomy st ON ((st.security_id = s.security_id)))
             JOIN market.taxonomy_node tn ON (((tn.node_id = st.node_id) AND (tn.taxonomy_id = 'muffin'::text) AND (tn.level = 1))))
             JOIN market.data_source ds ON ((ds.code = st.source_code)))
             JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
             JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
             JOIN market.security_identifier fi ON (((fi.security_id = h.fund_id) AND (fi.kind_code = 'ticker'::text))))
             JOIN market.tracked_fund tf ON (((tf.symbol = fi.value) AND (tf.kind = 'country'::text) AND (tf.represents_code = COALESCE(s.provider_country_iso2, s.country_iso2)))))
          WHERE ((COALESCE(s.provider_country_iso2, s.country_iso2) IS NOT NULL) AND (s.security_type_code = 'equity'::text) AND (h.weight > (0)::numeric) AND (sym.symbol IS NOT NULL))
          ORDER BY s.security_id, ds.priority DESC, st.as_of DESC
        )
 SELECT c.country_iso2,
    c.sector_id,
    p.period,
    round((sum((c.weight * p.change_pct)) / NULLIF(sum(c.weight), (0)::numeric)), 4) AS change_pct,
    round((sum((c.weight * p.total_return_pct)) FILTER (WHERE (p.total_return_pct IS NOT NULL)) / NULLIF(sum(c.weight) FILTER (WHERE (p.total_return_pct IS NOT NULL)), (0)::numeric)), 4) AS total_return_pct,
    count(*) AS constituents,
    count(*) FILTER (WHERE (p.total_return_pct IS NOT NULL)) AS total_return_constituents,
    round(sum(c.weight), 4) AS weight_covered,
    min(c.fund_symbol) AS fund_symbol,
    max(p.as_of) AS as_of
   FROM (constituent c
     JOIN market.performance p ON (((p.scope = 'instrument'::text) AND (p.scope_id = c.symbol))))
  GROUP BY c.country_iso2, c.sector_id, p.period;


--
-- Name: coupon_kind; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.coupon_kind (
    code text NOT NULL,
    name text
);


--
-- Name: TABLE coupon_kind; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.coupon_kind IS 'N-PORT couponKind values, LEARNED from filings rather than seeded. Observed 2026-08-18: Fixed, Variable, Floating, None — where "None" is a reported kind (a bond that pays no coupon), not a missing value.';


--
-- Name: disclosure_coverage; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.disclosure_coverage (
    source_code text NOT NULL,
    country_iso2 text NOT NULL
);


--
-- Name: TABLE disclosure_coverage; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.disclosure_coverage IS 'Which jurisdictions a regulator serves, for securities whose filer id has not been resolved yet. SEC has NO rows on purpose — it is registration-driven and serves any country that registers with it, so a country row would wrongly imply every US-domiciled security is reachable and every foreign one is not.';


--
-- Name: disclosure_source; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.disclosure_source (
    code text NOT NULL,
    name text NOT NULL,
    identifier_label text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    priority integer DEFAULT 0 NOT NULL,
    note text
);


--
-- Name: TABLE disclosure_source; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.disclosure_source IS 'Regulators that publish machine-readable disclosures. A control table: adding one is a row plus a resource, never a schema change. `enabled` is false until a resource exists, because an enabled source with no fetcher reports an addressable backlog that nothing can address.';


--
-- Name: fx_rate; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.fx_rate (
    currency_code text NOT NULL,
    as_of date NOT NULL,
    usd_per_unit numeric NOT NULL,
    source_code text NOT NULL,
    derived_from text,
    CONSTRAINT fx_rate_usd_per_unit_check CHECK ((usd_per_unit > (0)::numeric))
);


--
-- Name: COLUMN fx_rate.usd_per_unit; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.fx_rate.usd_per_unit IS 'USD per ONE unit of this currency — multiply a figure in this currency by it to reach USD. The reciprocal spelling is equally common and equally plausible-looking, which is why the direction is in the name.';


--
-- Name: COLUMN fx_rate.derived_from; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.fx_rate.derived_from IS 'The parent currency when this row is a SUBUNIT (ILA=ILS/100, ZAC=ZAR/100, KWF=KWD/1000). NULL when the rate was quoted directly. A derived rate and a quoted one are different facts.';


--
-- Name: fx_rate_current; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.fx_rate_current AS
 SELECT DISTINCT ON (currency_code) currency_code,
    as_of,
    usd_per_unit,
    source_code,
    derived_from
   FROM market.fx_rate
  ORDER BY currency_code, as_of DESC;


--
-- Name: insider_trade; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.insider_trade (
    trade_key text NOT NULL,
    security_id uuid NOT NULL,
    filing_date date,
    transaction_date date,
    owner_name text,
    owner_title text,
    direction text,
    transaction_type text,
    security_type text,
    shares numeric,
    shares_owned_after numeric,
    price numeric,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE insider_trade; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.insider_trade IS 'Form 4 insider transactions from `equity/ownership/insider_trading?provider=sec`. Keyed on a deterministic hash of the filing''s own facts because the response carries no id — re-fetching the same filing is then idempotent rather than duplicating it every run.';


--
-- Name: issuer; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.issuer (
    issuer_id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    lei text,
    cik text,
    country_iso2 text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: news_security; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.news_security (
    url text NOT NULL,
    security_id uuid NOT NULL,
    source_code text NOT NULL
);


--
-- Name: TABLE news_security; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.news_security IS 'Which securities a provider returned an article for. An ATTRIBUTION, not a curated relationship: yfinance returned a Waymo story under AAPL. A UI saying "related news" is honest; one saying "news about this company" is not.';


--
-- Name: required_facet; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.required_facet (
    security_type_code text NOT NULL,
    facet text NOT NULL,
    required boolean DEFAULT true NOT NULL
);


--
-- Name: security_corporate_action; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_corporate_action (
    security_id uuid NOT NULL,
    ex_date date NOT NULL,
    kind text NOT NULL,
    value numeric NOT NULL,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL,
    observed_symbol text NOT NULL
);


--
-- Name: TABLE security_corporate_action; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_corporate_action IS 'Splits and cash dividends with their ex-date, from Tiingo daily EOD (US-listed only — local foreign listings 404). Recorded rather than inferred: firstComparableIndex can only see that a price jumped, not whether it was a split, a redenomination or a real move.';


--
-- Name: COLUMN security_corporate_action.observed_symbol; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_corporate_action.observed_symbol IS 'The symbol this action was observed on — always the US ticker, since that is the only symbology Tiingo carries. Kept so a consumer can verify the action describes the same listing as the price series it is about to adjust; 33 of the first 45 securities ingested did not.';


--
-- Name: security_currency; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_currency AS
 SELECT s.security_id,
    COALESCE(pl.currency_code, s.currency_code) AS currency_code,
        CASE
            WHEN (pl.currency_code IS NOT NULL) THEN 'listing'::text
            WHEN (s.currency_code IS NOT NULL) THEN 'security'::text
            ELSE NULL::text
        END AS source,
    pl.exch_code AS venue
   FROM (market.security s
     LEFT JOIN market.listing pl ON (((pl.security_id = s.security_id) AND pl.is_primary)));


--
-- Name: VIEW security_currency; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_currency IS 'The one place to ask what currency a security''s figures are in. Prefers the primary LISTING (the normalized fact) and falls back to the security — which is not a compromise, because 15,159 bonds have no listing and their filing currency is the only correct answer. `source` says which was used.';


--
-- Name: security_current; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_current AS
 SELECT s.security_id,
    s.name,
    s.security_type_code,
    COALESCE(s.provider_country_iso2, s.country_iso2) AS country_iso2,
    s.currency_code,
    s.is_tradeable,
    s.market_cap,
    sym.symbol,
    isin.value AS isin,
    i.name AS issuer_name,
    c.name AS country_name,
    ( SELECT tn.code
           FROM ((market.security_taxonomy st
             JOIN market.taxonomy_node tn ON (((tn.node_id = st.node_id) AND (tn.taxonomy_id = 'muffin'::text) AND (tn.level = 1))))
             JOIN market.data_source ds ON ((ds.code = st.source_code)))
          WHERE (st.security_id = s.security_id)
          ORDER BY ds.priority DESC, st.as_of DESC
         LIMIT 1) AS sector_id,
    ( SELECT n.name
           FROM ((market.security_taxonomy st2
             JOIN market.taxonomy_node n ON (((n.node_id = st2.node_id) AND (n.taxonomy_id = 'muffin'::text) AND (n.level = 2) AND (n.parent_id = ( SELECT tn.node_id
                   FROM ((market.security_taxonomy st_sec
                     JOIN market.taxonomy_node tn ON (((tn.node_id = st_sec.node_id) AND (tn.taxonomy_id = 'muffin'::text) AND (tn.level = 1))))
                     JOIN market.data_source ds_sec ON ((ds_sec.code = st_sec.source_code)))
                  WHERE (st_sec.security_id = s.security_id)
                  ORDER BY ds_sec.priority DESC, st_sec.as_of DESC
                 LIMIT 1)))))
             JOIN market.data_source ds2 ON ((ds2.code = st2.source_code)))
          WHERE (st2.security_id = s.security_id)
          ORDER BY ds2.priority DESC, st2.as_of DESC
         LIMIT 1) AS industry,
    ( SELECT n.code
           FROM ((market.security_taxonomy st2
             JOIN market.taxonomy_node n ON (((n.node_id = st2.node_id) AND (n.taxonomy_id = 'muffin'::text) AND (n.level = 2) AND (n.parent_id = ( SELECT tn.node_id
                   FROM ((market.security_taxonomy st_sec
                     JOIN market.taxonomy_node tn ON (((tn.node_id = st_sec.node_id) AND (tn.taxonomy_id = 'muffin'::text) AND (tn.level = 1))))
                     JOIN market.data_source ds_sec ON ((ds_sec.code = st_sec.source_code)))
                  WHERE (st_sec.security_id = s.security_id)
                  ORDER BY ds_sec.priority DESC, st_sec.as_of DESC
                 LIMIT 1)))))
             JOIN market.data_source ds2 ON ((ds2.code = st2.source_code)))
          WHERE (st2.security_id = s.security_id)
          ORDER BY ds2.priority DESC, st2.as_of DESC
         LIMIT 1) AS industry_code,
    s.country_iso2 AS filed_country_iso2,
    s.provider_country_iso2
   FROM ((((market.security s
     LEFT JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
     LEFT JOIN market.security_identifier isin ON (((isin.security_id = s.security_id) AND (isin.kind_code = 'isin'::text))))
     LEFT JOIN market.issuer i ON ((i.issuer_id = s.issuer_id)))
     LEFT JOIN market.countries c ON ((c.iso2 = COALESCE(s.provider_country_iso2, s.country_iso2))));


--
-- Name: security_filer; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_filer (
    security_id uuid NOT NULL,
    source_code text NOT NULL,
    filer_id text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL,
    history_walked_at timestamp with time zone
);


--
-- Name: TABLE security_filer; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_filer IS 'The identifier each regulator addresses a security by — a CIK for SEC, a corp_code for DART. filer_id is NOT unique: share classes share a filer (GOOG and GOOGL are one CIK), which is why security.cik could never live in security_identifier.';


--
-- Name: security_disclosure; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_disclosure AS
 WITH enabled_source AS MATERIALIZED (
         SELECT disclosure_source.code,
            disclosure_source.priority
           FROM market.disclosure_source
          WHERE disclosure_source.enabled
        ), held AS MATERIALIZED (
         SELECT DISTINCT ON (f.security_id) f.security_id,
            f.source_code,
            f.filer_id
           FROM (market.security_filer f
             JOIN enabled_source d ON ((d.code = f.source_code)))
          ORDER BY f.security_id, d.priority DESC, f.source_code
        ), by_country AS MATERIALIZED (
         SELECT DISTINCT ON (c.country_iso2) c.country_iso2,
            c.source_code
           FROM (market.disclosure_coverage c
             JOIN enabled_source d ON ((d.code = c.source_code)))
          ORDER BY c.country_iso2, d.priority DESC, c.source_code
        )
 SELECT s.security_id,
    COALESCE(h.source_code, bc.source_code) AS segment_source,
    (h.source_code IS NOT NULL) AS filer_id_held,
        CASE
            WHEN (h.source_code IS NOT NULL) THEN 'held'::text
            WHEN (bc.source_code IS NOT NULL) THEN 'resolvable'::text
            ELSE 'none'::text
        END AS capability,
    h.filer_id
   FROM ((market.security s
     LEFT JOIN held h ON ((h.security_id = s.security_id)))
     LEFT JOIN by_country bc ON ((bc.country_iso2 = COALESCE(s.provider_country_iso2, s.country_iso2))));


--
-- Name: VIEW security_disclosure; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_disclosure IS 'Which regulator can serve a security, in three states: `held` (a filer id is stored, fetchable now), `resolvable` (its jurisdiction has an ENABLED source but the id is unresolved — the addressable backlog) and `none` (no source covers it, so an absence is permanent). Country is the EFFECTIVE one, coalesce(provider, filed), the same value security_current answers with.';


--
-- Name: security_estimate; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_estimate (
    security_id uuid NOT NULL,
    as_of date NOT NULL,
    target_high numeric,
    target_low numeric,
    target_consensus numeric,
    target_median numeric,
    recommendation text,
    recommendation_mean numeric,
    number_of_analysts integer,
    currency_code text,
    source_code text NOT NULL,
    fetched_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE security_estimate; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_estimate IS 'Analyst consensus and price targets. `data-coverage.md` called these "all premium"; measured 2026-08-20, yfinance answers for every market tried. Keyed on the FETCH date because a consensus is a running figure with no reported period of its own.';


--
-- Name: COLUMN security_estimate.recommendation_mean; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_estimate.recommendation_mean IS 'yfinance''s 1..5 scale where LOWER IS MORE BULLISH — 2.11 for AAPL beside recommendation "buy". Treating it as a score to maximise inverts every recommendation shown.';


--
-- Name: security_fundamentals; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_fundamentals (
    security_id uuid NOT NULL,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL,
    pe_ratio numeric,
    forward_pe numeric,
    peg_ratio numeric,
    price_to_book numeric,
    profit_margin numeric,
    gross_margin numeric,
    operating_margin numeric,
    return_on_equity numeric,
    revenue_growth numeric,
    debt_to_equity numeric,
    dividend_yield numeric,
    beta numeric,
    enterprise_value numeric,
    raw jsonb
);


--
-- Name: security_market_cap_usd; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_market_cap_usd AS
 SELECT s.security_id,
    s.market_cap AS market_cap_native,
    s.currency_code,
        CASE
            WHEN (s.market_cap IS NULL) THEN NULL::numeric
            WHEN (s.currency_code = 'USD'::text) THEN s.market_cap
            ELSE (s.market_cap * fx.usd_per_unit)
        END AS market_cap_usd,
    fx.as_of AS fx_as_of
   FROM (market.security s
     LEFT JOIN market.fx_rate_current fx ON ((fx.currency_code = s.currency_code)));


--
-- Name: security_style; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_style AS
 WITH scoreable AS (
         SELECT f.security_id,
            (1.0 / f.price_to_book) AS book_to_price,
            cm.group_id AS tier,
                CASE
                    WHEN (mc.market_cap_usd >= '10000000000'::numeric) THEN 'large'::text
                    WHEN (mc.market_cap_usd >= '2000000000'::numeric) THEN 'mid'::text
                    WHEN (mc.market_cap_usd > (0)::numeric) THEN 'small'::text
                    ELSE NULL::text
                END AS cap_band
           FROM ((((market.security_fundamentals f
             JOIN market.security_current sc_1 ON ((sc_1.security_id = f.security_id)))
             JOIN market.security s ON ((s.security_id = f.security_id)))
             JOIN market.classification_members cm ON (((cm.iso2 = sc_1.country_iso2) AND (cm.scheme_id = 'msci'::text) AND (cm.lens = 'tier'::text))))
             JOIN market.security_market_cap_usd mc ON ((mc.security_id = f.security_id)))
          WHERE ((s.security_type_code = 'equity'::text) AND (f.price_to_book IS NOT NULL) AND (f.price_to_book > (0)::numeric) AND (mc.market_cap_usd > (0)::numeric))
        ), cohorted AS (
         SELECT scoreable.security_id,
            scoreable.book_to_price,
            ((scoreable.tier || '/'::text) || scoreable.cap_band) AS cohort,
            count(*) OVER (PARTITION BY scoreable.tier, scoreable.cap_band) AS cohort_size,
            percent_rank() OVER (PARTITION BY scoreable.tier, scoreable.cap_band ORDER BY scoreable.book_to_price) AS value_score
           FROM scoreable
        ), scored AS (
         SELECT cohorted.security_id,
            cohorted.book_to_price,
            cohorted.cohort,
            cohorted.cohort_size,
            cohorted.value_score
           FROM cohorted
          WHERE (cohorted.cohort_size >= 30)
        ), index_label AS (
         SELECT h.security_id,
                CASE
                    WHEN ((count(*) FILTER (WHERE (fi.value = 'IWF'::text)) > 0) AND (count(*) FILTER (WHERE (fi.value = 'IWD'::text)) > 0)) THEN 'blend'::text
                    WHEN (count(*) FILTER (WHERE (fi.value = 'IWF'::text)) > 0) THEN 'growth'::text
                    WHEN (count(*) FILTER (WHERE (fi.value = 'IWD'::text)) > 0) THEN 'value'::text
                    ELSE NULL::text
                END AS style
           FROM (market.fund_holding_current h
             JOIN market.security_identifier fi ON (((fi.security_id = h.fund_id) AND (fi.kind_code = 'ticker'::text))))
          WHERE (fi.value = ANY (ARRAY['IWF'::text, 'IWD'::text]))
          GROUP BY h.security_id
        )
 SELECT sc.security_id,
    round((sc.value_score)::numeric, 4) AS value_score,
    round(sc.book_to_price, 4) AS book_to_price,
    sc.cohort,
    sc.cohort_size,
    COALESCE(il.style,
        CASE
            WHEN (sc.value_score >= (0.29)::double precision) THEN 'value'::text
            WHEN (sc.value_score <= (0.10)::double precision) THEN 'growth'::text
            ELSE 'blend'::text
        END) AS style,
        CASE
            WHEN (il.style IS NOT NULL) THEN 'index'::text
            ELSE 'composite'::text
        END AS style_source,
        CASE
            WHEN (il.style IS NOT NULL) THEN 'high'::text
            WHEN (sc.value_score >= (0.29)::double precision) THEN 'moderate'::text
            ELSE 'low'::text
        END AS style_confidence
   FROM (scored sc
     LEFT JOIN index_label il ON ((il.security_id = sc.security_id)));


--
-- Name: VIEW security_style; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_style IS 'Growth/value, fitted against Russell 1000 Growth/Value membership (IWF/IWD) rather than invented, and ranked WITHIN a (MSCI tier x cap band) peer group because a global ranking labels 89% of the world "value" — the median Russell name sits at the 0.299 percentile globally and 0.430 within its cohort. Thresholds reproduce Russell''s own proportions rather than maximising accuracy, which halves outright growth<->value swaps to 2.5%. Measured recall: value 0.84, growth 0.48, blend 0.36. value_score (a within-cohort percentile) is the primary artifact; the label is derived; style_confidence carries the measured trust.';


--
-- Name: security_facets; Type: MATERIALIZED VIEW; Schema: market; Owner: -
--

CREATE MATERIALIZED VIEW market.security_facets AS
 WITH country_lens AS (
         SELECT classification_members.iso2,
            max(classification_members.group_id) FILTER (WHERE ((classification_members.scheme_id = 'msci'::text) AND (classification_members.lens = 'tier'::text))) AS msci_tier,
            max(classification_members.group_id) FILTER (WHERE ((classification_members.scheme_id = 'msci'::text) AND (classification_members.lens = 'region'::text))) AS msci_region,
            max(classification_members.group_id) FILTER (WHERE ((classification_members.scheme_id = 'ftse'::text) AND (classification_members.lens = 'tier'::text))) AS ftse_tier,
            max(classification_members.group_id) FILTER (WHERE ((classification_members.scheme_id = 'ftse'::text) AND (classification_members.lens = 'region'::text))) AS ftse_region,
            max(classification_members.group_id) FILTER (WHERE ((classification_members.scheme_id = 'world-bank'::text) AND (classification_members.lens = 'tier'::text))) AS income_group,
            max(classification_members.group_id) FILTER (WHERE ((classification_members.scheme_id = 'world-bank'::text) AND (classification_members.lens = 'region'::text))) AS wb_region
           FROM market.classification_members
          GROUP BY classification_members.iso2
        )
 SELECT sc.security_id,
    sc.symbol,
    sc.name,
    sc.security_type_code,
    sc.sector_id,
    sc.industry,
    sc.industry_code,
    sc.country_iso2,
    sc.country_name,
    c.region_id AS app_region_id,
    c.market AS country_market,
    cl.msci_tier,
    cl.msci_region,
    cl.ftse_tier,
    cl.ftse_region,
    cl.income_group,
    cl.wb_region,
    mc.market_cap_usd,
    sc.market_cap AS market_cap_native,
        CASE
            WHEN (mc.market_cap_usd IS NULL) THEN NULL::text
            WHEN (mc.market_cap_usd >= '10000000000'::numeric) THEN 'large'::text
            WHEN (mc.market_cap_usd >= '2000000000'::numeric) THEN 'mid'::text
            WHEN (mc.market_cap_usd > (0)::numeric) THEN 'small'::text
            ELSE NULL::text
        END AS cap_band,
    cur.currency_code,
    cur.source AS currency_source,
    s.maturity_date,
    s.coupon_rate,
    s.coupon_kind_code,
    s.in_default,
    sc.is_tradeable,
    sty.style,
    sty.style_source,
    sty.style_confidence,
    sty.value_score,
    sty.cohort AS style_cohort,
    now() AS refreshed_at
   FROM ((((((market.security_current sc
     JOIN market.security s ON ((s.security_id = sc.security_id)))
     LEFT JOIN market.countries c ON ((c.iso2 = sc.country_iso2)))
     LEFT JOIN country_lens cl ON ((cl.iso2 = sc.country_iso2)))
     LEFT JOIN market.security_market_cap_usd mc ON ((mc.security_id = sc.security_id)))
     LEFT JOIN market.security_currency cur ON ((cur.security_id = sc.security_id)))
     LEFT JOIN market.security_style sty ON ((sty.security_id = sc.security_id)))
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW security_facets; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON MATERIALIZED VIEW market.security_facets IS 'The filter spine: every dimension a list can be filtered by, on one row per security. MATERIALISED because the un-materialised view timed out for anon (57014) the moment two filters were combined — measured 2026-08-19, msci_tier AND sector_id took 2993ms against a 3s statement timeout, while the same query answers in 0.47ms from here. Refreshed by the `facets-refresh` resource; `refreshed_at` carries the snapshot age.';


--
-- Name: security_filing; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_filing (
    accession_number text NOT NULL,
    security_id uuid NOT NULL,
    filing_date date,
    report_date date,
    report_type text,
    report_url text,
    filing_detail_url text,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL,
    segments_parsed_at timestamp with time zone,
    segments_parser_version smallint,
    is_xbrl boolean
);


--
-- Name: TABLE security_filing; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_filing IS 'The SEC filings themselves — 10-K/10-Q/8-K and the 20-F/6-K a foreign private issuer files instead — with their dates and URLs. `security_statement` holds the numbers a filing reported; this holds the document, which is what makes a research answer citable.';


--
-- Name: COLUMN security_filing.segments_parsed_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_filing.segments_parsed_at IS 'When this filing''s XBRL instance was read for segment facts. NOT a negative cache with an expiry: a filed document is immutable, so "this filing discloses no segments" is permanent. Re-reading is driven by segments_parser_version instead.';


--
-- Name: COLUMN security_filing.is_xbrl; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_filing.is_xbrl IS 'Whether SEC reports this filing as carrying XBRL. NULL means unknown — rows written before the submissions walk — and is treated as "worth trying", because every filing since 2019 has it.';


--
-- Name: security_metric; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_metric (
    security_id uuid NOT NULL,
    metric_code text NOT NULL,
    period_type text NOT NULL,
    as_of date NOT NULL,
    value numeric NOT NULL,
    currency_code text,
    source_code text NOT NULL,
    fetched_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE security_metric; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_metric IS 'One value per (security, metric, period type, period end) — the shape macro_observation already uses for countries, so a company metric and a country metric differ only in what they hang off.';


--
-- Name: COLUMN security_metric.period_type; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_metric.period_type IS 'Part of the KEY. One period end carries both an annual and a TTM figure and they are different facts; keeping this beside the key would let one overwrite the other.';


--
-- Name: security_officer; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_officer (
    security_id uuid NOT NULL,
    name text NOT NULL,
    title text,
    pay numeric,
    year_born integer,
    age integer,
    fiscal_year integer,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE security_officer; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_officer IS 'Named officers from `equity/fundamental/management` — global, unlike most of this schema. Keyed on the person''s name because the response carries no id and a company does not have two officers of the same name.';


--
-- Name: security_price; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_price (
    security_id uuid NOT NULL,
    date date NOT NULL,
    close numeric NOT NULL,
    grain text DEFAULT 'daily'::text NOT NULL,
    CONSTRAINT security_price_grain_chk CHECK ((grain = ANY (ARRAY['daily'::text, 'weekly'::text])))
);


--
-- Name: TABLE security_price; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_price IS 'Daily closes for the fund-derived universe, keyed on the security so a listing or symbol change cannot orphan the series. ~400-day rolling window, pruned on write. market.prices remains the curated-instrument series, including instruments that are not securities.';


--
-- Name: COLUMN security_price.grain; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_price.grain IS 'How the bar was sampled. `daily` is a rolling window; `weekly` is the full 20-year history and DELIBERATELY overlaps it, so a long chart does not end where the daily window begins. Part of the primary key, because one date carries both.';


--
-- Name: security_profile; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_profile (
    security_id uuid NOT NULL,
    description text,
    employees integer,
    website text,
    hq_city text,
    hq_state text,
    hq_country text,
    beta numeric,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE security_profile; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_profile IS 'Descriptive company identity from `equity/profile` — the fields `security-profiles` was fetching and discarding. A separate table because `description` is a paragraph and `market.security` is joined by the spine matview and every serving view.';


--
-- Name: security_segment; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_segment (
    security_id uuid NOT NULL,
    axis text NOT NULL,
    member_code text NOT NULL,
    metric_code text NOT NULL,
    period_type text NOT NULL,
    period_ending date NOT NULL,
    period_start date,
    value numeric NOT NULL,
    currency_code text,
    partition_id smallint DEFAULT 0 NOT NULL,
    accession_number text,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL,
    reconciled_to numeric,
    parent_axis text,
    parent_member text,
    parent_key text GENERATED ALWAYS AS (COALESCE(parent_member, ''::text)) STORED NOT NULL,
    CONSTRAINT security_segment_period_type_check CHECK ((period_type = ANY (ARRAY['annual'::text, 'quarter'::text, 'instant'::text])))
);


--
-- Name: TABLE security_segment; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_segment IS 'Revenue, operating income and capital expenditure per disclosed business line, parsed from the filing''s XBRL instance. AGGREGATE WITHIN ONE partition_id ONLY: an axis can carry several overlapping splits that each sum to the consolidated total (Amazon discloses three), so summing an axis doubles the company''s revenue and summing the table triples it. partition_id 0 is a subtotal and must never be summed.';


--
-- Name: COLUMN security_segment.period_type; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_segment.period_type IS 'annual / quarter for flows measured over a period; `instant` for stocks measured at a date (segment assets). An instant''s partition is inherited from a duration bucket on the same axis and date, because segment assets never sum to consolidated assets and could otherwise never be placed.';


--
-- Name: COLUMN security_segment.partition_id; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_segment.partition_id IS 'Which disclosed split this member belongs to. 1 is the finest split that reconciles to the filing''s own consolidated figure; 2+ are coarser splits of the same total; 0 is a subtotal (Apple''s ProductMember is the sum of iPhone/iPad/Mac/Wearables) or a member the parser could not place.';


--
-- Name: COLUMN security_segment.reconciled_to; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_segment.reconciled_to IS 'The consolidated figure THIS split was accepted against — for its own metric, period type and span. NOT shared across the group: the partition MAP is one fact per (axis, period end) and is applied across metrics and period types deliberately, but the target is not, and stamping the winning bucket''s target on the whole group gave a quarter the year''s revenue for 3,021 of 11,211 splits. Null where the filing never states that metric undimensioned for that span, which is the honest answer — a consumer must skip a null target rather than assert against a borrowed one.';


--
-- Name: COLUMN security_segment.parent_member; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_segment.parent_member IS 'For a fact tagged with TWO segment axes, the coarser member it sits inside — Alphabet''s Search is a product line WITHIN Google Services. NULL for an ordinary flat member. A nested row''s siblings sum to the PARENT''s value, not to the company''s consolidated figure, so nested and flat rows must never be summed together.';


--
-- Name: security_segment_latest; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_segment_latest AS
 WITH ranked AS (
         SELECT g.security_id,
            g.axis,
            g.member_code,
            g.metric_code,
            g.period_type,
            g.period_ending,
            g.period_start,
            g.value,
            g.currency_code,
            g.partition_id,
            g.accession_number,
            g.source_code,
            g.as_of,
            g.reconciled_to,
            g.parent_axis,
            g.parent_member,
            g.parent_key,
            f.filing_date,
            dense_rank() OVER (PARTITION BY g.security_id, g.axis, g.metric_code, g.period_type, g.period_ending ORDER BY f.filing_date DESC NULLS LAST, g.accession_number DESC) AS filing_rank
           FROM (market.security_segment g
             LEFT JOIN market.security_filing f ON (((f.security_id = g.security_id) AND (f.accession_number = g.accession_number))))
        )
 SELECT security_id,
    axis,
    member_code,
    parent_axis,
    parent_member,
    metric_code,
    period_type,
    period_ending,
    period_start,
    value,
    currency_code,
    partition_id,
    reconciled_to,
    accession_number,
    filing_date,
    source_code,
    as_of
   FROM ranked
  WHERE (filing_rank = 1);


--
-- Name: VIEW security_segment_latest; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_segment_latest IS 'One filing per (security, axis, metric, period) — the most recently filed. An annual report carries three years of comparatives, so a period appears in several filings, and filers RENAME member codes between them (ASML''s EuvMember became NXEMember). Reading the raw table unions two complete splits of the same period and counts the company twice. Everything that serves segments reads this, not `security_segment`.';


--
-- Name: segment_alias; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.segment_alias (
    member_code text NOT NULL,
    concept_code text NOT NULL,
    security_id uuid
);


--
-- Name: TABLE segment_alias; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.segment_alias IS 'Maps a filer''s own XBRL member code onto a shared concept. Scoped per security because member codes are not globally unique — `us-gaap:ProductMember` means something different in every filing.';


--
-- Name: segment_axis; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.segment_axis (
    taxonomy text NOT NULL,
    axis text NOT NULL,
    kind text NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    required_member text,
    CONSTRAINT segment_axis_kind_check CHECK ((kind = ANY (ARRAY['product'::text, 'business'::text, 'geography'::text, 'qualifier'::text])))
);


--
-- Name: TABLE segment_axis; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.segment_axis IS 'Which XBRL dimensions express a business segmentation, per taxonomy. us-gaap and ifrs-full spell the same idea differently, so the axis name is data rather than code — adding a taxonomy is rows. `kind = qualifier` marks a dimension that narrows a fact without sub-dividing it (Alphabet tags every segment figure with ConsolidationItems=OperatingSegments).';


--
-- Name: COLUMN segment_axis.required_member; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.segment_axis.required_member IS 'A member this axis MUST carry for the fact to be kept; NULL means any. Rejects only when the axis is PRESENT with a different member, so a filer that omits it is unaffected. Korea''s ConsolidatedAndSeparateFinancialStatementsAxis pins ConsolidatedMember (SeparateMember is parent-only accounts — a different company''s numbers), and SegmentConsolidationItemsAxis pins OperatingSegmentsMember: migration 155 assumed that axis "narrows a fact without changing what it measures", and it does not — the elimination member is the other COLUMN of the segment table, and admitting it stored Hyundai Mobis''s intersegment eliminations as its business-line split.';


--
-- Name: segment_concept; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.segment_concept (
    code text NOT NULL,
    name text NOT NULL,
    parent_code text,
    node_id uuid
);


--
-- Name: TABLE segment_concept; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.segment_concept IS 'The shared vocabulary of business lines — "cloud-infrastructure", "smartphones" — that a filer''s own member codes are mapped onto. Editable in Studio; a redeploy must not revert a curation.';


--
-- Name: segment_member; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.segment_member (
    member_code text NOT NULL,
    kind text NOT NULL,
    country_iso2 text,
    label text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT segment_member_kind_check CHECK ((kind = ANY (ARRAY['product'::text, 'business'::text, 'geography'::text])))
);


--
-- Name: TABLE segment_member; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.segment_member IS 'Members whose meaning is PUBLISHED rather than filer-specific — ISO country members and the standard region members. A control table: a member met for the first time is a row here, and until it is one it inherits its axis''s kind and appears in pending_segment_alias.';


--
-- Name: security_segment_current; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_segment_current AS
 WITH newest AS (
         SELECT g.security_id,
            g.axis,
            max(g.period_ending) AS period_ending
           FROM market.security_segment_latest g
          WHERE ((g.partition_id = 1) AND (g.period_type = 'annual'::text) AND (g.parent_member IS NULL))
          GROUP BY g.security_id, g.axis
        ), latest AS (
         SELECT DISTINCT ON (g.security_id, g.axis, g.member_code, g.metric_code) g.security_id,
            g.axis,
            g.member_code,
            g.metric_code,
            g.value,
            g.currency_code,
            g.period_ending,
            g.accession_number,
            g.reconciled_to
           FROM (market.security_segment_latest g
             JOIN newest n ON (((n.security_id = g.security_id) AND (n.axis = g.axis) AND (n.period_ending = g.period_ending))))
          WHERE ((g.partition_id = 1) AND (g.period_type = 'annual'::text) AND (g.parent_member IS NULL))
          ORDER BY g.security_id, g.axis, g.member_code, g.metric_code, g.period_ending DESC
        ), pivoted AS (
         SELECT l.security_id,
            l.axis,
            l.member_code,
            max(l.currency_code) AS currency_code,
            max(l.period_ending) AS period_ending,
            max(l.accession_number) AS accession_number,
            max(l.reconciled_to) AS reconciled_to,
            max(l.value) FILTER (WHERE (l.metric_code = 'revenue'::text)) AS revenue,
            max(l.value) FILTER (WHERE (l.metric_code = 'operating_income'::text)) AS operating_income,
            max(l.value) FILTER (WHERE (l.metric_code = 'capital_expenditure'::text)) AS capital_expenditure,
            max(l.value) FILTER (WHERE (l.metric_code = 'depreciation'::text)) AS depreciation,
            max(l.value) FILTER (WHERE (l.metric_code = 'cost_of_revenue'::text)) AS cost_of_revenue
           FROM latest l
          GROUP BY l.security_id, l.axis, l.member_code
        )
 SELECT p.security_id,
    p.axis,
    COALESCE(sm.kind, a.kind) AS kind,
    p.member_code,
    c.code AS concept_code,
    c.name AS concept_name,
    p.revenue,
    p.operating_income,
    p.capital_expenditure,
    p.depreciation,
    p.cost_of_revenue,
    ast.value AS total_assets,
        CASE
            WHEN ((p.revenue IS NOT NULL) AND (p.revenue <> (0)::numeric)) THEN round((((100)::numeric * p.operating_income) / p.revenue), 2)
            ELSE NULL::numeric
        END AS operating_margin_pct,
        CASE
            WHEN ((p.revenue IS NOT NULL) AND (p.revenue <> (0)::numeric) AND (p.cost_of_revenue IS NOT NULL)) THEN round((((100)::numeric * (p.revenue - p.cost_of_revenue)) / p.revenue), 2)
            ELSE NULL::numeric
        END AS gross_margin_pct,
        CASE
            WHEN ((p.depreciation IS NOT NULL) AND (p.depreciation <> (0)::numeric)) THEN round((p.capital_expenditure / p.depreciation), 2)
            ELSE NULL::numeric
        END AS capex_to_depreciation,
        CASE
            WHEN ((ast.value IS NOT NULL) AND (ast.value <> (0)::numeric)) THEN round((((100)::numeric * p.operating_income) / ast.value), 2)
            ELSE NULL::numeric
        END AS return_on_segment_assets_pct,
    round((((100)::numeric * p.revenue) / NULLIF(sum(p.revenue) OVER (PARTITION BY p.security_id, p.axis), (0)::numeric)), 2) AS revenue_share_pct,
    p.currency_code,
    p.period_ending,
    p.accession_number,
    p.reconciled_to,
    sm.country_iso2,
    sm.label AS member_label,
    lla.value AS long_lived_assets,
    gw.value AS goodwill
   FROM (((((((pivoted p
     CROSS JOIN LATERAL ( SELECT ax.kind
           FROM market.segment_axis ax
          WHERE (ax.axis = p.axis)
          ORDER BY ax.priority DESC, ax.taxonomy
         LIMIT 1) a)
     LEFT JOIN market.segment_member sm ON ((sm.member_code = p.member_code)))
     LEFT JOIN LATERAL ( SELECT g.value
           FROM market.security_segment_latest g
          WHERE ((g.security_id = p.security_id) AND (g.axis = p.axis) AND (g.member_code = p.member_code) AND (g.metric_code = 'total_assets'::text) AND (g.period_type = 'instant'::text) AND (g.partition_id = 1) AND (g.parent_member IS NULL) AND (g.period_ending <= p.period_ending))
          ORDER BY g.period_ending DESC
         LIMIT 1) ast ON (true))
     LEFT JOIN LATERAL ( SELECT g.value
           FROM market.security_segment_latest g
          WHERE ((g.security_id = p.security_id) AND (g.axis = p.axis) AND (g.member_code = p.member_code) AND (g.metric_code = 'long_lived_assets'::text) AND (g.period_type = 'instant'::text) AND (g.partition_id = 1) AND (g.parent_member IS NULL) AND (g.period_ending <= p.period_ending))
          ORDER BY g.period_ending DESC
         LIMIT 1) lla ON (true))
     LEFT JOIN LATERAL ( SELECT g.value
           FROM market.security_segment_latest g
          WHERE ((g.security_id = p.security_id) AND (g.axis = p.axis) AND (g.member_code = p.member_code) AND (g.metric_code = 'goodwill'::text) AND (g.period_type = 'instant'::text) AND (g.partition_id = 1) AND (g.parent_member IS NULL) AND (g.period_ending <= p.period_ending))
          ORDER BY g.period_ending DESC
         LIMIT 1) gw ON (true))
     LEFT JOIN LATERAL ( SELECT al_1.concept_code
           FROM market.segment_alias al_1
          WHERE ((al_1.member_code = p.member_code) AND ((al_1.security_id = p.security_id) OR (al_1.security_id IS NULL)))
          ORDER BY (al_1.security_id IS NOT NULL) DESC
         LIMIT 1) al ON (true))
     LEFT JOIN market.segment_concept c ON ((c.code = al.concept_code)));


--
-- Name: VIEW security_segment_current; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_segment_current IS 'Latest annual revenue and operating income per disclosed business line, with each line''s share of its own split. Restricted to partition 1 — the finest split that reconciles to the filing — so the rows on one (security, axis) can safely be summed. `kind` is the MEMBER''s kind where that is published (a country filed on the business axis is geography), falling back to the axis''s. operating_margin_pct is a SEGMENT margin: it excludes unallocated corporate cost by design and does not roll up to the company''s operating margin.';


--
-- Name: security_segment_spine; Type: MATERIALIZED VIEW; Schema: market; Owner: -
--

CREATE MATERIALIZED VIEW market.security_segment_spine AS
 SELECT security_id,
    axis,
    kind,
    member_code,
    concept_code,
    concept_name,
    revenue,
    operating_income,
    capital_expenditure,
    depreciation,
    cost_of_revenue,
    total_assets,
    operating_margin_pct,
    gross_margin_pct,
    capex_to_depreciation,
    return_on_segment_assets_pct,
    revenue_share_pct,
    currency_code,
    period_ending,
    accession_number,
    reconciled_to,
    country_iso2,
    member_label,
    long_lived_assets,
    goodwill
   FROM market.security_segment_current
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW security_segment_spine; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON MATERIALIZED VIEW market.security_segment_spine IS 'Every business line, materialised. Identical in content to security_segment_current (it is `select *` over it) and refreshed hourly by refresh_facets. Read this for anything that scans more than one security: the live view is 3.8 ms for one security and 6.1 s for all of them.';


--
-- Name: security_share_stats; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_share_stats (
    security_id uuid NOT NULL,
    as_of date NOT NULL,
    float_shares numeric,
    outstanding_shares numeric,
    short_interest numeric,
    short_percent_of_float numeric,
    days_to_cover numeric,
    insider_ownership numeric,
    institution_ownership numeric,
    institutions_count integer,
    source_code text NOT NULL,
    fetched_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE security_share_stats; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_share_stats IS 'Float, shares outstanding, short interest and ownership, keyed on the PROVIDER''s date so a re-fetch updates a period rather than inventing one. Universal and free — measured across US, German, Japanese, Korean and Brazilian listings.';


--
-- Name: COLUMN security_share_stats.short_percent_of_float; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_share_stats.short_percent_of_float IS 'A FRACTION as the provider sends it: 0.0097 is 0.97%. Not converted on write — storing the fact and naming the unit is what stops one reader multiplying by 100 and another not.';


--
-- Name: COLUMN security_share_stats.insider_ownership; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_share_stats.insider_ownership IS 'A FRACTION: 0.01648 is 1.648%. Same convention as short_percent_of_float and institution_ownership.';


--
-- Name: COLUMN security_share_stats.institution_ownership; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_share_stats.institution_ownership IS 'A FRACTION: 0.66482 is 66.482%.';


--
-- Name: security_statement; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_statement (
    security_id uuid NOT NULL,
    statement text NOT NULL,
    period_ending date NOT NULL,
    period_type text DEFAULT 'annual'::text NOT NULL,
    currency text,
    data jsonb NOT NULL,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL,
    derived_at timestamp with time zone
);


--
-- Name: COLUMN security_statement.derived_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.security_statement.derived_at IS 'When this statement was turned into metric rows. NULL means "not yet, or re-fetched since" — the writers null it on every upsert. Exists so the backlog is an indexed lookup rather than a NOT EXISTS over 3.29M metric rows, which cost ~6s against an 8s statement timeout regardless of page size.';


--
-- Name: coverage_current; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.coverage_current AS
 WITH base AS MATERIALIZED (
         SELECT f.security_id,
            f.security_type_code,
            f.symbol,
            f.country_iso2,
            f.sector_id,
            f.industry_code,
            f.cap_band,
            f.style,
            f.msci_tier,
            f.msci_region,
            f.income_group,
            f.currency_code,
            (f.symbol IS NOT NULL) AS has_symbol,
            (f.sector_id IS NOT NULL) AS has_sector,
            (f.industry_code IS NOT NULL) AS has_industry,
            (p30.security_id IS NOT NULL) AS has_price,
            (p7.security_id IS NOT NULL) AS priced_7d,
            (p3.security_id IS NOT NULL) AS priced_3d,
            (pf.symbol IS NOT NULL) AS has_performance,
            (pr.security_id IS NOT NULL) AS has_profile,
            (fu.security_id IS NOT NULL) AS has_fundamentals,
            (st.security_id IS NOT NULL) AS has_statements,
            (mt.security_id IS NOT NULL) AS has_metrics,
            (f2.price_history_from IS NOT NULL) AS has_price_history,
            (f2.daily_history_from IS NOT NULL) AS has_daily_history,
            (nw.security_id IS NOT NULL) AS has_news,
            (of.security_id IS NOT NULL) AS has_leadership,
            (it.security_id IS NOT NULL) AS has_insider,
            (fl.security_id IS NOT NULL) AS has_filings,
            (dv.security_id IS NOT NULL) AS has_dividends,
            (ss.security_id IS NOT NULL) AS has_share_stats,
            (es.security_id IS NOT NULL) AS has_estimates,
            (qt.security_id IS NOT NULL) AS has_quarters,
            (f2.sic IS NOT NULL) AS has_sic,
            (sd.capability = 'held'::text) AS segment_capable,
            (sd.capability = 'resolvable'::text) AS segment_resolvable,
            COALESCE(sd.segment_source, 'none'::text) AS segment_source,
            (sg.security_id IS NOT NULL) AS has_segments,
            (gg.security_id IS NOT NULL) AS has_segment_geography,
            (wi.security_id IS NOT NULL) AS has_weighted_industry
           FROM (((((((((((((((((((((market.security_facets f
             LEFT JOIN ( SELECT DISTINCT security_price.security_id
                   FROM market.security_price
                  WHERE (security_price.date > (CURRENT_DATE - 30))) p30 USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_price.security_id
                   FROM market.security_price
                  WHERE (security_price.date > (CURRENT_DATE - 7))) p7 USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_price.security_id
                   FROM market.security_price
                  WHERE (security_price.date > (CURRENT_DATE - 3))) p3 USING (security_id))
             LEFT JOIN ( SELECT DISTINCT performance.scope_id AS symbol
                   FROM market.performance
                  WHERE (performance.scope = 'instrument'::text)) pf ON ((pf.symbol = f.symbol)))
             LEFT JOIN market.security f2 USING (security_id))
             LEFT JOIN market.security_disclosure sd USING (security_id))
             LEFT JOIN ( SELECT DISTINCT news_security.security_id
                   FROM market.news_security) nw USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_officer.security_id
                   FROM market.security_officer) of USING (security_id))
             LEFT JOIN ( SELECT DISTINCT insider_trade.security_id
                   FROM market.insider_trade) it USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_filing.security_id
                   FROM market.security_filing) fl USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_corporate_action.security_id
                   FROM market.security_corporate_action
                  WHERE (security_corporate_action.kind = 'dividend'::text)) dv USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_share_stats.security_id
                   FROM market.security_share_stats) ss USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_estimate.security_id
                   FROM market.security_estimate) es USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_statement.security_id
                   FROM market.security_statement
                  WHERE (security_statement.period_type = 'quarter'::text)) qt USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_profile.security_id
                   FROM market.security_profile) pr USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_segment_spine.security_id
                   FROM market.security_segment_spine) sg USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_segment_spine.security_id
                   FROM market.security_segment_spine
                  WHERE (security_segment_spine.kind = 'geography'::text)) gg USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_taxonomy.security_id
                   FROM market.security_taxonomy
                  WHERE (security_taxonomy.source_code = ANY (ARRAY['segment-revenue'::text, 'segment-profit'::text]))) wi USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_fundamentals.security_id
                   FROM market.security_fundamentals) fu USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_statement.security_id
                   FROM market.security_statement) st USING (security_id))
             LEFT JOIN ( SELECT DISTINCT security_metric.security_id
                   FROM market.security_metric) mt USING (security_id))
        ), facet_status AS (
         SELECT base.security_id,
            base.security_type_code,
            'symbol'::text AS facet,
            base.has_symbol AS present
           FROM base
        UNION ALL
         SELECT base.security_id,
            base.security_type_code,
            'sector'::text,
            base.has_sector
           FROM base
        UNION ALL
         SELECT base.security_id,
            base.security_type_code,
            'industry'::text,
            base.has_industry
           FROM base
        UNION ALL
         SELECT base.security_id,
            base.security_type_code,
            'price'::text,
            base.has_price
           FROM base
        UNION ALL
         SELECT base.security_id,
            base.security_type_code,
            'performance'::text,
            base.has_performance
           FROM base
        UNION ALL
         SELECT base.security_id,
            base.security_type_code,
            'profile'::text,
            base.has_profile
           FROM base
        UNION ALL
         SELECT base.security_id,
            base.security_type_code,
            'fundamentals'::text,
            base.has_fundamentals
           FROM base
        UNION ALL
         SELECT base.security_id,
            base.security_type_code,
            'statements'::text,
            base.has_statements
           FROM base
        UNION ALL
         SELECT base.security_id,
            base.security_type_code,
            'metrics'::text,
            base.has_metrics
           FROM base
        ), all_facets AS (
         SELECT base.security_id,
            'symbol'::text AS facet,
            base.has_symbol AS present,
            true AS applicable
           FROM base
        UNION ALL
         SELECT base.security_id,
            'sector'::text,
            base.has_sector,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'industry'::text,
            base.has_industry,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'price'::text,
            base.has_price,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'performance'::text,
            base.has_performance,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'profile'::text,
            base.has_profile,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'fundamentals'::text,
            base.has_fundamentals,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'statements'::text,
            base.has_statements,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'metrics'::text,
            base.has_metrics,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'price_history'::text,
            base.has_price_history,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'daily_history'::text,
            base.has_daily_history,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'news'::text,
            base.has_news,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'leadership'::text,
            base.has_leadership,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'insider'::text,
            base.has_insider,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'filings'::text,
            base.has_filings,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'dividends'::text,
            base.has_dividends,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'share_stats'::text,
            base.has_share_stats,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'estimates'::text,
            base.has_estimates,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'quarters'::text,
            base.has_quarters,
            true
           FROM base
        UNION ALL
         SELECT base.security_id,
            'sic'::text,
            base.has_sic,
            base.segment_capable
           FROM base
        UNION ALL
         SELECT base.security_id,
            'segments'::text,
            base.has_segments,
            base.segment_capable
           FROM base
        UNION ALL
         SELECT base.security_id,
            'segment_geography'::text,
            base.has_segment_geography,
            base.segment_capable
           FROM base
        UNION ALL
         SELECT base.security_id,
            'weighted_industry'::text,
            base.has_weighted_industry,
            base.segment_capable
           FROM base
        ), richness AS (
         SELECT all_facets.security_id,
            count(*) FILTER (WHERE (all_facets.present AND all_facets.applicable)) AS present_facets,
            count(*) FILTER (WHERE all_facets.applicable) AS applicable_facets
           FROM all_facets
          GROUP BY all_facets.security_id
        ), completeness AS (
         SELECT fs.security_id,
            bool_and((fs.present OR (NOT COALESCE(rf.required, false)))) AS complete
           FROM (facet_status fs
             LEFT JOIN market.required_facet rf ON (((rf.security_type_code = fs.security_type_code) AND (rf.facet = fs.facet))))
          GROUP BY fs.security_id
        ), dims AS (
         SELECT 'country'::text AS dimension,
            b.country_iso2 AS bucket,
            b.security_id,
            b.security_type_code,
            b.symbol,
            b.country_iso2,
            b.sector_id,
            b.industry_code,
            b.cap_band,
            b.style,
            b.msci_tier,
            b.msci_region,
            b.income_group,
            b.currency_code,
            b.has_symbol,
            b.has_sector,
            b.has_industry,
            b.has_price,
            b.priced_7d,
            b.priced_3d,
            b.has_performance,
            b.has_profile,
            b.has_fundamentals,
            b.has_statements,
            b.has_metrics,
            b.has_price_history,
            b.has_daily_history,
            b.has_news,
            b.has_leadership,
            b.has_insider,
            b.has_filings,
            b.has_dividends,
            b.has_share_stats,
            b.has_estimates,
