            b.segment_capable,
            b.segment_resolvable,
            b.segment_source,
            b.has_segments,
            b.has_segment_geography,
            b.has_weighted_industry
           FROM base b
        UNION ALL
         SELECT 'sector'::text,
            b.sector_id,
