);


--
-- Name: COLUMN currency.history_missing_at; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.currency.history_missing_at IS 'Set when the provider was asked for ten years of weekly rates and returned no usable history — Yahoo carries a single bar for some minor pairs. Re-asked after 30 days: a pair not quoted today may be quoted next quarter.';


--
-- Name: currency_repair; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.currency_repair (
    security_id uuid NOT NULL,
    repaired_at timestamp with time zone DEFAULT now() NOT NULL,
