--
-- Name: TABLE currency_repair; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.currency_repair IS 'Every automated change to security.currency_code, with the value it replaced. A repair that cannot be undone from the database itself is not a repair — the first version of migration 74 overwrote 233 rows with no record and was only recoverable by accident.';


--
-- Name: dart_discovery_cursor; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.dart_discovery_cursor (
    singleton boolean DEFAULT true NOT NULL,
    window_end date,
    cls text DEFAULT 'Y'::text NOT NULL,
    page integer DEFAULT 1 NOT NULL,
    mapped_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dart_discovery_cursor_cls_check CHECK ((cls = ANY (ARRAY['Y'::text, 'K'::text]))),
    CONSTRAINT dart_discovery_cursor_page_check CHECK ((page >= 1)),
    CONSTRAINT dart_discovery_cursor_singleton_check CHECK (singleton)
);


--
-- Name: pending_industry; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_industry AS
 SELECT s.security_id,
    COALESCE(ps.symbol, t.value) AS symbol,
    sec_n.code AS sector_id,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((((market.security s
     JOIN market.security_taxonomy sec_st ON ((sec_st.security_id = s.security_id)))
     JOIN market.taxonomy_node sec_n ON (((sec_n.node_id = sec_st.node_id) AND (sec_n.taxonomy_id = 'muffin'::text) AND (sec_n.level = 1))))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((NOT (EXISTS ( SELECT 1
           FROM (market.security_taxonomy ind_st
             JOIN market.taxonomy_node ind_n ON (((ind_n.node_id = ind_st.node_id) AND (ind_n.taxonomy_id = 'muffin'::text) AND (ind_n.level = 2))))
          WHERE (ind_st.security_id = s.security_id)))) AND (COALESCE(ps.symbol, t.value) IS NOT NULL) AND ((s.industry_missing_at IS NULL) OR (s.industry_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, COALESCE(ps.symbol, t.value), sec_n.code
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: VIEW pending_industry; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_industry IS 'Securities with a sector but no sub-industry, heaviest fund weight first. The "no industry" half is a not-exists over the SECURITY: expressing it as a left join plus "is null" filters rows rather than securities, and a security keeps qualifying through its own level-1 rows (see 31-pending-industry-antijoin.sql).';


--
-- Name: sector_constituents; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.sector_constituents AS
 SELECT DISTINCT ON (tn.code, s.security_id) tn.code AS sector_id,
    s.security_id,
    s.name,
    sym.symbol,
    COALESCE(s.provider_country_iso2, s.country_iso2) AS country_iso2,
    ind.name AS industry,
    h.weight,
    h.fund_symbol,
    s.market_cap,
    s.currency_code,
    h.market_value,
    h.as_of
   FROM ((((((market.security_taxonomy st
     JOIN market.taxonomy_node tn ON (((tn.node_id = st.node_id) AND (tn.taxonomy_id = 'muffin'::text) AND (tn.level = 1))))
     JOIN market.data_source ds ON ((ds.code = st.source_code)))
     JOIN market.security s ON ((s.security_id = st.security_id)))
     LEFT JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
     LEFT JOIN LATERAL ( SELECT n.name
           FROM (market.security_taxonomy st2
             JOIN market.taxonomy_node n ON (((n.node_id = st2.node_id) AND (n.taxonomy_id = 'muffin'::text) AND (n.level = 2) AND (n.parent_id = tn.node_id))))
          WHERE (st2.security_id = s.security_id)
         LIMIT 1) ind ON (true))
     LEFT JOIN LATERAL ( SELECT h_1.weight,
            h_1.market_value,
            h_1.as_of,
            fi.value AS fund_symbol
           FROM ((market.fund_holding_current h_1
             JOIN market.security_identifier fi ON (((fi.security_id = h_1.fund_id) AND (fi.kind_code = 'ticker'::text))))
             JOIN market.tracked_fund tf ON (((tf.symbol = fi.value) AND (tf.represents_code = tn.code))))
          WHERE (h_1.security_id = s.security_id)
         LIMIT 1) h ON (true))
  ORDER BY tn.code, s.security_id, ds.priority DESC, st.as_of DESC;


--
-- Name: data_defect; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.data_defect AS
 SELECT 'placeholder_cusip'::text AS defect,
    count(*) AS n,
    'security_identifier rows with the all-zero CUSIP placeholder'::text AS detail
   FROM market.security_identifier
  WHERE ((security_identifier.kind_code = 'cusip'::text) AND (security_identifier.value = '000000000'::text))
UNION ALL
 SELECT 'placeholder_isin'::text AS defect,
    count(*) AS n,
    'security_identifier rows with the all-zero ISIN placeholder'::text AS detail
   FROM market.security_identifier
  WHERE ((security_identifier.kind_code = 'isin'::text) AND (security_identifier.value = '000000000000'::text))
UNION ALL
 SELECT 'duplicate_constituents'::text AS defect,
    COALESCE(sum((q.rows_ - q.distinct_)), (0)::numeric) AS n,
    'sector_constituents rows beyond one per security, across ALL sectors'::text AS detail
   FROM ( SELECT sector_constituents.sector_id,
            count(*) AS rows_,
            count(DISTINCT sector_constituents.security_id) AS distinct_
           FROM market.sector_constituents
          GROUP BY sector_constituents.sector_id) q
UNION ALL
 SELECT 'returns_at_minus_100'::text AS defect,
    count(*) AS n,
    'performance rows at exactly -100% — a zero close became a total loss'::text AS detail
   FROM market.performance
  WHERE ((performance.scope = 'instrument'::text) AND (performance.change_pct = ('-100'::integer)::numeric))
UNION ALL
 SELECT 'frozen_series'::text AS defect,
    count(*) AS n,
    'symbols whose FRESH refresh is 0.00% on every period it produced (3+ periods)'::text AS detail
   FROM ( SELECT performance.scope_id
           FROM market.performance
          WHERE ((performance.scope = 'instrument'::text) AND (performance.as_of > (now() - '2 days'::interval)))
          GROUP BY performance.scope_id
         HAVING ((count(*) FILTER (WHERE (performance.change_pct = (0)::numeric)) >= 3) AND (count(*) FILTER (WHERE ((performance.change_pct IS NOT NULL) AND (performance.change_pct <> (0)::numeric))) = 0))) q
UNION ALL
 SELECT 'contradicted_negative_cache'::text AS defect,
    count(*) AS n,
    'securities marked as having no returns while holding recent bars that MOVE'::text AS detail
   FROM market.security s
  WHERE ((s.performance_missing_at IS NOT NULL) AND (( SELECT count(DISTINCT p.close) AS count
           FROM market.security_price p
          WHERE ((p.security_id = s.security_id) AND (p.date > (CURRENT_DATE - 30)))) > 1) AND (EXISTS ( SELECT 1
           FROM market.security_price p
          WHERE ((p.security_id = s.security_id) AND (p.date > (CURRENT_DATE - 7))))))
UNION ALL
 SELECT 'country_with_no_symbols'::text AS defect,
    count(*) AS n,
    'countries with 20+ equities and not one provider symbol'::text AS detail
   FROM ( SELECT s.country_iso2
           FROM market.security s
          WHERE ((s.security_type_code = 'equity'::text) AND (s.country_iso2 IS NOT NULL))
          GROUP BY s.country_iso2
         HAVING ((count(*) >= 20) AND (NOT (EXISTS ( SELECT 1
                   FROM market.security s2
                  WHERE ((s2.country_iso2 = s.country_iso2) AND ((EXISTS ( SELECT 1
                           FROM market.security_provider_symbol sp
                          WHERE (sp.security_id = s2.security_id))) OR (EXISTS ( SELECT 1
                           FROM market.security_identifier i
                          WHERE ((i.security_id = s2.security_id) AND (i.kind_code = 'ticker'::text))))))))))) q
UNION ALL
 SELECT 'queued_but_already_done'::text AS defect,
    count(*) AS n,
    'securities in pending_industry that already have a level-2 industry'::text AS detail
   FROM market.pending_industry pi
  WHERE (EXISTS ( SELECT 1
           FROM (market.security_taxonomy st
             JOIN market.taxonomy_node tn ON ((tn.node_id = st.node_id)))
          WHERE ((st.security_id = pi.security_id) AND (tn.level = 2))))
UNION ALL
 SELECT 'extreme_1y_returns'::text AS defect,
    count(*) AS n,
    'GAUGE not an invariant: 1y returns >= +1000%, expected non-zero and stable'::text AS detail
   FROM market.performance
  WHERE ((performance.scope = 'instrument'::text) AND (performance.period = '1y'::text) AND (performance.change_pct >= (1000)::numeric));


--
-- Name: earnings_calendar; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.earnings_calendar (
    symbol text NOT NULL,
    report_date date NOT NULL,
    security_id uuid,
    name text,
    eps_consensus numeric,
    eps_previous numeric,
    num_estimates integer,
    period_ending text,
    reporting_time text,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE earnings_calendar; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.earnings_calendar IS 'Upcoming and recent earnings dates from `equity/calendar/earnings`, which takes a DATE RANGE rather than a symbol — one call covers ~116 companies. A rolling refresh, not a backlog: the horizon moves and dates are rescheduled, so each run re-reads the whole forward window and the newest answer wins.';


--
-- Name: earnings_history_cursor; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.earnings_history_cursor (
    only_row boolean DEFAULT true NOT NULL,
    walked_to date DEFAULT CURRENT_DATE NOT NULL,
    stop_at date DEFAULT '2015-01-01'::date NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT earnings_history_cursor_only_row_check CHECK (only_row)
);


--
-- Name: TABLE earnings_history_cursor; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.earnings_history_cursor IS 'How far back the earnings-history sweep has walked. A POSITION, not a negative cache: the resource sweeps a calendar rather than asking about entities.';


--
-- Name: exchange; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.exchange (
    exch_code text NOT NULL,
    country_iso2 text,
    suffix text NOT NULL,
    preference integer DEFAULT 1 NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    notes text,
    promotion_tier integer DEFAULT 9 NOT NULL,
    promotion_enabled boolean DEFAULT false NOT NULL
);


--
-- Name: TABLE exchange; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.exchange IS 'Venue catalog: OpenFIGI/Bloomberg exchange code -> country -> the suffix the price provider uses. Source of truth for both local-symbol resolution and the exchange sweep. Adding a venue is a row.';


--
-- Name: COLUMN exchange.suffix; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.exchange.suffix IS 'Appended to the local ticker for the price provider. Empty string for US, which is why it is NOT NULL rather than nullable — an absent suffix and a US listing are different facts.';


--
-- Name: COLUMN exchange.preference; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.exchange.preference IS 'Order within a country, lowest first. Korea lists KOSPI (1) before KOSDAQ (2) so a mid-cap on the secondary board still resolves, but the primary board wins when both answer.';


--
-- Name: COLUMN exchange.promotion_tier; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.exchange.promotion_tier IS 'Promotion order, lowest first. Ranks HOME MARKETS ahead of cross-listing venues: measured 2026-08-19, 18.3% of Frankfurt''s untracked listings name a company already held (against 0.5% for the US), because composite_figi is per country of listing and cannot see that the company is already tracked.';


--
-- Name: COLUMN exchange.promotion_enabled; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.exchange.promotion_enabled IS 'Opt-in per venue. FALSE by default on purpose — 92,826 listings are untracked and every downstream backlog shares one rate-limited provider budget, so promotion must be a decision someone takes, not something a deploy starts.';


--
-- Name: exchange_cursor; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.exchange_cursor (
    exch_code text NOT NULL,
    country_iso2 text,
    suffix text,
    enabled boolean DEFAULT true NOT NULL,
    next_cursor text,
    last_run_at timestamp with time zone,
    listings integer DEFAULT 0 NOT NULL,
    security_type text DEFAULT 'Common Stock'::text NOT NULL,
    query_prefix text
);


--
-- Name: COLUMN exchange_cursor.security_type; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.exchange_cursor.security_type IS 'Which OpenFIGI securityType2 this venue is currently enumerating. A venue is finished when it has completed every type in market.exchange_sweep_type, not merely the first.';


--
-- Name: COLUMN exchange_cursor.query_prefix; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.exchange_cursor.query_prefix IS 'The ticker prefix currently being enumerated, or NULL to sweep the venue whole. Set only when a venue+type exceeds OpenFIGI''s 15,000-row paging ceiling — Athens does not need slicing, the US does.';


--
-- Name: exchange_listing; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.exchange_listing (
    figi text NOT NULL,
    composite_figi text,
    exch_code text NOT NULL,
    ticker text NOT NULL,
    name text,
    security_type text,
    country_iso2 text,
    provider_symbol text,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    figi_security_type text
);


--
-- Name: COLUMN exchange_listing.figi_security_type; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.exchange_listing.figi_security_type IS 'OpenFIGI securityType (FINE). The only one that identifies a fund: an ETF is securityType ETP inside securityType2 Mutual Fund, so security_type alone cannot tell an exchange-traded fund from an open-end one. Null for rows catalogued before 2026-08-17; they carry it on their next sweep.';


--
-- Name: exchange_sweep_partition; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.exchange_sweep_partition (
    prefix text NOT NULL,
    sort_order integer NOT NULL
);


--
-- Name: exchange_sweep_type; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.exchange_sweep_type (
    security_type text NOT NULL,
    sort_order integer NOT NULL,
    notes text,
    figi_field text DEFAULT 'securityType2'::text NOT NULL,
    CONSTRAINT exchange_sweep_type_figi_field_ck CHECK ((figi_field = ANY (ARRAY['securityType'::text, 'securityType2'::text])))
);


--
-- Name: COLUMN exchange_sweep_type.figi_field; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.exchange_sweep_type.figi_field IS 'Which OpenFIGI field this type filters on. securityType2 is the coarse bucket (Common Stock, Depositary Receipt); securityType is the fine one, and ETP is only reachable through it — its coarse bucket is Mutual Fund, 44,119 US rows of mostly open-end funds, over the 15,000 paging ceiling.';


--
-- Name: filer_profile; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.filer_profile (
    security_id uuid NOT NULL,
    entity_type text,
    owner_org text,
    ein text,
    lei text,
    category text,
    fiscal_year_end text,
    state_of_incorporation text,
    website text,
    investor_website text,
    phone text,
    us_ticker text,
    us_exchange text,
    hq_street text,
    hq_city text,
    hq_state_or_country text,
    hq_zip text,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE filer_profile; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.filer_profile IS 'What a registrant told the SEC about itself, from the submissions response `security-filing-history` already fetches. Separate from `security_profile`, which holds a PROVIDER''s view of the same company and is keyed so only one writer can own it.';


--
-- Name: COLUMN filer_profile.ein; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.filer_profile.ein IS 'Employer Identification Number. SEC''s `000000000` placeholder is rejected at parse rather than stored — the same shape as `<cusip>000000000</cusip>`, which once collapsed four unrelated companies into one security.';


--
-- Name: COLUMN filer_profile.us_ticker; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.filer_profile.us_ticker IS 'The registrant''s own US ticker. Authoritative, unlike the OpenFIGI US lookup this pipeline otherwise relies on, which returns the thin OTC foreign-ordinary line (TSMWF, ASMLF, BUDFF) for most foreign companies.';


--
-- Name: filing_form; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.filing_form (
    source_code text NOT NULL,
    form_code text NOT NULL,
    is_annual boolean NOT NULL,
    carries_segments boolean DEFAULT true NOT NULL
);


--
-- Name: TABLE filing_form; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.filing_form IS 'Forms that carry audited accounts, per regulator. A 6-K or 8-K is an EVENT, not accounts, and a foreign private issuer files 20-F/40-F INSTEAD OF 10-K/10-Q rather than as well — so a rule classifying filings must know both vocabularies or every foreign annual report is labelled an event.';


--
-- Name: fund_country_weight; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.fund_country_weight AS
 SELECT fi.value AS fund_symbol,
    COALESCE(s.provider_country_iso2, s.country_iso2, 'XX'::text) AS country_iso2,
    sum(h.weight) AS weight,
    round((((100)::numeric * sum(h.weight)) / NULLIF(sum(sum(h.weight)) OVER (PARTITION BY fi.value), (0)::numeric)), 4) AS weight_pct,
    max(h.as_of) AS as_of
   FROM ((market.fund_holding_current h
     JOIN market.security_identifier fi ON (((fi.security_id = h.fund_id) AND (fi.kind_code = 'ticker'::text))))
     JOIN market.security s ON ((s.security_id = h.security_id)))
  WHERE (h.security_id <> h.fund_id)
  GROUP BY fi.value, COALESCE(s.provider_country_iso2, s.country_iso2, 'XX'::text);


--
-- Name: fund_holdings; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.fund_holdings AS
 SELECT fi.value AS fund_symbol,
    h.security_id,
    s.name,
    sym.symbol,
    s.country_iso2,
    s.security_type_code,
    s.currency_code,
    h.weight,
    h.market_value,
    h.as_of
   FROM (((market.fund_holding_current h
     JOIN market.security_identifier fi ON (((fi.security_id = h.fund_id) AND (fi.kind_code = 'ticker'::text))))
     JOIN market.security s ON ((s.security_id = h.security_id)))
     LEFT JOIN market.security_symbol sym ON ((sym.security_id = h.security_id)))
  WHERE (h.security_id <> h.fund_id);


--
-- Name: VIEW fund_holdings; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.fund_holdings IS 'Everything a tracked fund holds, heaviest first when ordered by weight. The counterpart of security_funds — same join, read from the other end.';


--
-- Name: fund_sector_weight; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.fund_sector_weight AS
 WITH classified AS (
         SELECT DISTINCT ON (st.security_id) st.security_id,
            tn.code
           FROM ((market.security_taxonomy st
             JOIN market.taxonomy_node tn ON (((tn.node_id = st.node_id) AND (tn.taxonomy_id = 'muffin'::text) AND (tn.level = 1))))
             JOIN market.data_source ds ON ((ds.code = st.source_code)))
          ORDER BY st.security_id, ds.priority DESC, st.as_of DESC
        )
 SELECT fi.value AS fund_symbol,
    COALESCE(c.code, 'unclassified'::text) AS sector_id,
    sum(h.weight) AS weight,
    round((((100)::numeric * sum(h.weight)) / NULLIF(sum(sum(h.weight)) OVER (PARTITION BY fi.value), (0)::numeric)), 4) AS weight_pct,
    max(h.as_of) AS as_of
   FROM (((market.fund_holding_current h
     JOIN market.security_identifier fi ON (((fi.security_id = h.fund_id) AND (fi.kind_code = 'ticker'::text))))
     JOIN market.security s ON (((s.security_id = h.security_id) AND (s.security_type_code = 'equity'::text))))
     LEFT JOIN classified c ON ((c.security_id = h.security_id)))
  WHERE (h.security_id <> h.fund_id)
  GROUP BY fi.value, COALESCE(c.code, 'unclassified'::text);


--
-- Name: VIEW fund_sector_weight; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.fund_sector_weight IS 'Sector weights within a fund, over its EQUITY holdings only. Percentages renormalise over those holdings, so a fund that is part bonds sums to 100% across the equities it does hold — weights do not sum to 100 in the filings either (EWT sums to 110.38).';


--
-- Name: identifier_kind; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.identifier_kind (
    code text NOT NULL,
    name text NOT NULL,
    is_global_unique boolean DEFAULT true NOT NULL
);


--
-- Name: ingest_run; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.ingest_run (
    run_id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_code text,
    resource text NOT NULL,
    scope text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    ok boolean,
    securities_added integer DEFAULT 0 NOT NULL,
    holdings_written integer DEFAULT 0 NOT NULL,
    error text
);


--
-- Name: instruments; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.instruments (
    symbol text NOT NULL,
    name text,
    sector_id text,
    provider_sector text,
    industry text,
    country text,
    market_cap numeric,
    currency text,
    asset_type text DEFAULT 'equity'::text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone,
    price_symbol text,
    priced boolean DEFAULT true NOT NULL,
    security_id uuid
);


--
-- Name: COLUMN instruments.price_symbol; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.instruments.price_symbol IS 'Symbol the price provider knows, when it differs from the display ticker (e.g. NESN -> NESN.SW on yfinance). NULL means they are the same.';


--
-- Name: COLUMN instruments.priced; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.instruments.priced IS 'False when a price return is meaningless (cash, a bond yield). The refresh skips these and the UI shows no number rather than an invented or misleading one.';


--
-- Name: COLUMN instruments.security_id; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.instruments.security_id IS 'The fund-derived security this curated instrument refers to, where one exists. NULL for cash, yields, crypto and commodities, which are not securities. Auto-linked by any name the security is known by; the ADR picks (TSM -> Taiwan Semiconductor) must be set by hand in Studio, and survive a redeploy because this table is seeded `on conflict do nothing`.';


--
-- Name: instrument_current; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.instrument_current AS
 SELECT i.symbol,
    COALESCE(i.name, s.name) AS name,
    i.asset_type,
    i.priced,
    i.sort_order,
    i.price_symbol,
    i.security_id,
    COALESCE(s.sector_id, i.sector_id) AS sector_id,
    COALESCE(s.industry, i.industry) AS industry,
    COALESCE(s.country_name, i.country) AS country,
    COALESCE(s.market_cap, i.market_cap) AS market_cap,
    COALESCE(s.currency_code, i.currency) AS currency,
    i.provider_sector,
    i.updated_at
   FROM (market.instruments i
     LEFT JOIN market.security_current s ON ((s.security_id = i.security_id)));


--
-- Name: VIEW instrument_current; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.instrument_current IS 'The curated instrument list, enriched from the linked security where there is one. Curated columns win for editorial fields (asset_type, priced, sort_order, symbol); provider-refreshed fields (market cap, currency, sector, industry) come from the security so a linked instrument does not go stale.';


--
-- Name: issuer_category; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.issuer_category (
    code text NOT NULL,
    name text NOT NULL
);


--
-- Name: macro_indicator; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.macro_indicator (
    code text NOT NULL,
    name text NOT NULL,
    category text NOT NULL,
    route text NOT NULL,
    provider text NOT NULL,
    params jsonb DEFAULT '{}'::jsonb NOT NULL,
    country_iso2 text,
    provider_country text,
    frequency text,
    unit text,
    value_is_fraction boolean DEFAULT false NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 100 NOT NULL,
    notes text
);


--
-- Name: TABLE macro_indicator; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.macro_indicator IS 'The macro series this deployment serves, as a CONTROL TABLE — adding one is a row, never a migration, the same shape as tracked_fund. Only series MEASURED to return rows are seeded: econdb''s 4,506-indicator catalogue is free but its data returns 204 without a key, so nothing here depends on it.';


--
-- Name: COLUMN macro_indicator.provider_country; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.macro_indicator.provider_country IS 'The country value the PROVIDER wants (`united_states`) — not the ISO2 code and not the display name. The catalogue''s own "United States" contains a space and is not a usable value.';


--
-- Name: COLUMN macro_indicator.unit; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.macro_indicator.unit IS 'How to render the value. `percent` for a rate, `index` for a genuine index level, or a THREE-LETTER CURRENCY CODE where the value is money — OECD returns GDP in each country''s national currency, so this cannot be a boolean and must not default to dollars.';


--
-- Name: COLUMN macro_indicator.notes; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.macro_indicator.notes IS 'Why a series is disabled, kept instead of deleting the row — the record that an id was tried and failed is what stops the next person re-adding it. Never cleared by a seed''s on-conflict.';


--
-- Name: macro_observation; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.macro_observation (
    indicator_code text NOT NULL,
    as_of date NOT NULL,
    dimension text DEFAULT ''::text NOT NULL,
    value numeric NOT NULL,
    fetched_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE macro_observation; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.macro_observation IS 'One value per (series, date, dimension). `dimension` carries a yield curve''s maturity and is empty for scalar series, so a term structure and a single number share one table.';


--
-- Name: macro_current; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.macro_current AS
 SELECT DISTINCT ON (i.code, o.dimension) i.code,
    i.name,
    i.category,
    i.country_iso2,
    i.unit,
    i.frequency,
    o.dimension,
        CASE
            WHEN i.value_is_fraction THEN round((o.value * (100)::numeric), 4)
            ELSE o.value
        END AS value,
    o.as_of,
    o.fetched_at
   FROM (market.macro_indicator i
     JOIN market.macro_observation o ON ((o.indicator_code = i.code)))
  WHERE i.enabled
  ORDER BY i.code, o.dimension, o.as_of DESC;


--
-- Name: VIEW macro_current; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.macro_current IS 'The latest value of every enabled macro series, already converted to its stated unit — OECD sends inflation as a fraction (0.0239) and the app wants percent, and that conversion belongs next to the series rather than in every reader.';


--
-- Name: metric; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.metric (
    code text NOT NULL,
    name text NOT NULL,
    category text NOT NULL,
    unit text NOT NULL,
    is_derived boolean DEFAULT false NOT NULL,
    sort_order integer DEFAULT 100 NOT NULL,
    notes text,
    is_flow boolean DEFAULT false NOT NULL,
    min_plausible numeric,
    max_plausible numeric
);


--
-- Name: TABLE metric; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.metric IS 'The metrics this deployment can chart, as a CONTROL TABLE — adding one is a row, the same shape as tracked_fund and macro_indicator. Holds INPUTS the filing reports; ratios are derived over price x metric rather than stored, so the two numbers behind a P/E stay visible.';


--
-- Name: COLUMN metric.is_flow; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.metric.is_flow IS 'True when the metric ACCUMULATES over a period and may be summed into a TTM — income-statement and cash-flow lines. False for instants: total assets over four quarters is four times the company, not a year of it.';


--
-- Name: COLUMN metric.min_plausible; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.metric.min_plausible IS 'Lowest value that is not obviously wrong. NULL = unbounded. Read by market.data_defect.';


--
-- Name: COLUMN metric.max_plausible; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.metric.max_plausible IS 'Highest value that is not obviously wrong. NULL = unbounded. Read by market.data_defect.';


--
-- Name: metric_out_of_range; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.metric_out_of_range AS
 SELECT m.code AS metric_code,
    count(*) AS n
   FROM (market.security_metric sm
     JOIN market.metric m ON ((m.code = sm.metric_code)))
  WHERE (((m.min_plausible IS NOT NULL) AND (sm.value < m.min_plausible)) OR ((m.max_plausible IS NOT NULL) AND (sm.value > m.max_plausible)))
  GROUP BY m.code;


--
-- Name: metric_source_field; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.metric_source_field (
    metric_code text NOT NULL,
    source_code text NOT NULL,
    statement text NOT NULL,
    field text NOT NULL
);


--
-- Name: TABLE metric_source_field; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.metric_source_field IS 'How each provider spells each metric. Measured, not assumed: sec and yfinance share 4 of 40 income-statement field names, and one of the four is period_ending. A hardcoded lookup or a case-over-providers would be the same fact in two places.';


--
-- Name: news_article; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.news_article (
    url text NOT NULL,
    published_at timestamp with time zone NOT NULL,
    title text NOT NULL,
    source text,
    summary text,
    first_seen timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE news_article; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.news_article IS 'One row per article, keyed on its URL. 11% of articles are returned for more than one security (measured), and a market-wide story is attached to hundreds — storing it once is the difference between one row and hundreds of copies free to drift apart. `text` is not stored: it was byte-identical to `summary` in all 200 rows measured.';


--
-- Name: one_shot; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.one_shot (
    key text NOT NULL,
    applied_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text
);


--
-- Name: TABLE one_shot; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.one_shot IS 'Data repairs that must run ONCE, in a migration set that is re-applied on every deploy. Schema changes do not belong here — they are idempotent already.';


--
-- Name: pending_cn_filings; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_cn_filings AS
 SELECT s.security_id,
    l.symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((market.security s
     JOIN market.listing l ON ((l.security_id = s.security_id)))
     LEFT JOIN market.security_filer sf ON (((sf.security_id = s.security_id) AND (sf.source_code = 'cninfo'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (s.country_iso2 = 'CN'::text) AND (l.symbol ~ '^[0-9]{6}$'::text) AND ((sf.history_walked_at IS NULL) OR (sf.history_walked_at < (now() - '180 days'::interval))))
  GROUP BY s.security_id, l.symbol
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, l.symbol;


--
-- Name: VIEW pending_cn_filings; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_cn_filings IS 'Chinese equities whose CNINFO annual-report links have not been fetched in 180 days. Links only — China is measured NOT viable for segments (migration 183), every filing being a PDF — so rows land with is_xbrl = false and the form is not marked carries_segments, keeping them out of every parse backlog.';


--
-- Name: segment_parser; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.segment_parser (
    singleton boolean DEFAULT true NOT NULL,
    version smallint NOT NULL,
    CONSTRAINT segment_parser_singleton_check CHECK (singleton)
);


--
-- Name: TABLE segment_parser; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.segment_parser IS 'One row. Bumping `version` re-queues every filing for segment parsing — the supported way to pick up a newly added `segment_axis` without a deploy or a hand-written update.';


--
-- Name: pending_cn_segments; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_cn_segments AS
 SELECT security_id,
    accession_number,
    report_type,
    report_date,
    report_url,
    best_weight,
    round
   FROM ( SELECT f.security_id,
            f.accession_number,
            f.report_type,
            f.report_date,
            f.report_url,
            COALESCE(max(h.weight), (0)::numeric) AS best_weight,
            ((f.segments_parsed_at IS NULL) OR (COALESCE((f.segments_parser_version)::integer, 0) < ( SELECT p.version
                   FROM market.segment_parser p))) AS needs_work,
            row_number() OVER (PARTITION BY f.security_id ORDER BY f.report_date DESC NULLS LAST, f.accession_number) AS round
           FROM (market.security_filing f
             LEFT JOIN market.fund_holding_current h ON ((h.security_id = f.security_id)))
          WHERE ((f.source_code = 'cninfo'::text) AND (f.report_url IS NOT NULL) AND (EXISTS ( SELECT 1
                   FROM market.filing_form ff
                  WHERE ((ff.source_code = 'cninfo'::text) AND (ff.form_code = f.report_type) AND ff.carries_segments))))
          GROUP BY f.security_id, f.accession_number, f.report_type, f.report_date, f.report_url, f.segments_parsed_at, f.segments_parser_version) ranked
  WHERE needs_work
  ORDER BY round, best_weight DESC, accession_number;


--
-- Name: VIEW pending_cn_segments; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_cn_segments IS 'Chinese annual reports whose PDF has not been read for segment facts. Only `年度报告` is eligible — the summary and the English edition have their own form codes and carry no segment table. `round` is the filing''s STABLE depth into its own company''s history, computed over every eligible filing rather than only the outstanding ones.';


--
-- Name: pending_corporate_actions; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_corporate_actions AS
 SELECT s.security_id,
    t.value AS symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((market.security s
     JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
     JOIN market.security_symbol sym ON (((sym.security_id = s.security_id) AND (upper(sym.symbol) = upper(t.value)))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND ((s.corporate_actions_missing_at IS NULL) OR (s.corporate_actions_missing_at < (now() - '30 days'::interval))) AND (NOT (EXISTS ( SELECT 1
           FROM market.security_corporate_action a
          WHERE ((a.security_id = s.security_id) AND (a.as_of > (now() - '30 days'::interval)))))))
  GROUP BY s.security_id, t.value
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: pending_daily_history; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_daily_history AS
 SELECT s.security_id,
    sym.symbol,
    COALESCE(ps.symbol, sym.symbol) AS fetch_symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((market.security s
     JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (s.daily_history_from IS NULL) AND ((s.daily_history_missing_at IS NULL) OR (s.daily_history_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, sym.symbol, COALESCE(ps.symbol, sym.symbol)
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, s.security_id;


--
-- Name: VIEW pending_daily_history; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_daily_history IS 'Equities with no deep DAILY history yet, heaviest fund holding first. Whole universe, not US-only: measured 2026-08-28, every non-US venue tried returns 20+ years of daily bars.';


--
-- Name: pending_dividends; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_dividends AS
 SELECT s.security_id,
    sym.symbol,
    COALESCE(ps.symbol, sym.symbol) AS fetch_symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((market.security s
     JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND ((s.dividends_missing_at IS NULL) OR (s.dividends_missing_at < (now() - '30 days'::interval))) AND (NOT (EXISTS ( SELECT 1
           FROM market.security_corporate_action a
          WHERE ((a.security_id = s.security_id) AND (a.kind = 'dividend'::text) AND (a.as_of > (now() - '30 days'::interval)))))))
  GROUP BY s.security_id, sym.symbol, ps.symbol
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, s.security_id;


--
-- Name: VIEW pending_dividends; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_dividends IS 'Equities needing a dividend refresh from yfinance. Unlike pending_corporate_actions this does NOT require the priced symbol to be the US ticker — yfinance is asked with the symbol the bars are keyed on, so the action and the series describe one listing by construction. That constraint is why Tiingo reaches 560 of 12,350.';


--
-- Name: pending_eps_history; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_eps_history AS
 SELECT s.security_id,
    t.value AS symbol,
    max(h.weight) AS best_weight
   FROM ((market.security s
     JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
     JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
  WHERE ((s.security_type_code = 'equity'::text) AND (t.value !~~ '%.%'::text) AND (EXISTS ( SELECT 1
           FROM market.listing l
          WHERE ((l.security_id = s.security_id) AND (l.exch_code = 'US'::text)))) AND ((s.eps_history_fetched_at IS NULL) OR (s.eps_history_fetched_at < (now() - '90 days'::interval))))
  GROUP BY s.security_id, t.value
 HAVING (max(h.weight) >= 1.0)
  ORDER BY (max(h.weight)) DESC;


--
-- Name: VIEW pending_eps_history; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_eps_history IS 'US-LISTED equities that are at least 1% of some tracked fund and whose EPS history is unread or a quarter old. Takes the US ticker and requires a US listing in market.listing: alpha_vantage serves US listings, and OpenFIGI''s US lookup returns the OTC foreign-ordinary line (ASMLF, TSMWF) for most foreign companies — bare tickers the provider answers with an empty object, each costing 4% of a 25-a-day budget to learn nothing.';


--
-- Name: pending_filing_history; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_filing_history AS
 SELECT s.security_id,
    s.cik,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (market.security s
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.cik IS NOT NULL) AND ((s.filing_history_fetched_at IS NULL) OR (s.filing_history_fetched_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, s.cik
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, s.security_id;


--
-- Name: VIEW pending_filing_history; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_filing_history IS 'Filers whose complete filing history has not been walked from SEC''s submissions API in the last 30 days. Ordered by fund weight so the largest holdings gain depth first.';


--
-- Name: pending_filings; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_filings AS
 SELECT s.security_id,
    s.cik,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (market.security s
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (s.cik IS NOT NULL) AND ((s.filings_fetched_at IS NULL) OR (s.filings_fetched_at < (now() - '7 days'::interval))))
  GROUP BY s.security_id, s.cik
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: VIEW pending_filings; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_filings IS 'SEC filers whose filing index has not been read in the last week, ordered by fund weight. A rolling cursor: it is not meant to empty.';


--
-- Name: pending_fundamentals; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_fundamentals AS
 SELECT s.security_id,
    COALESCE(ps.symbol, t.value) AS symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM ((((market.security s
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
     LEFT JOIN market.security_fundamentals f ON ((f.security_id = s.security_id)))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((f.security_id IS NULL) AND (s.security_type_code = 'equity'::text) AND (COALESCE(ps.symbol, t.value) IS NOT NULL) AND ((s.fundamentals_missing_at IS NULL) OR (s.fundamentals_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, COALESCE(ps.symbol, t.value)
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: pending_fx_history; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_fx_history AS
 SELECT code AS currency_code
   FROM market.currency c
  WHERE ((code <> 'USD'::text) AND ((history_missing_at IS NULL) OR (history_missing_at < (now() - '30 days'::interval))) AND (NOT (EXISTS ( SELECT 1
           FROM market.fx_rate r
          WHERE ((r.currency_code = c.code) AND (r.as_of < (CURRENT_DATE - 90)))))));


--
-- Name: VIEW pending_fx_history; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_fx_history IS 'Currencies with no exchange rate older than 90 days and no recent record of the provider having none — i.e. spot-only and worth asking about. A VIEW rather than a client-side probe because the probe read rows and PGRST_DB_MAX_ROWS silently capped it at 1,000.';


--
-- Name: pending_in_history; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_in_history AS
 SELECT s.security_id,
    COALESCE(sf.filer_id, l.symbol) AS symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM ((((market.security s
     JOIN market.listing l ON ((l.security_id = s.security_id)))
     JOIN market.exchange e ON ((e.exch_code = l.exch_code)))
     LEFT JOIN market.security_filer sf ON (((sf.security_id = s.security_id) AND (sf.source_code = 'nse'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (s.country_iso2 = 'IN'::text) AND (e.country_iso2 = 'IN'::text) AND (l.symbol IS NOT NULL) AND ((sf.history_walked_at IS NULL) OR (sf.history_walked_at < (now() - '90 days'::interval))))
  GROUP BY s.security_id, sf.filer_id, l.symbol
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, COALESCE(sf.filer_id, l.symbol);


--
-- Name: VIEW pending_in_history; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_in_history IS 'Indian equities whose NSE filing history has not been walked in 90 days. `symbol` is the RESOLVED NSE trading symbol from security_filer.filer_id where one is known, falling back to market.listing.symbol — which holds a vendor abbreviation for 406 of 645 Indian equities and makes NSE answer with an empty 200.';


--
-- Name: pending_in_segments; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_in_segments AS
 SELECT security_id,
    accession_number,
    report_type,
    filing_date,
    filer_id,
    best_weight,
    round
   FROM ( SELECT f.security_id,
            f.accession_number,
            f.report_type,
            f.filing_date,
            sf.filer_id,
            COALESCE(max(h.weight), (0)::numeric) AS best_weight,
            ((f.segments_parsed_at IS NULL) OR (COALESCE((f.segments_parser_version)::integer, 0) < ( SELECT p.version
                   FROM market.segment_parser p))) AS needs_work,
            row_number() OVER (PARTITION BY f.security_id ORDER BY COALESCE(( SELECT ff.is_annual
                   FROM market.filing_form ff
                  WHERE ((ff.source_code = 'nse'::text) AND (ff.form_code = f.report_type))
                 LIMIT 1), false) DESC, f.filing_date DESC, f.accession_number) AS round
           FROM ((market.security_filing f
             JOIN market.security_filer sf ON (((sf.security_id = f.security_id) AND (sf.source_code = 'nse'::text))))
             LEFT JOIN market.fund_holding_current h ON ((h.security_id = f.security_id)))
          WHERE ((f.source_code = 'nse'::text) AND (EXISTS ( SELECT 1
                   FROM market.filing_form ff
                  WHERE ((ff.source_code = 'nse'::text) AND (ff.form_code = f.report_type) AND ff.carries_segments))))
          GROUP BY f.security_id, f.accession_number, f.report_type, f.filing_date, sf.filer_id, f.segments_parsed_at, f.segments_parser_version) ranked
  WHERE needs_work
  ORDER BY round, best_weight DESC, accession_number;


--
-- Name: VIEW pending_in_segments; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_in_segments IS 'Indian filings whose XBRL instance has not been read for segment facts. `round` is the filing''s STABLE depth into its own company''s history — see pending_kr_segments for why computing it over the outstanding set instead makes the queue depth-first.';


--
-- Name: pending_insider; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_insider AS
 SELECT s.security_id,
    s.cik,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (market.security s
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (s.cik IS NOT NULL) AND ((s.insider_fetched_at IS NULL) OR (s.insider_fetched_at < (now() - '7 days'::interval))))
  GROUP BY s.security_id, s.cik
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: VIEW pending_insider; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_insider IS 'SEC filers whose Form 4 filings have not been read in the last week, ordered by fund weight. A rolling cursor: insiders keep trading, so this never empties and is not meant to.';


--
-- Name: pending_kr_history; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_kr_history AS
 SELECT sf.security_id,
    sf.filer_id,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight,
    sf.history_walked_at
   FROM ((market.security_filer sf
     JOIN market.security s ON ((s.security_id = sf.security_id)))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = sf.security_id)))
  WHERE ((sf.source_code = 'dart'::text) AND ((sf.history_walked_at IS NULL) OR (sf.history_walked_at < (now() - '90 days'::interval))))
  GROUP BY sf.security_id, sf.filer_id, sf.history_walked_at
  ORDER BY (sf.history_walked_at IS NOT NULL), COALESCE(max(h.weight), (0)::numeric) DESC, sf.security_id;


--
-- Name: VIEW pending_kr_history; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_kr_history IS 'Korean filers whose filing history has not been walked in the last 90 days. A CURSOR rather than a negative cache: companies keep filing, so an absence here is never permanent, and after `dart_discovery_cursor.mapped_at` is set this is the only way a new annual report is discovered.';


--
-- Name: pending_kr_segments; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_kr_segments AS
 SELECT security_id,
    accession_number,
    report_type,
    filing_date,
    filer_id,
    best_weight,
    round
   FROM ( SELECT f.security_id,
            f.accession_number,
            f.report_type,
            f.filing_date,
            sf.filer_id,
            COALESCE(max(h.weight), (0)::numeric) AS best_weight,
            ((f.segments_parsed_at IS NULL) OR (COALESCE((f.segments_parser_version)::integer, 0) < ( SELECT p.version
                   FROM market.segment_parser p))) AS needs_work,
            row_number() OVER (PARTITION BY f.security_id ORDER BY COALESCE(( SELECT ff.is_annual
                   FROM market.filing_form ff
                  WHERE ((ff.source_code = 'dart'::text) AND (ff.form_code = f.report_type))
                 LIMIT 1), false) DESC, f.filing_date DESC, f.accession_number) AS round
           FROM ((market.security_filing f
             JOIN market.security_filer sf ON (((sf.security_id = f.security_id) AND (sf.source_code = 'dart'::text))))
             LEFT JOIN market.fund_holding_current h ON ((h.security_id = f.security_id)))
          WHERE ((f.source_code = 'dart'::text) AND (EXISTS ( SELECT 1
                   FROM market.filing_form ff
                  WHERE ((ff.source_code = 'dart'::text) AND (ff.form_code = f.report_type) AND ff.carries_segments))))
          GROUP BY f.security_id, f.accession_number, f.report_type, f.filing_date, sf.filer_id, f.segments_parsed_at, f.segments_parser_version) ranked
  WHERE needs_work
  ORDER BY round, best_weight DESC, accession_number;


--
-- Name: VIEW pending_kr_segments; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_kr_segments IS 'Korean filings whose XBRL archive has not been read for segment facts. `round` is the filing''s STABLE depth into its own company''s history, computed over every eligible filing rather than only the outstanding ones — computing it over the outstanding set makes it renumber as the queue drains, which sends the heaviest company back to the head after every parse.';


--
-- Name: pending_local_symbol; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_local_symbol AS
 SELECT s.security_id,
    s.country_iso2,
    isin.value AS isin,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((market.security s
     JOIN market.security_identifier isin ON (((isin.security_id = s.security_id) AND (isin.kind_code = 'isin'::text))))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((ps.security_id IS NULL) AND (s.security_type_code = 'equity'::text) AND (s.country_iso2 IS NOT NULL) AND (s.country_iso2 <> 'US'::text) AND (EXISTS ( SELECT 1
           FROM market.exchange e
          WHERE (e.country_iso2 = s.country_iso2))) AND ((s.local_symbol_missing_at IS NULL) OR (s.local_symbol_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, s.country_iso2, isin.value
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: pending_management; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_management AS
 SELECT s.security_id,
    COALESCE(ps.symbol, t.value) AS symbol,
    max(h.weight) AS best_weight
   FROM (((market.security s
     JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
  WHERE ((s.security_type_code = 'equity'::text) AND (COALESCE(ps.symbol, t.value) IS NOT NULL) AND ((s.management_fetched_at IS NULL) OR (s.management_fetched_at < (now() - '180 days'::interval))))
  GROUP BY s.security_id, COALESCE(ps.symbol, t.value)
 HAVING (max(h.weight) >= 0.5)
  ORDER BY (max(h.weight)) DESC;


--
-- Name: VIEW pending_management; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_management IS 'Equities that are at least 0.5% of some tracked fund and whose officer list is unread or six months old. Bounded deliberately: this costs one yfinance call per security and must not out-compete the price and statement backlogs on the same budget.';


--
-- Name: pending_metrics; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_metrics AS
 SELECT security_id,
    statement,
    period_ending
   FROM market.security_statement st
  WHERE (derived_at IS NULL);


--
-- Name: VIEW pending_metrics; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_metrics IS 'Statements not yet turned into metrics. A DRIFT COUNTER, not a work queue: the derivation needs no provider, so this settles to the statements whose provider reports none of the catalogue''s field names. Expected non-zero and stable; the TREND is the signal.';


--
-- Name: pending_news; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_news AS
 SELECT s.security_id,
    sym.symbol,
    COALESCE(ps.symbol, sym.symbol) AS fetch_symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((market.security s
     JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND ((s.news_fetched_at IS NULL) OR (s.news_fetched_at < (now() - '7 days'::interval))))
  GROUP BY s.security_id, sym.symbol, COALESCE(ps.symbol, sym.symbol)
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, s.security_id;


--
-- Name: VIEW pending_news; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_news IS 'Equities whose news has not been read in 7 days, heaviest fund holding first. Keyed on when we ASKED because news has no "done" state — an anti-join over existing rows would re-ask the whole universe for ever.';


--
-- Name: pending_performance; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_performance AS
 SELECT s.security_id,
    COALESCE(sym.symbol, ps.symbol, t.value) AS symbol,
    COALESCE(ps.symbol, t.value) AS fetch_symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((((market.security s
     LEFT JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
     LEFT JOIN market.performance p ON (((p.scope = 'instrument'::text) AND (p.scope_id = COALESCE(sym.symbol, ps.symbol, t.value)) AND (p.stale_after > now()))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((p.scope_id IS NULL) AND (COALESCE(ps.symbol, t.value) IS NOT NULL) AND ((s.performance_missing_at IS NULL) OR (s.performance_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, sym.symbol, ps.symbol, t.value
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: pending_price_history; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_price_history AS
 SELECT s.security_id,
    sym.symbol,
    COALESCE(ps.symbol, sym.symbol) AS fetch_symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((market.security s
     JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (s.price_history_from IS NULL) AND ((s.price_history_missing_at IS NULL) OR (s.price_history_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, sym.symbol, COALESCE(ps.symbol, sym.symbol)
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, s.security_id;


--
-- Name: VIEW pending_price_history; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_price_history IS 'Equities with no weekly history yet, heaviest fund holding first. Keyed on the price_history_from MARKER rather than a scan of security_price: the left-join form measured 5.8s, two seconds from the PostgREST role timeout, and grew with the series.';


--
-- Name: pending_price_targets; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_price_targets AS
 SELECT s.security_id,
    t.value AS symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM ((market.security s
     JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (EXISTS ( SELECT 1
           FROM market.listing l
          WHERE ((l.security_id = s.security_id) AND (l.exch_code = 'US'::text)))) AND ((s.price_targets_fetched_at IS NULL) OR (s.price_targets_fetched_at < (now() - '7 days'::interval))))
  GROUP BY s.security_id, t.value
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: VIEW pending_price_targets; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_price_targets IS 'US-listed equities whose analyst actions have not been read in the last week, ordered by fund weight. A rolling cursor rather than a drain: analysts keep re-rating, so this never empties and is not meant to. Scoped on a US LISTING because finviz 400s on every suffixed symbol and on every OTC foreign-ordinary line.';


--
-- Name: pending_prices; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_prices AS
 SELECT s.security_id,
    sym.symbol,
    COALESCE(ps.symbol, sym.symbol) AS fetch_symbol,
    p.last_date,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM ((((market.security s
     JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN LATERAL ( SELECT max(sp.date) AS last_date
           FROM market.security_price sp
          WHERE (sp.security_id = s.security_id)) p ON (true))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND ((p.last_date IS NULL) OR (p.last_date < (((now() AT TIME ZONE 'utc'::text))::date - 2))) AND ((s.prices_missing_at IS NULL) OR (s.prices_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, sym.symbol, ps.symbol, p.last_date
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: pending_profile; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_profile AS
 SELECT s.security_id,
    COALESCE(ps.symbol, t.value) AS symbol,
    s.name,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight,
        CASE
            WHEN (st.security_id IS NULL) THEN 'sector'::text
            ELSE 'country'::text
        END AS want
   FROM ((((market.security s
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
     LEFT JOIN market.security_taxonomy st ON (((st.security_id = s.security_id) AND (st.source_code = 'yfinance'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (COALESCE(ps.symbol, t.value) IS NOT NULL) AND (((st.security_id IS NULL) AND ((s.profile_missing_at IS NULL) OR (s.profile_missing_at < (now() - '30 days'::interval)))) OR ((s.provider_country_iso2 IS NULL) AND ((s.country_iso2 IS NULL) OR (NOT (EXISTS ( SELECT 1
           FROM market.countries c
          WHERE ((c.iso2 = s.country_iso2) AND c.drillable))))) AND ((s.provider_country_missing_at IS NULL) OR (s.provider_country_missing_at < (now() - '30 days'::interval))))))
  GROUP BY s.security_id, COALESCE(ps.symbol, t.value), s.name, st.security_id
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: pending_profile_detail; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_profile_detail AS
 SELECT s.security_id,
    COALESCE(ps.symbol, t.value) AS symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM ((((market.security s
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
     LEFT JOIN market.security_profile p ON ((p.security_id = s.security_id)))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((p.security_id IS NULL) AND (s.security_type_code = 'equity'::text) AND (COALESCE(ps.symbol, t.value) IS NOT NULL) AND ((s.profile_detail_missing_at IS NULL) OR (s.profile_detail_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, COALESCE(ps.symbol, t.value)
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: VIEW pending_profile_detail; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_profile_detail IS 'Equities with no descriptive profile, ordered by fund weight. Its own backlog rather than a widened `pending_profile`, which asks about the SECTOR and is drained — a new field filled by an existing resource is inert without one.';


--
-- Name: untracked_listing; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.untracked_listing AS
 SELECT figi,
    composite_figi,
    exch_code,
    ticker,
    name,
    country_iso2,
    provider_symbol
   FROM market.exchange_listing l
  WHERE ((name IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM market.security_identifier si
          WHERE ((si.kind_code = 'figi'::text) AND (si.value = l.composite_figi))))) AND (NOT (EXISTS ( SELECT 1
           FROM market.security_provider_symbol ps
          WHERE (upper(ps.symbol) = upper(l.provider_symbol))))) AND (NOT (EXISTS ( SELECT 1
           FROM market.security_identifier ti
          WHERE ((ti.kind_code = 'ticker'::text) AND (upper(ti.value) = upper(l.provider_symbol)))))));


--
-- Name: VIEW untracked_listing; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.untracked_listing IS 'Exchange listings the universe does not track. Excluded by composite FIGI, by provider symbol and by resolved ticker — the FIGI alone covered 547 of 27,628 securities and called 9,976 tracked companies untracked, Samsung Electronics among them.';


--
-- Name: pending_promotion; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_promotion AS
 SELECT l.figi,
    l.composite_figi,
    l.exch_code,
    l.ticker,
    l.name,
    l.country_iso2,
    l.provider_symbol,
    e.promotion_tier,
    e.preference
   FROM (market.untracked_listing l
     JOIN market.exchange e ON ((e.exch_code = l.exch_code)))
  WHERE (e.promotion_enabled AND e.enabled AND (NOT (EXISTS ( SELECT 1
           FROM market.security s
          WHERE (upper(s.name) = upper(l.name))))))
  ORDER BY e.promotion_tier, e.preference, l.name;


--
-- Name: VIEW pending_promotion; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_promotion IS 'Listings eligible for promotion, in the order a fixed provider budget should spend itself: home markets first, cross-listing venues last, opted in per venue and name-deduped against securities already held. Empty until an operator sets promotion_enabled — see the column comment.';


--
-- Name: pending_quarters; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_quarters AS
 SELECT s.security_id,
    COALESCE(ps.symbol, t.value) AS symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((market.security s
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (s.cik IS NULL) AND (COALESCE(ps.symbol, t.value) IS NOT NULL) AND ((s.quarters_missing_at IS NULL) OR (s.quarters_missing_at < (now() - '30 days'::interval))) AND (EXISTS ( SELECT 1
           FROM market.security_statement a
          WHERE ((a.security_id = s.security_id) AND (a.period_type = 'annual'::text)))) AND (NOT (EXISTS ( SELECT 1
           FROM market.security_statement q
          WHERE ((q.security_id = s.security_id) AND (q.period_type = 'quarter'::text))))))
  GROUP BY s.security_id, COALESCE(ps.symbol, t.value)
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: VIEW pending_quarters; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_quarters IS 'Non-SEC equities with annual statements but no quarterly ones, ordered by fund weight. Quarterly does not batch (3 calls per security), so this is deliberately scoped rather than the whole universe — SEC filers already have 17 years of quarters from companyfacts.';


--
-- Name: pending_segment_alias; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_segment_alias AS
 SELECT c.member_code,
    min(c.kind) AS kind,
    count(DISTINCT s.issuer_id) AS issuers,
    count(DISTINCT c.security_id) AS securities,
    max(COALESCE(h.best_weight, (0)::numeric)) AS best_weight,
    max(c.revenue_share_pct) AS largest_share_pct,
    max(c.revenue) AS largest_revenue,
    max(c.currency_code) AS a_currency_code,
    min(c.axis) AS an_axis,
    bool_or((c.member_code ~* '(AllOther|CorporateAndOther|OtherSegment|:Other[A-Z]|:OthersMember|Unallocated|Reconcil|Elimination|Intersegment)'::text)) AS is_catch_all
   FROM ((market.security_segment_spine c
     JOIN market.security s ON ((s.security_id = c.security_id)))
     LEFT JOIN LATERAL ( SELECT max(fh.weight) AS best_weight
           FROM market.fund_holding_current fh
          WHERE (fh.security_id = c.security_id)) h ON (true))
  WHERE ((c.concept_code IS NULL) AND (c.kind = ANY (ARRAY['product'::text, 'business'::text])))
  GROUP BY c.member_code
  ORDER BY (bool_or((c.member_code ~* '(AllOther|CorporateAndOther|OtherSegment|:Other[A-Z]|:OthersMember|Unallocated|Reconcil|Elimination|Intersegment)'::text))), (max(COALESCE(h.best_weight, (0)::numeric))) DESC NULLS LAST, (max(c.revenue_share_pct)) DESC NULLS LAST, c.member_code;


--
-- Name: VIEW pending_segment_alias; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_segment_alias IS 'Business lines with no shared concept. NOT ordered by how many companies use the member: an XBRL extension member is namespaced by its filer, so measured across the whole universe ZERO extension members are shared by two issuers and that number is structurally 1 rather than merely small. Ranked by fund weight (a percentage, so free of currency) with residual buckets last — they cannot be a comparable concept because "all other segments" means something different in every filing.';


--
-- Name: pending_segments; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_segments AS
 SELECT security_id,
    accession_number,
    report_type,
    filing_date,
    filing_detail_url,
    cik,
    best_weight,
    round,
    already_read
   FROM ( SELECT f.security_id,
            f.accession_number,
            f.report_type,
            f.filing_date,
            f.filing_detail_url,
            s.cik,
            (f.segments_parsed_at IS NOT NULL) AS already_read,
            ((f.segments_parsed_at IS NULL) OR (COALESCE((f.segments_parser_version)::integer, 0) < ( SELECT p.version
                   FROM market.segment_parser p))) AS needs_work,
            COALESCE(max(h.weight), (0)::numeric) AS best_weight,
            row_number() OVER (PARTITION BY f.security_id ORDER BY COALESCE(( SELECT ff.is_annual
                   FROM market.filing_form ff
                  WHERE ((ff.source_code = 'sec'::text) AND (ff.form_code = f.report_type))
                 LIMIT 1), false) DESC, f.filing_date DESC, f.accession_number) AS round
           FROM ((market.security_filing f
             JOIN market.security s ON ((s.security_id = f.security_id)))
             LEFT JOIN market.fund_holding_current h ON ((h.security_id = f.security_id)))
          WHERE ((s.cik IS NOT NULL) AND (EXISTS ( SELECT 1
                   FROM market.filing_form ff
                  WHERE ((ff.source_code = 'sec'::text) AND (ff.form_code = f.report_type) AND ff.carries_segments))) AND (EXISTS ( SELECT 1
                   FROM market.security_disclosure sd
                  WHERE ((sd.security_id = f.security_id) AND (sd.capability = 'held'::text)))))
          GROUP BY f.security_id, f.accession_number, f.report_type, f.filing_date, f.filing_detail_url, s.cik, f.segments_parsed_at, f.segments_parser_version) ranked
  WHERE needs_work
  ORDER BY round, already_read DESC, best_weight DESC, accession_number;


--
-- Name: VIEW pending_segments; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_segments IS 'SEC filings whose XBRL instance has not been read for segment facts. Ordered BREADTH-FIRST: `round` is the filing''s STABLE depth into its own company''s history (annuals before quarterlies), computed over every eligible filing rather than only the outstanding ones — so a company that has had k filings read sits at round k+1 and yields to every company still at round 1. Computing it over the outstanding set instead makes it renumber as the queue drains, which put 3,861 of 3,967 filers at zero re-reads while one company had 131. Requires a CIK — that is the SEC path''s actual precondition, and without it enabling DART puts Korean filings in this queue, where `findInstanceUrl` cannot address them.';


--
-- Name: pending_share_stats; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_share_stats AS
 SELECT s.security_id,
    sym.symbol,
    COALESCE(ps.symbol, sym.symbol) AS fetch_symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM ((((market.security s
     JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.security_share_stats st ON (((st.security_id = s.security_id) AND (st.fetched_at > (now() - '7 days'::interval)))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (st.security_id IS NULL) AND ((s.share_stats_missing_at IS NULL) OR (s.share_stats_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, sym.symbol, COALESCE(ps.symbol, sym.symbol)
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, s.security_id;


--
-- Name: VIEW pending_share_stats; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_share_stats IS 'Equities whose share statistics have not been read in 7 days, heaviest fund holding first. Drives BOTH share statistics and analyst estimates — one batch of symbols answers both endpoints, and splitting them would double the requests for two halves of one row.';


--
-- Name: pending_statements; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_statements AS
 SELECT s.security_id,
    COALESCE(ps.symbol, t.value) AS symbol,
    COALESCE(us.symbol, t.value) AS us_ticker,
        CASE
            WHEN (st.security_id IS NULL) THEN 'missing'::text
            ELSE 'no_currency'::text
        END AS want,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((((market.security s
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
     LEFT JOIN LATERAL ( SELECT l.symbol
           FROM (market.listing l
             JOIN market.exchange e ON ((e.exch_code = l.exch_code)))
          WHERE ((l.security_id = s.security_id) AND (e.country_iso2 = 'US'::text) AND (l.symbol IS NOT NULL))
          ORDER BY l.is_primary DESC, l.symbol
         LIMIT 1) us ON (true))
     LEFT JOIN LATERAL ( SELECT x.security_id,
            count(*) FILTER (WHERE (x.currency IS NOT NULL)) AS with_currency
           FROM market.security_statement x
          WHERE (x.security_id = s.security_id)
          GROUP BY x.security_id) st ON (true))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (COALESCE(ps.symbol, t.value) IS NOT NULL) AND ((s.statements_missing_at IS NULL) OR (s.statements_missing_at < (now() - '30 days'::interval))) AND ((st.security_id IS NULL) OR ((st.with_currency = 0) AND (t.value IS NOT NULL) AND (s.cik IS NOT NULL) AND (EXISTS ( SELECT 1
           FROM (market.listing l
             JOIN market.exchange e ON ((e.exch_code = l.exch_code)))
          WHERE ((l.security_id = s.security_id) AND (e.country_iso2 = 'US'::text) AND (l.symbol IS NOT NULL)))) AND ((s.statement_currency_missing_at IS NULL) OR (s.statement_currency_missing_at < (now() - '30 days'::interval))))))
  GROUP BY s.security_id, COALESCE(ps.symbol, t.value), COALESCE(us.symbol, t.value), t.value, st.security_id, st.with_currency
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, s.security_id;


--
-- Name: VIEW pending_statements; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_statements IS 'Equities needing statements, or needing a currency for the ones they have. `us_ticker` is the symbol a US venue lists the security under, falling back to the OpenFIGI ticker identifier — SEC is asked by it, and OpenFIGI spells Berkshire''s B share BRK/B where SEC uses BRK-B. Asking under the wrong name and then recording the 404 as an absence would negative-cache a company SEC serves perfectly.';


--
-- Name: pending_symbol_repair; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_symbol_repair AS
 SELECT s.security_id,
    sym.symbol,
    COALESCE(ps.symbol, sym.symbol) AS fetch_symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((market.security s
     JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND ((s.prices_missing_at IS NOT NULL) OR (s.price_history_missing_at IS NOT NULL) OR (s.performance_missing_at IS NOT NULL)) AND ((s.symbol_repair_at IS NULL) OR (s.symbol_repair_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, sym.symbol, COALESCE(ps.symbol, sym.symbol)
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, s.security_id;


--
-- Name: VIEW pending_symbol_repair; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_symbol_repair IS 'Securities whose price fetches have failed and whose symbol has not been re-examined this month, heaviest holding first. Reads the MARKED set on purpose: a candidate costs a provider call, and generating them for working symbols is the expensive way to learn nothing.';


--
-- Name: pending_ticker; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_ticker AS
 SELECT s.security_id,
    isin.value AS isin,
    s.name,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((market.security s
     JOIN market.security_identifier isin ON (((isin.security_id = s.security_id) AND (isin.kind_code = 'isin'::text))))
     LEFT JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((t.security_id IS NULL) AND (s.security_type_code = 'equity'::text) AND ((s.figi_missing_at IS NULL) OR (s.figi_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, isin.value, s.name
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: pending_ttm; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_ttm AS
 SELECT q.security_id
   FROM (( SELECT m.security_id,
            max(m.fetched_at) AS newest_quarter
           FROM (market.security_metric m
             JOIN market.metric mt ON (((mt.code = m.metric_code) AND mt.is_flow)))
          WHERE (m.period_type = 'quarter'::text)
          GROUP BY m.security_id) q
     LEFT JOIN ( SELECT t.security_id,
            max(t.fetched_at) AS newest_ttm
           FROM market.security_metric t
          WHERE (t.period_type = 'ttm'::text)
          GROUP BY t.security_id) d ON ((d.security_id = q.security_id)))
  WHERE ((d.newest_ttm IS NULL) OR (d.newest_ttm < q.newest_quarter));


--
-- Name: VIEW pending_ttm; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_ttm IS 'Securities whose TTM is missing or older than the quarterly metrics it is derived from. Shared with market.derive_ttm so the backlog and the work cannot disagree about what "done" means.';


--
-- Name: pending_wikidata; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_wikidata AS
 SELECT s.security_id,
    i.value AS isin,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM ((market.security s
     JOIN market.security_identifier i ON (((i.security_id = s.security_id) AND (i.kind_code = 'isin'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND ((s.wikidata_missing_at IS NULL) OR (s.wikidata_missing_at < (now() - '30 days'::interval))) AND (NOT (EXISTS ( SELECT 1
           FROM market.security_taxonomy st
          WHERE ((st.security_id = s.security_id) AND (st.source_code = 'wikidata'::text))))))
  GROUP BY s.security_id, i.value
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, s.security_id;


--
-- Name: VIEW pending_wikidata; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_wikidata IS 'Equities with an ISIN and no Wikidata industry tags yet. Ordered by fund weight so the largest holdings resolve first.';


--
-- Name: pending_xbrl; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_xbrl AS
 SELECT s.security_id,
    s.cik,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (market.security s
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.cik IS NOT NULL) AND (s.security_type_code = 'equity'::text) AND ((s.xbrl_fetched_at IS NULL) OR (s.xbrl_fetched_at < (now() - '30 days'::interval))) AND ((s.xbrl_missing_at IS NULL) OR (s.xbrl_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, s.cik
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC, s.security_id;


--
-- Name: VIEW pending_xbrl; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_xbrl IS 'US filers whose company facts have not been read in 30 days, heaviest fund holding first. Keyed on when we last ASKED rather than on whether rows exist, so a filer using none of the catalogued concepts is not re-asked for ever.';


--
-- Name: pending_yahoo_symbol; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.pending_yahoo_symbol AS
 SELECT s.security_id,
    isin.value AS isin,
    s.country_iso2,
    COALESCE(ps.symbol, t.value) AS current_symbol,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM ((((market.security s
     JOIN market.security_identifier isin ON (((isin.security_id = s.security_id) AND (isin.kind_code = 'isin'::text))))
     LEFT JOIN market.security_provider_symbol ps ON (((ps.security_id = s.security_id) AND (ps.provider_code = 'yfinance'::text))))
     LEFT JOIN market.security_identifier t ON (((t.security_id = s.security_id) AND (t.kind_code = 'ticker'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = s.security_id)))
  WHERE ((s.security_type_code = 'equity'::text) AND (s.country_iso2 IS NOT NULL) AND ((s.industry_missing_at IS NOT NULL) OR (s.profile_missing_at IS NOT NULL) OR (s.performance_missing_at IS NOT NULL) OR (COALESCE(ps.symbol, t.value) IS NULL)) AND ((s.yahoo_symbol_missing_at IS NULL) OR (s.yahoo_symbol_missing_at < (now() - '30 days'::interval))))
  GROUP BY s.security_id, isin.value, s.country_iso2, COALESCE(ps.symbol, t.value)
  ORDER BY (COALESCE(ps.symbol, t.value) IS NULL) DESC, COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: VIEW pending_yahoo_symbol; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.pending_yahoo_symbol IS 'Securities whose symbol is missing or suspected wrong, with an ISIN to resolve from. Symbol-less first — those cannot enter any other backlog until this one names them.';


--
-- Name: prices; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.prices (
    symbol text NOT NULL,
    date date NOT NULL,
    close numeric NOT NULL
);


--
-- Name: symbol_security; Type: MATERIALIZED VIEW; Schema: market; Owner: -
--

CREATE MATERIALIZED VIEW market.symbol_security AS
 SELECT s.security_id,
    sym.symbol
   FROM (market.security s
     JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
  WHERE (sym.symbol IS NOT NULL)
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW symbol_security; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON MATERIALIZED VIEW market.symbol_security IS 'symbol -> security_id, materialised. `security_symbol` is a view over two LATERAL subqueries, so resolving one symbol through it costs a scan of all 27,629 securities — measured, that is most of the 260 ms a daily chart takes and 1,382 ms of a weekly one. Refreshed beside security_facets by the same resource, because a matview with no scheduled refresh is a stale view nobody notices.';


--
-- Name: price_series; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.price_series AS
 SELECT DISTINCT ON (symbol, grain, date) symbol,
    date,
    close,
    grain
   FROM ( SELECT ss.symbol,
            sp.date,
            sp.close,
            sp.grain,
            1 AS priority
           FROM (market.security_price sp
             JOIN market.symbol_security ss ON ((ss.security_id = sp.security_id)))
        UNION ALL
         SELECT p.symbol,
            p.date,
            p.close,
            'daily'::text AS grain,
            2 AS priority
           FROM market.prices p) x
  ORDER BY symbol, grain, date, priority;


--
-- Name: VIEW price_series; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.price_series IS 'Every close the app can chart, by symbol and GRAIN: the security series first, the curated instrument series second. Joins the MATERIALISED symbol map — through the `security_symbol` view the planner scans all 27,629 securities to answer about one, which timed out for anon on the weekly series. A reader must filter on `grain` (the two overlap by design) and page (a 20-year weekly series is 1,077 rows, above PGRST_DB_MAX_ROWS).';


--
-- Name: refresh_log; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.refresh_log (
    resource text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    ok boolean DEFAULT false NOT NULL,
    error text,
    min_interval interval
);


--
-- Name: refresh_run; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.refresh_run (
    run_id bigint NOT NULL,
    resource text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    finished_at timestamp with time zone DEFAULT now() NOT NULL,
    duration_ms integer,
    ok boolean NOT NULL,
    skipped boolean DEFAULT false NOT NULL,
    http_status integer,
    error text,
    report jsonb,
    written bigint GENERATED ALWAYS AS (
CASE
    WHEN (jsonb_typeof((report -> 'written'::text)) = 'number'::text) THEN ((report ->> 'written'::text))::bigint
    ELSE NULL::bigint
END) STORED,
    remaining bigint GENERATED ALWAYS AS (
CASE
    WHEN (jsonb_typeof((report -> 'remaining'::text)) = 'number'::text) THEN ((report ->> 'remaining'::text))::bigint
    ELSE NULL::bigint
END) STORED,
    failed bigint GENERATED ALWAYS AS (
CASE
    WHEN (jsonb_typeof((report -> 'failed'::text)) = 'number'::text) THEN ((report ->> 'failed'::text))::bigint
    ELSE NULL::bigint
END) STORED
);


--
-- Name: COLUMN refresh_run.skipped; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.refresh_run.skipped IS 'True when the invocation returned `skipped: true` — the TTL had not elapsed, or another invocation held the in-flight lock. The call SUCCEEDED and did no work, so `ok` is true and THIS is what separates the two. Any "has this resource stopped" question must exclude skips, or a resource whose worker dies on every run reads as healthy from the wreckage of its own in-flight lock.';


--
-- Name: refresh_run_run_id_seq; Type: SEQUENCE; Schema: market; Owner: -
--

CREATE SEQUENCE market.refresh_run_run_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: refresh_run_run_id_seq; Type: SEQUENCE OWNED BY; Schema: market; Owner: -
--

ALTER SEQUENCE market.refresh_run_run_id_seq OWNED BY market.refresh_run.run_id;


--
-- Name: regions; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.regions (
    id text NOT NULL,
    name text NOT NULL,
    icon text,
    blurb text,
    sort_order integer DEFAULT 0 NOT NULL
);


--
-- Name: resource_health; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.resource_health AS
 SELECT resource,
    min(started_at) AS first_seen,
    max(finished_at) FILTER (WHERE (ok AND (NOT skipped))) AS last_worked,
    max(finished_at) FILTER (WHERE ok) AS last_ok_including_skips,
    count(*) FILTER (WHERE (skipped AND (started_at > (now() - '06:00:00'::interval)))) AS skips_6h,
    count(*) FILTER (WHERE (started_at > (now() - '06:00:00'::interval))) AS runs_6h,
    ( SELECT (EXTRACT(epoch FROM l.min_interval) / 3600.0)
           FROM market.refresh_log l
          WHERE (l.resource = r.resource)) AS ttl_hours,
    (EXISTS ( SELECT 1
           FROM market.cron_resource cr
          WHERE (cr.resource = r.resource))) AS scheduled
   FROM market.refresh_run r
  WHERE (started_at > (now() - '30 days'::interval))
  GROUP BY resource;


--
-- Name: VIEW resource_health; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.resource_health IS 'Per resource: when it last did WORK (a successful run that was not a skip), beside when it last returned ok at all. A large gap between the two is a resource whose worker is dying and whose in-flight wreckage is answering skips — which reads as healthy to anything counting `ok`. `refresh_log` cannot answer this: it holds one row per resource, overwritten every run, so a resource dying on a five-minute cron always looks just-started.';


--
-- Name: sectors; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.sectors (
    id text NOT NULL,
    name text NOT NULL,
    icon text,
    sort_order integer DEFAULT 0 NOT NULL
);


--
-- Name: security_earnings_surprise; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_earnings_surprise AS
 SELECT e.security_id,
    e.symbol,
    e.report_date,
    e.period_ending,
    m.as_of AS period_end_date,
    e.eps_consensus AS expected,
    m.value AS actual,
    (m.value - e.eps_consensus) AS surprise,
        CASE
            WHEN (e.eps_consensus <> (0)::numeric) THEN round((((m.value - e.eps_consensus) / abs(e.eps_consensus)) * (100)::numeric), 2)
            ELSE NULL::numeric
        END AS surprise_pct,
    (m.value >= e.eps_consensus) AS beat
   FROM (market.earnings_calendar e
     JOIN market.security_metric m ON (((m.security_id = e.security_id) AND (m.metric_code = 'eps_diluted'::text) AND (m.period_type = 'quarter'::text) AND (m.as_of >= (to_date(e.period_ending, 'YYYY-MM'::text) - 7)) AND (m.as_of < ((to_date(e.period_ending, 'YYYY-MM'::text) + '1 mon'::interval) + '7 days'::interval)))))
  WHERE ((e.security_id IS NOT NULL) AND (e.eps_consensus IS NOT NULL) AND (e.report_date <= CURRENT_DATE));


--
-- Name: VIEW security_earnings_surprise; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_earnings_surprise IS 'Actual diluted EPS against the consensus that preceded it. Derived from `security_metric` and `earnings_calendar` rather than fetched: `equity/fundamental/historical_eps` (alpha_vantage) allows 25 calls a day and covers US listings only, which cannot serve 12,350 equities. The period match widens the named month by a week each side because a 52/53-week fiscal calendar ends a quarter on the nearest Saturday.';


--
-- Name: security_eps_history; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_eps_history (
    security_id uuid NOT NULL,
    period_ending date NOT NULL,
    eps_actual numeric,
    eps_estimated numeric,
    surprise numeric,
    surprise_pct numeric,
    reported_date date,
    source_code text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE security_eps_history; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_eps_history IS 'Actual versus estimated EPS per quarter, going back years — from `equity/fundamental/historical_eps`. Complements `security_earnings_surprise`, which derives the same fact from data already held but only for quarters inside the earnings calendar''s 90-day window.';


--
-- Name: security_facet_status; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_facet_status AS
 WITH b AS (
         SELECT f.security_id,
            f.security_type_code,
            f.symbol,
            (f.symbol IS NOT NULL) AS has_symbol,
            (f.sector_id IS NOT NULL) AS has_sector,
            (f.industry_code IS NOT NULL) AS has_industry,
            (EXISTS ( SELECT 1
                   FROM market.security_price p
                  WHERE ((p.security_id = f.security_id) AND (p.date > (CURRENT_DATE - 30))))) AS has_price,
            (EXISTS ( SELECT 1
                   FROM market.performance pf
                  WHERE ((pf.scope = 'instrument'::text) AND (pf.scope_id = f.symbol)))) AS has_performance,
            (EXISTS ( SELECT 1
                   FROM market.security_profile x_1
                  WHERE (x_1.security_id = f.security_id))) AS has_profile,
            (EXISTS ( SELECT 1
                   FROM market.security_fundamentals x_1
                  WHERE (x_1.security_id = f.security_id))) AS has_fundamentals,
            (EXISTS ( SELECT 1
                   FROM market.security_statement x_1
                  WHERE (x_1.security_id = f.security_id))) AS has_statements,
            (EXISTS ( SELECT 1
                   FROM market.security_metric x_1
                  WHERE (x_1.security_id = f.security_id))) AS has_metrics,
            (s.price_history_from IS NOT NULL) AS has_price_history,
            (s.daily_history_from IS NOT NULL) AS has_daily_history,
            (EXISTS ( SELECT 1
                   FROM market.news_security x_1
                  WHERE (x_1.security_id = f.security_id))) AS has_news,
            (EXISTS ( SELECT 1
                   FROM market.security_officer x_1
                  WHERE (x_1.security_id = f.security_id))) AS has_leadership,
            (EXISTS ( SELECT 1
                   FROM market.insider_trade x_1
                  WHERE (x_1.security_id = f.security_id))) AS has_insider,
            (EXISTS ( SELECT 1
                   FROM market.security_filing x_1
                  WHERE (x_1.security_id = f.security_id))) AS has_filings,
            (EXISTS ( SELECT 1
                   FROM market.security_corporate_action x_1
                  WHERE ((x_1.security_id = f.security_id) AND (x_1.kind = 'dividend'::text)))) AS has_dividends,
            (EXISTS ( SELECT 1
                   FROM market.security_share_stats x_1
                  WHERE (x_1.security_id = f.security_id))) AS has_share_stats,
            (EXISTS ( SELECT 1
                   FROM market.security_estimate x_1
                  WHERE (x_1.security_id = f.security_id))) AS has_estimates,
            (EXISTS ( SELECT 1
                   FROM market.security_statement x_1
                  WHERE ((x_1.security_id = f.security_id) AND (x_1.period_type = 'quarter'::text)))) AS has_quarters,
            (s.sic IS NOT NULL) AS has_sic,
            (sd.capability = 'held'::text) AS segment_capable,
            (EXISTS ( SELECT 1
                   FROM market.security_segment_spine x_1
                  WHERE (x_1.security_id = f.security_id))) AS has_segments,
            (EXISTS ( SELECT 1
                   FROM market.security_segment_spine x_1
                  WHERE ((x_1.security_id = f.security_id) AND (x_1.kind = 'geography'::text)))) AS has_segment_geography,
            (EXISTS ( SELECT 1
                   FROM market.security_taxonomy x_1
                  WHERE ((x_1.security_id = f.security_id) AND (x_1.source_code = ANY (ARRAY['segment-revenue'::text, 'segment-profit'::text]))))) AS has_weighted_industry
           FROM ((market.security_facets f
             LEFT JOIN market.security s ON ((s.security_id = f.security_id)))
             LEFT JOIN market.security_disclosure sd ON ((sd.security_id = f.security_id)))
        )
 SELECT b.security_id,
    b.security_type_code,
    x.facet,
    x.present,
    x.applicable,
    COALESCE(rf.required, false) AS required
   FROM ((b
     CROSS JOIN LATERAL ( VALUES ('symbol'::text,b.has_symbol,true), ('sector'::text,b.has_sector,true), ('industry'::text,b.has_industry,true), ('price'::text,b.has_price,true), ('performance'::text,b.has_performance,true), ('profile'::text,b.has_profile,true), ('fundamentals'::text,b.has_fundamentals,true), ('statements'::text,b.has_statements,true), ('metrics'::text,b.has_metrics,true), ('price_history'::text,b.has_price_history,true), ('daily_history'::text,b.has_daily_history,true), ('news'::text,b.has_news,true), ('leadership'::text,b.has_leadership,true), ('insider'::text,b.has_insider,true), ('filings'::text,b.has_filings,true), ('dividends'::text,b.has_dividends,true), ('share_stats'::text,b.has_share_stats,true), ('estimates'::text,b.has_estimates,true), ('quarters'::text,b.has_quarters,true), ('sic'::text,b.has_sic,b.segment_capable), ('segments'::text,b.has_segments,b.segment_capable), ('segment_geography'::text,b.has_segment_geography,b.segment_capable), ('weighted_industry'::text,b.has_weighted_industry,b.segment_capable)) x(facet, present, applicable))
     LEFT JOIN market.required_facet rf ON (((rf.security_type_code = b.security_type_code) AND (rf.facet = x.facet))));


--
-- Name: VIEW security_facet_status; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_facet_status IS 'What one security has and what it owes, one row per facet. `coverage_current` answers the same question for the whole universe and cannot be filtered to one security — its `base` CTE is `as materialized`, which is load-bearing for the aggregate and a wall for a per-security read. The presence rules therefore exist twice and `tests/completeness-agrees-with-coverage.sql` asserts the two agree, so drift is detectable rather than merely deprecated. `applicable` is false where no regulator can serve the security; `required` comes from the `required_facet` control table, so what a type owes stays editable.';


--
-- Name: security_former_name; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_former_name (
    security_id uuid NOT NULL,
    name text NOT NULL,
    from_date date,
    to_date date,
    source_code text NOT NULL
);


--
-- Name: TABLE security_former_name; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_former_name IS 'Dated former names of a registrant, from SEC''s submissions response. Apple filed as APPLE COMPUTER INC until 2007; matching an older filing by name needs this.';


--
-- Name: security_fundamentals_current; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_fundamentals_current AS
 SELECT sym.symbol,
    f.security_id,
    f.source_code,
    f.as_of,
    f.pe_ratio,
    f.forward_pe,
    f.peg_ratio,
    f.price_to_book,
    f.profit_margin,
    f.gross_margin,
    f.operating_margin,
    f.return_on_equity,
    f.revenue_growth,
    f.debt_to_equity,
    f.dividend_yield,
    f.beta,
    f.enterprise_value,
    f.raw,
    s.currency_code
   FROM ((market.security_fundamentals f
     JOIN market.security_symbol sym ON ((sym.security_id = f.security_id)))
     JOIN market.security s ON ((s.security_id = f.security_id)));


--
-- Name: security_funds; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_funds AS
 SELECT h.security_id,
    fi.value AS fund_symbol,
    COALESCE(tf.name, fs.name) AS fund_name,
    tf.kind AS fund_kind,
    tf.represents_code,
    h.weight,
    h.as_of
   FROM (((market.fund_holding_current h
     JOIN market.security_identifier fi ON (((fi.security_id = h.fund_id) AND (fi.kind_code = 'ticker'::text))))
     JOIN market.security fs ON ((fs.security_id = h.fund_id)))
     LEFT JOIN market.tracked_fund tf ON ((tf.symbol = fi.value)))
  WHERE (h.security_id <> h.fund_id);


--
-- Name: VIEW security_funds; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_funds IS 'Which tracked funds hold a given security, with the weight the fund REPORTED IN ITS FILING. Weights do not sum to 100 across a fund (EWT files 110.38) and are up to ~4 months old — always show as_of.';


--
-- Name: security_industries; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_industries AS
 SELECT st.security_id,
    tn.taxonomy_id,
    tn.node_id,
    tn.code,
    tn.name,
    tn.level,
    parent.code AS parent_code,
    parent.name AS parent_name,
    st.source_code,
    ds.priority AS source_priority,
    st.weight,
    st.as_of
   FROM (((market.security_taxonomy st
     JOIN market.taxonomy_node tn ON ((tn.node_id = st.node_id)))
     LEFT JOIN market.taxonomy_node parent ON ((parent.node_id = tn.parent_id)))
     JOIN market.data_source ds ON ((ds.code = st.source_code)));


--
-- Name: VIEW security_industries; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_industries IS 'EVERY classification a security carries, across EVERY taxonomy, with its source, that source''s priority and — where the classification is derived from disclosed segments — its weight. `taxonomy_id` is a column, not a filter: muffin is what `security_current` resolves for a page header, while SIC and Wikidata exist precisely to disagree with it.';


--
-- Name: security_insider_summary; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_insider_summary AS
 SELECT security_id,
    count(*) FILTER (WHERE (direction = 'Acquisition'::text)) AS buys,
    count(*) FILTER (WHERE (direction = 'Disposition'::text)) AS sells,
    count(DISTINCT owner_name) FILTER (WHERE (direction = 'Acquisition'::text)) AS buyers,
    count(DISTINCT owner_name) FILTER (WHERE (direction = 'Disposition'::text)) AS sellers,
    (COALESCE(sum(shares) FILTER (WHERE (direction = 'Acquisition'::text)), (0)::numeric) - COALESCE(sum(shares) FILTER (WHERE (direction = 'Disposition'::text)), (0)::numeric)) AS net_shares,
    max(transaction_date) AS latest,
    count(*) AS trades
   FROM market.insider_trade t
  WHERE (transaction_date >= (CURRENT_DATE - 90))
  GROUP BY security_id;


--
-- Name: VIEW security_insider_summary; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_insider_summary IS 'Insider direction over the last 90 days: net shares, and how many distinct PEOPLE were on each side. The people count is not decoration — one officer exercising a large grant can outweigh a dozen colleagues buying, and a net share figure alone would report that as selling.';


--
-- Name: security_leadership; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_leadership AS
 SELECT o.security_id,
    o.name,
    o.title,
    o.pay,
    o.age,
    o.fiscal_year,
    ((o.title ~~* '%chief executive%'::text) OR (o.title ~~* '%CEO%'::text)) AS is_ceo,
        CASE
            WHEN (s.reporting_currency IS NOT NULL) THEN s.reporting_currency
            WHEN (s.currency_code IS NULL) THEN NULL::text
            WHEN (s.currency_code <> 'USD'::text) THEN s.currency_code
            WHEN (COALESCE(s.provider_country_iso2, s.country_iso2) = 'US'::text) THEN s.currency_code
            ELSE NULL::text
        END AS pay_currency
   FROM (market.security_officer o
     JOIN market.security s ON ((s.security_id = o.security_id)));


--
-- Name: VIEW security_leadership; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_leadership IS 'Officers with a flag for the chief executive and the currency `pay` is denominated in. Ordering by pay alone puts whoever was granted the most equity that year at the top, which is not who runs the company. `pay_currency` follows migration 091''s rule — the company''s stated reporting currency first, the quote currency only where it can stand in, NULL otherwise — so a figure whose currency is unknown is rendered unlabelled rather than as dollars.';


--
-- Name: security_metric_series; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_metric_series AS
 WITH gapped AS (
         SELECT sm.security_id,
            sym.symbol,
            sm.metric_code,
            sm.period_type,
            sm.as_of,
            sm.value,
            sm.currency_code,
            sm.source_code,
            ds.priority,
                CASE
                    WHEN ((sm.as_of - lag(sm.as_of) OVER (PARTITION BY sym.symbol, sm.security_id, sm.metric_code, sm.period_type ORDER BY sm.as_of)) <= 7) THEN 0
                    ELSE 1
                END AS starts_cluster
           FROM ((market.security_metric sm
             JOIN market.data_source ds ON ((ds.code = sm.source_code)))
             JOIN market.symbol_security sym ON ((sym.security_id = sm.security_id)))
        ), clustered AS (
         SELECT g.security_id,
            g.symbol,
            g.metric_code,
            g.period_type,
            g.as_of,
            g.value,
            g.currency_code,
            g.source_code,
            g.priority,
            g.starts_cluster,
            sum(g.starts_cluster) OVER (PARTITION BY g.symbol, g.security_id, g.metric_code, g.period_type ORDER BY g.as_of) AS period_group
           FROM gapped g
        )
 SELECT DISTINCT ON (c.symbol, c.security_id, c.metric_code, c.period_type, c.period_group) c.symbol,
    c.security_id,
    c.metric_code,
    m.name AS metric_name,
    m.category,
    m.unit,
    m.is_derived,
    c.period_type,
    c.as_of,
    c.value,
    COALESCE(c.currency_code, s.reporting_currency) AS currency_code,
    c.source_code
   FROM ((clustered c
     JOIN market.metric m ON ((m.code = c.metric_code)))
     JOIN market.security s ON ((s.security_id = c.security_id)))
  ORDER BY c.symbol, c.security_id, c.metric_code, c.period_type, c.period_group, c.priority DESC, c.as_of DESC;


--
-- Name: VIEW security_metric_series; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_metric_series IS 'One point per fiscal period per metric, the filing preferred over the provider. `currency_code` is EFFECTIVE — the metric''s own currency where the source stated one, else the company''s `reporting_currency` — because the yfinance statement endpoints carry no currency field and 990,847 metrics were therefore null, which `money.ts` correctly renders as an unlabelled number. It is the REPORTING currency and never `security.currency_code`: BHP quotes AUD and reports USD, Shell quotes GBP and reports USD. Joins the MATERIALISED `symbol_security`, not `security_symbol`: the latter is a per-security lateral, so filtering by symbol walked the whole universe and timed out for anon.';


--
-- Name: security_news; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_news AS
 SELECT ns.security_id,
    sym.symbol,
    a.url,
    a.published_at,
    a.title,
    a.source,
    a.summary,
    ns.source_code
   FROM ((market.news_security ns
     JOIN market.news_article a ON ((a.url = ns.url)))
     JOIN market.security_symbol sym ON ((sym.security_id = ns.security_id)));


--
-- Name: VIEW security_news; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_news IS 'Articles a provider returned for a security, newest first when ordered. The association is the PROVIDER''S — see news_security.';


--
-- Name: security_next_earnings; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_next_earnings AS
 SELECT DISTINCT ON (security_id) security_id,
    symbol,
    report_date,
    eps_consensus,
    eps_previous,
    num_estimates,
    reporting_time,
    period_ending,
    (report_date >= CURRENT_DATE) AS upcoming,
    as_of
   FROM market.earnings_calendar e
  WHERE (security_id IS NOT NULL)
  ORDER BY security_id, (report_date >= CURRENT_DATE) DESC, (abs((report_date - CURRENT_DATE)));


--
-- Name: VIEW security_next_earnings; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_next_earnings IS 'One row per tracked security: its next scheduled earnings date, or the most recent past one when nothing is scheduled. `upcoming` says which — a page showing "reports 26 Aug" for a date that has passed is worse than showing nothing.';


--
-- Name: security_peers; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_peers AS
 SELECT s.security_id,
    p.security_id AS peer_id,
    p.name AS peer_name,
    p.symbol AS peer_symbol,
    p.market_cap_usd AS peer_market_cap_usd,
    s.market_cap_usd,
    s.sector_id,
    abs(((ln((p.market_cap_usd / s.market_cap_usd)))::double precision / ln((10)::double precision))) AS size_distance
   FROM (market.security_facets s
     JOIN market.security_facets p ON (((p.sector_id = s.sector_id) AND (p.security_id <> s.security_id))))
  WHERE ((s.sector_id IS NOT NULL) AND (s.market_cap_usd > (0)::numeric) AND (p.market_cap_usd > (0)::numeric));


--
-- Name: VIEW security_peers; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_peers IS 'Companies in the same sector of a similar size, computed from the materialised spine. NOT taken from `equity/compare/peers`: that endpoint answers for every symbol (measured — the per-symbol 402 belongs to `revenue_per_geography`, not to this one), but its list is not size-proximate — AAPL comes back beside NVDA at $5.2tn AND Algorhythm Holdings at $852,000. Size proximity is the property a comparison needs, so it is computed rather than fetched. Distance is a log ratio because a $40bn gap means one thing between two $50bn companies and nothing between two $2tn ones.';


--
-- Name: security_price_target; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_price_target (
    security_id uuid NOT NULL,
    published_date date NOT NULL,
    analyst_company text NOT NULL,
    target_from numeric,
    target_to numeric,
    status text,
    rating_change text,
    source_code text NOT NULL,
    fetched_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE security_price_target; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.security_price_target IS 'Individual analyst actions from `equity/estimates/price_target?provider=finviz` — who re-rated, when, and in which direction. Distinct in GRAIN from market.security_estimate, which holds the daily consensus LEVEL and covers the universe globally; this is the US-listed event stream behind it. `target_to` is the provider''s `adj_price_target` (the NEW target) and `target_from` its `price_target` (the PREVIOUS one), which is the opposite of what those names suggest.';


--
-- Name: security_ratio_series; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_ratio_series AS
 WITH spans AS (
         SELECT m.security_id,
            m.metric_code,
            m.value,
            m.currency_code,
            m.as_of,
            lead(m.as_of) OVER (PARTITION BY m.security_id, m.metric_code ORDER BY m.as_of) AS next_as_of
           FROM (market.security_metric m
             JOIN market.metric mt ON ((mt.code = m.metric_code)))
          WHERE ((m.period_type =
                CASE
                    WHEN mt.is_flow THEN 'ttm'::text
                    ELSE 'quarter'::text
                END) AND (m.metric_code = ANY (ARRAY['eps_diluted'::text, 'revenue'::text, 'total_equity'::text, 'free_cash_flow'::text, 'net_income'::text, 'shares_diluted'::text, 'total_assets'::text])))
        ), fx AS (
         SELECT r.currency_code,
            r.usd_per_unit,
            r.as_of,
            lead(r.as_of) OVER (PARTITION BY r.currency_code ORDER BY r.as_of) AS next_as_of
           FROM market.fx_rate r
        ), bars AS (
         SELECT ss.symbol,
            sp.security_id,
            sp.date,
            sp.close,
            sp.grain,
            s.currency_code AS quote_currency,
            s.reporting_currency
           FROM ((market.security_price sp
             JOIN market.symbol_security ss ON ((ss.security_id = sp.security_id)))
             JOIN market.security s ON ((s.security_id = sp.security_id)))
        ), joined AS (
         SELECT b.symbol,
            b.security_id,
            b.date,
            b.close,
            b.grain,
            b.quote_currency,
            b.reporting_currency,
            max(
                CASE
                    WHEN (sp.metric_code = 'eps_diluted'::text) THEN sp.value
                    ELSE NULL::numeric
                END) AS eps,
            max(
                CASE
                    WHEN (sp.metric_code = 'revenue'::text) THEN sp.value
                    ELSE NULL::numeric
                END) AS revenue,
            max(
                CASE
                    WHEN (sp.metric_code = 'total_equity'::text) THEN sp.value
                    ELSE NULL::numeric
                END) AS equity,
            max(
                CASE
                    WHEN (sp.metric_code = 'free_cash_flow'::text) THEN sp.value
                    ELSE NULL::numeric
                END) AS fcf,
            max(
                CASE
                    WHEN (sp.metric_code = 'net_income'::text) THEN sp.value
                    ELSE NULL::numeric
                END) AS net_income,
            max(
                CASE
                    WHEN (sp.metric_code = 'shares_diluted'::text) THEN sp.value
                    ELSE NULL::numeric
                END) AS shares,
            max(
                CASE
                    WHEN (sp.metric_code = 'total_assets'::text) THEN sp.value
                    ELSE NULL::numeric
                END) AS assets,
            max(sp.currency_code) AS metric_currency
           FROM (bars b
             JOIN spans sp ON (((sp.security_id = b.security_id) AND (b.date >= sp.as_of) AND ((sp.next_as_of IS NULL) OR (b.date < sp.next_as_of)))))
          GROUP BY b.symbol, b.security_id, b.date, b.close, b.grain, b.quote_currency, b.reporting_currency
        ), resolved AS (
         SELECT j.symbol,
            j.security_id,
            j.date,
            j.close,
            j.grain,
            j.quote_currency,
            j.reporting_currency,
            j.eps,
            j.revenue,
            j.equity,
            j.fcf,
            j.net_income,
            j.shares,
            j.assets,
            j.metric_currency,
            COALESCE(j.metric_currency, j.reporting_currency) AS report_currency
           FROM joined j
        ), priced AS (
         SELECT r.symbol,
            r.security_id,
            r.date,
            r.close,
            r.grain,
            r.quote_currency,
            r.reporting_currency,
            r.eps,
            r.revenue,
            r.equity,
            r.fcf,
            r.net_income,
            r.shares,
            r.assets,
            r.metric_currency,
            r.report_currency,
                CASE
                    WHEN (r.report_currency = 'USD'::text) THEN (1)::numeric
                    ELSE fr.usd_per_unit
                END AS report_usd,
                CASE
                    WHEN (r.quote_currency = 'USD'::text) THEN (1)::numeric
                    ELSE fq.usd_per_unit
                END AS quote_usd
           FROM ((resolved r
             LEFT JOIN fx fr ON (((fr.currency_code = r.report_currency) AND (r.date >= fr.as_of) AND ((fr.next_as_of IS NULL) OR (r.date < fr.next_as_of)))))
             LEFT JOIN fx fq ON (((fq.currency_code = r.quote_currency) AND (r.date >= fq.as_of) AND ((fq.next_as_of IS NULL) OR (r.date < fq.next_as_of)))))
        ), converted AS (
         SELECT p.symbol,
            p.security_id,
            p.date,
            p.close,
            p.grain,
            p.quote_currency,
            p.reporting_currency,
            p.eps,
            p.revenue,
            p.equity,
            p.fcf,
            p.net_income,
            p.shares,
            p.assets,
            p.metric_currency,
            p.report_currency,
            p.report_usd,
            p.quote_usd,
            ((p.report_currency IS NOT NULL) AND (p.quote_currency IS NOT NULL) AND (p.report_currency = p.quote_currency)) AS same_currency,
            ((p.report_currency IS NOT NULL) AND (p.quote_currency IS NOT NULL) AND (p.report_currency <> p.quote_currency) AND (p.report_usd IS NOT NULL) AND (p.quote_usd IS NOT NULL) AND (p.quote_usd > (0)::numeric)) AS convertible,
                CASE
                    WHEN (p.report_currency = p.quote_currency) THEN (1)::numeric
                    WHEN ((p.report_usd IS NOT NULL) AND (p.quote_usd IS NOT NULL) AND (p.quote_usd > (0)::numeric)) THEN (p.report_usd / p.quote_usd)
                    ELSE NULL::numeric
                END AS fx
           FROM priced p
        )
 SELECT symbol,
    security_id,
    date,
    grain,
    close,
    report_currency,
    quote_currency,
    (same_currency OR convertible) AS currency_comparable,
    convertible AS fx_converted,
        CASE
            WHEN ((fx IS NOT NULL) AND ((eps * fx) > (0)::numeric)) THEN round((close / (eps * fx)), 4)
            ELSE NULL::numeric
        END AS pe_ratio,
        CASE
            WHEN ((fx IS NOT NULL) AND (revenue > (0)::numeric) AND (shares > (0)::numeric)) THEN round((close / ((revenue * fx) / shares)), 4)
            ELSE NULL::numeric
        END AS ps_ratio,
        CASE
            WHEN ((fx IS NOT NULL) AND (equity > (0)::numeric) AND (shares > (0)::numeric)) THEN round((close / ((equity * fx) / shares)), 4)
            ELSE NULL::numeric
        END AS pb_ratio,
        CASE
            WHEN ((fx IS NOT NULL) AND (fcf > (0)::numeric) AND (shares > (0)::numeric)) THEN round((close / ((fcf * fx) / shares)), 4)
            ELSE NULL::numeric
        END AS price_to_fcf,
        CASE
            WHEN ((fx IS NOT NULL) AND ((eps * fx) > (0)::numeric)) THEN round((((eps * fx) / close) * (100)::numeric), 4)
            ELSE NULL::numeric
        END AS earnings_yield_pct,
        CASE
            WHEN ((fx IS NOT NULL) AND (fcf > (0)::numeric) AND (shares > (0)::numeric)) THEN round(((((fcf * fx) / shares) / close) * (100)::numeric), 4)
            ELSE NULL::numeric
        END AS fcf_yield_pct,
        CASE
            WHEN (revenue > (0)::numeric) THEN round(((net_income / revenue) * (100)::numeric), 4)
            ELSE NULL::numeric
        END AS net_margin_pct,
        CASE
            WHEN (equity > (0)::numeric) THEN round(((net_income / equity) * (100)::numeric), 4)
            ELSE NULL::numeric
        END AS roe_pct,
        CASE
            WHEN (assets > (0)::numeric) THEN round(((net_income / assets) * (100)::numeric), 4)
            ELSE NULL::numeric
        END AS roa_pct
   FROM converted;


--
-- Name: VIEW security_ratio_series; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_ratio_series IS 'Ratios computed PER PRICE BAR from stored inputs. A metric is stepwise in time; so is an exchange rate, and both are carried forward rather than interpolated. Where the filing and the listing use different currencies the FILING is converted into the quote currency at the rate observed for that bar — `fx_converted` says so. A ratio is NULL where no rate is held for the bar or the denominator is not positive: a missing rate is not a rate of 1.';


--
-- Name: security_recent_filings; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_recent_filings AS
 SELECT security_id,
    accession_number,
    filing_date,
    report_date,
    report_type,
    report_url,
    filing_detail_url,
        CASE
            WHEN (report_type = ANY (ARRAY['10-K'::text, '10-K/A'::text, '20-F'::text, '20-F/A'::text])) THEN 'annual'::text
            WHEN (report_type = ANY (ARRAY['10-Q'::text, '10-Q/A'::text, '6-K'::text, '6-K/A'::text])) THEN 'interim'::text
            ELSE 'event'::text
        END AS kind
   FROM market.security_filing f;


--
-- Name: VIEW security_recent_filings; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_recent_filings IS 'Filings with a `kind` — annual, interim or event. A 10-K and an 8-K answer different questions, and a single date-ordered list buries the annual report under a month of press releases.';


--
-- Name: security_segment_detail; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_segment_detail AS
 WITH newest AS (
         SELECT g.security_id,
            g.parent_axis,
            g.parent_member,
            g.axis,
            max(g.period_ending) AS period_ending
           FROM market.security_segment_latest g
          WHERE ((g.partition_id = 1) AND (g.period_type = 'annual'::text) AND (g.parent_member IS NOT NULL))
          GROUP BY g.security_id, g.parent_axis, g.parent_member, g.axis
        ), latest AS (
         SELECT DISTINCT ON (g.security_id, g.parent_member, g.axis, g.member_code, g.metric_code) g.security_id,
            g.parent_axis,
            g.parent_member,
            g.axis,
            g.member_code,
            g.metric_code,
            g.value,
            g.currency_code,
            g.period_ending
           FROM (market.security_segment_latest g
             JOIN newest n ON (((n.security_id = g.security_id) AND (NOT (n.parent_axis IS DISTINCT FROM g.parent_axis)) AND (n.parent_member = g.parent_member) AND (n.axis = g.axis) AND (n.period_ending = g.period_ending))))
          WHERE ((g.partition_id = 1) AND (g.period_type = 'annual'::text) AND (g.parent_member IS NOT NULL))
          ORDER BY g.security_id, g.parent_member, g.axis, g.member_code, g.metric_code, g.period_ending DESC
        ), pivoted AS (
         SELECT l.security_id,
            l.parent_axis,
            l.parent_member,
            l.axis,
            l.member_code,
            max(l.currency_code) AS currency_code,
            max(l.period_ending) AS period_ending,
            max(l.value) FILTER (WHERE (l.metric_code = 'revenue'::text)) AS revenue,
            max(l.value) FILTER (WHERE (l.metric_code = 'operating_income'::text)) AS operating_income
           FROM latest l
          GROUP BY l.security_id, l.parent_axis, l.parent_member, l.axis, l.member_code
        )
 SELECT p.security_id,
    p.parent_axis,
    p.parent_member,
    p.axis,
    p.member_code,
    c.code AS concept_code,
    c.name AS concept_name,
    p.revenue,
    p.operating_income,
    round((((100)::numeric * p.revenue) / NULLIF(sum(p.revenue) OVER (PARTITION BY p.security_id, p.parent_member, p.axis), (0)::numeric)), 2) AS share_of_parent_pct,
    p.currency_code,
    p.period_ending
   FROM ((pivoted p
     LEFT JOIN LATERAL ( SELECT al_1.concept_code
           FROM market.segment_alias al_1
          WHERE ((al_1.member_code = p.member_code) AND ((al_1.security_id = p.security_id) OR (al_1.security_id IS NULL)))
          ORDER BY (al_1.security_id IS NOT NULL) DESC
         LIMIT 1) al ON (true))
     LEFT JOIN market.segment_concept c ON ((c.code = al.concept_code)));


--
-- Name: VIEW security_segment_detail; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_segment_detail IS 'Product lines disclosed WITHIN a reportable segment — Alphabet''s Search, YouTube, Network and Subscriptions inside Google Services. Their share is OF THE PARENT, not of the company. Never sum these beside `security_segment_current`.';


--
-- Name: security_segment_geography; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_segment_geography AS
 SELECT security_id,
    member_code,
    country_iso2,
    member_label,
    axis,
    revenue,
    operating_income,
    revenue_share_pct,
    currency_code,
    period_ending,
    accession_number
   FROM market.security_segment_spine c
  WHERE ((kind = 'geography'::text) AND (member_label IS NOT NULL));


--
-- Name: VIEW security_segment_geography; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_segment_geography IS 'Revenue and operating income by the geography a filer discloses, for members whose meaning is published (ISO countries and standard regions) so nothing here required curation. A filer''s own extension for a region — bud:LatinAmericaWestMember — is deliberately absent: it needs a segment_member row before it can be named.';


--
-- Name: security_statement_current; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.security_statement_current AS
 SELECT sym.symbol,
    st.security_id,
    st.statement,
    st.period_ending,
    st.period_type,
    st.currency,
    st.data,
    st.source_code,
    st.as_of,
    st.derived_at,
    s.currency_code,
    COALESCE(s.provider_country_iso2, s.country_iso2) AS country_iso2,
        CASE
            WHEN (st.currency IS NOT NULL) THEN st.currency
            WHEN (s.currency_code IS NULL) THEN NULL::text
            WHEN (s.currency_code <> 'USD'::text) THEN s.currency_code
            WHEN (COALESCE(s.provider_country_iso2, s.country_iso2) = 'US'::text) THEN s.currency_code
            ELSE NULL::text
        END AS reporting_currency
   FROM ((market.security_statement st
     JOIN market.security_symbol sym ON ((sym.security_id = st.security_id)))
     JOIN market.security s ON ((s.security_id = st.security_id)));


--
-- Name: VIEW security_statement_current; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.security_statement_current IS 'Income/balance/cash statements with the security symbol. `reporting_currency` is THE column to label a figure with: the filing''s own currency where a provider supplied it, the quote currency only where it can stand in, and NULL otherwise — a non-US company quoted in USD reports in neither. `currency_code` remains the raw QUOTE currency and `country_iso2` the EFFECTIVE country, so a caller can still see the inputs.';


--
-- Name: security_type; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.security_type (
    code text NOT NULL,
    name text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL
);


--
-- Name: segment_member_class; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.segment_member_class (
    member_code text NOT NULL,
    class text NOT NULL,
    reason text NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT segment_member_class_class_check CHECK ((class = ANY (ARRAY['subtotal'::text, 'residual'::text])))
);


--
-- Name: TABLE segment_member_class; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.segment_member_class IS 'Members that cannot be a business line, and why. `subtotal` is dropped before partitioning — a split containing one double-counts by construction. `residual` is KEPT (it is a real part of a split that includes named segments) but may never be the whole of one, or the leftovers get served as the company. Adding a row needs no deploy; a `segment_parser.version` bump re-reads every filing.';


--
-- Name: symbol_cache_classification; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.symbol_cache_classification AS
 SELECT column_name,
    symbol_keyed,
    reason
   FROM ( VALUES ('industry_missing_at'::text,true,'yfinance profile fetched by symbol'::text), ('profile_missing_at'::text,true,'yfinance profile fetched by symbol'::text), ('performance_missing_at'::text,true,'historical bars fetched by symbol'::text), ('fundamentals_missing_at'::text,true,'metrics fetched by symbol'::text), ('statements_missing_at'::text,true,'statements fetched by symbol'::text), ('prices_missing_at'::text,true,'daily bars fetched by symbol'::text), ('quarters_missing_at'::text,true,'quarterly statements fetched by the PRICED symbol'::text), ('provider_country_missing_at'::text,true,'yfinance profile fetched by symbol'::text), ('corporate_actions_missing_at'::text,true,'Tiingo EOD fetched by the US ticker'::text), ('dividends_missing_at'::text,true,'yfinance dividends fetched by the PRICED symbol'::text), ('price_history_missing_at'::text,true,'weekly history fetched by the PRICED symbol'::text), ('daily_history_missing_at'::text,true,'deep daily history fetched by the PRICED symbol'::text), ('share_stats_missing_at'::text,true,'share statistics fetched by the PRICED symbol'::text), ('estimates_missing_at'::text,true,'analyst consensus fetched by the PRICED symbol'::text), ('profile_detail_missing_at'::text,true,'yfinance profile fetched by symbol'::text), ('figi_missing_at'::text,false,'OpenFIGI asked for the ISIN, not the symbol'::text), ('local_symbol_missing_at'::text,false,'keyed on ISIN/FIGI, not the symbol'::text), ('yahoo_symbol_missing_at'::text,false,'the resolver''s own flag — clearing it here would loop'::text), ('statement_currency_missing_at'::text,false,'SEC asked by the US ticker; a new provider symbol says nothing about whether the company files'::text), ('xbrl_missing_at'::text,false,'company facts are asked for by CIK; a new provider symbol says nothing about the filer'::text), ('wikidata_missing_at'::text,false,'Wikidata is asked for by ISIN; a corrected provider symbol says nothing about a Wikidata entity, and clearing it would re-ask a public endpoint for an answer already held'::text)) t(column_name, symbol_keyed, reason);


--
-- Name: taxonomy; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.taxonomy (
    taxonomy_id text NOT NULL,
    name text NOT NULL,
    description text
);


--
-- Name: ticker_disagreement; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.ticker_disagreement AS
 SELECT s.security_id,
    s.name,
    s.country_iso2,
    f.us_ticker AS sec_ticker,
    f.us_exchange AS sec_exchange,
    i.value AS openfigi_ticker,
    COALESCE(max(h.weight), (0)::numeric) AS best_weight
   FROM (((market.filer_profile f
     JOIN market.security s ON ((s.security_id = f.security_id)))
     LEFT JOIN market.security_identifier i ON (((i.security_id = f.security_id) AND (i.kind_code = 'ticker'::text))))
     LEFT JOIN market.fund_holding_current h ON ((h.security_id = f.security_id)))
  WHERE ((f.us_ticker IS NOT NULL) AND (i.value IS DISTINCT FROM f.us_ticker))
  GROUP BY s.security_id, s.name, s.country_iso2, f.us_ticker, f.us_exchange, i.value
  ORDER BY COALESCE(max(h.weight), (0)::numeric) DESC;


--
-- Name: VIEW ticker_disagreement; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.ticker_disagreement IS 'Securities where the registrant''s own US ticker differs from the one OpenFIGI resolved, weighted by fund holding. The measurement that decides whether the symbol-dependent backlogs should prefer SEC''s answer — read it before changing them.';


--
-- Name: venue_currency; Type: VIEW; Schema: market; Owner: -
--

CREATE VIEW market.venue_currency AS
 WITH quoted AS (
         SELECT SUBSTRING(sym.symbol FROM POSITION(('.'::text) IN (sym.symbol))) AS suffix,
            s.currency_code
           FROM (market.security s
             JOIN market.security_symbol sym ON ((sym.security_id = s.security_id)))
          WHERE ((s.currency_code IS NOT NULL) AND (POSITION(('.'::text) IN (sym.symbol)) > 0))
        ), tallied AS (
         SELECT quoted.suffix,
            quoted.currency_code,
            count(*) AS n,
            sum(count(*)) OVER (PARTITION BY quoted.suffix) AS venue_total
           FROM quoted
          GROUP BY quoted.suffix, quoted.currency_code
        )
 SELECT DISTINCT ON (suffix) suffix,
    currency_code AS quote_currency,
    n AS agreeing,
    venue_total AS securities
   FROM tallied
  WHERE ((venue_total >= (5)::numeric) AND (((n)::numeric / venue_total) > 0.60))
  ORDER BY suffix, n DESC;


--
-- Name: VIEW venue_currency; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON VIEW market.venue_currency IS 'The currency each venue MOST COMMONLY trades in, derived by majority from securities we hold. Descriptive only: it may not overrule a provider by itself, because Hong Kong, Toronto and SIX all carry legitimate multi-currency listings and Johannesburg and Kuwait quote in subunits. Used only in combination with an impossible market cap.';


--
-- Name: xbrl_concept; Type: TABLE; Schema: market; Owner: -
--

CREATE TABLE market.xbrl_concept (
    metric_code text NOT NULL,
    concept text NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    unit text DEFAULT 'USD'::text NOT NULL,
    taxonomy text DEFAULT 'us-gaap'::text NOT NULL
);


--
-- Name: TABLE xbrl_concept; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON TABLE market.xbrl_concept IS 'Which XBRL concepts express each metric, priority-ordered. Measured, not guessed: JPM and CAT report revenue as `Revenues` while AAPL, WMT and PFE use `RevenueFromContractWithCustomerExcludingAssessedTax`. Resolution is per PERIOD — CAT reports NetIncomeLoss only for 2009..2011.';


--
-- Name: COLUMN xbrl_concept.unit; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.xbrl_concept.unit IS 'A KIND, not a literal. `USD` means "whichever currency this filer reports in" — Novo Nordisk''s facts are under a DKK unit key and Nokia''s under EUR. `USD/shares` is per-share in that currency; `shares` is a count with no currency.';


--
-- Name: COLUMN xbrl_concept.taxonomy; Type: COMMENT; Schema: market; Owner: -
--

COMMENT ON COLUMN market.xbrl_concept.taxonomy IS 'The companyfacts taxonomy node: `us-gaap` for domestic filers, `ifrs-full` for foreign private issuers filing 20-F. Reading only one marked 10 of 20 filers as having no facts — AB InBev''s companyfacts has no us-gaap node at all.';


