INSERT INTO market.backlog_negative_cache (backlog, missing_column, note) VALUES ('pending_ticker', 'figi_missing_at', 'keyed on the ISIN, not the symbol');
INSERT INTO market.backlog_negative_cache (backlog, missing_column, note) VALUES ('pending_xbrl', 'xbrl_missing_at', NULL);
INSERT INTO market.backlog_negative_cache (backlog, missing_column, note) VALUES ('pending_metrics', NULL, 'a DRIFT COUNTER, not a queue: the function re-derives everything every run, so a non-zero value is expected and the TREND is the signal');
INSERT INTO market.backlog_negative_cache (backlog, missing_column, note) VALUES ('pending_ttm', NULL, 'derived in SQL, no provider and therefore no negative cache');
INSERT INTO market.backlog_negative_cache (backlog, missing_column, note) VALUES ('pending_promotion', NULL, 'opt-in per venue; does nothing until an operator enables one');
INSERT INTO market.backlog_negative_cache (backlog, missing_column, note) VALUES ('pending_symbol_repair', NULL, 'verifies candidates against the provider; an unrepairable symbol simply stays');
INSERT INTO market.backlog_negative_cache (backlog, missing_column, note) VALUES ('pending_segments', NULL, 'a CURSOR, not a negative cache: `security_filing.segments_parsed_at` records that we LOOKED, permanently, because a filed document is immutable. Re-reading is driven by segment_parser.version');
INSERT INTO market.backlog_negative_cache (backlog, missing_column, note) VALUES ('pending_filing_history', NULL, 'a CURSOR (`filing_history_fetched_at`): filings keep arriving, so an absence is never permanent — the same reasoning as insider_fetched_at');
INSERT INTO market.backlog_negative_cache (backlog, missing_column, note) VALUES ('pending_wikidata', 'wikidata_missing_at', NULL);
INSERT INTO market.backlog_negative_cache (backlog, missing_column, note) VALUES ('pending_segment_alias', NULL, 'a DRIFT COUNTER, not a queue: segment_alias is EDITORIAL, so a non-zero value is expected for ever and the TREND is the signal. It grows when the parser reaches new filers and falls when somebody curates');


