INSERT INTO market.disclosure_source (code, name, identifier_label, enabled, priority, note) VALUES ('cninfo', 'CNINFO (China)', 'org_id', true, 60, 'Measured NOT viable 2026-09-06: CNINFO has a working machine-readable search and is reachable from the node, but every filing is a PDF — 2,771 announcements for China Yangtze Power (600900), all adjunctType PDF, including all 61 annual reports; the FY2025 report begins %PDF-1.7. The route exists and the format does not.');
INSERT INTO market.disclosure_source (code, name, identifier_label, enabled, priority, note) VALUES ('sec', 'SEC EDGAR', 'CIK', true, 100, 'Registration-driven rather than jurisdictional: 787 non-US securities file a 20-F or 40-F, so SEC deliberately has NO rows in disclosure_coverage.');
INSERT INTO market.disclosure_source (code, name, identifier_label, enabled, priority, note) VALUES ('edinet', 'EDINET (Japan)', 'edinet_code', false, 80, 'Measured NOT viable 2026-08-29: Nintendo FY2026 carries 8 distinct dimensions and ZERO segment axes. The segment note is jpcrp_cor:NotesSegmentInformationEtc...TextBlock — escaped HTML in a text block. Kept as a row so the finding is not re-derived.');
INSERT INTO market.disclosure_source (code, name, identifier_label, enabled, priority, note) VALUES ('esef', 'ESEF (EU)', 'lei', false, 70, 'Measured NOT viable 2026-08-29: ASML, Nokia, Novo Nordisk and TotalEnergies FY2025 carry 431-872 facts and ZERO segment axes. ESEF mandates detailed tagging of the PRIMARY STATEMENTS only; the IFRS 8 note is block-tagged as text.');
INSERT INTO market.disclosure_source (code, name, identifier_label, enabled, priority, note) VALUES ('dart', 'DART (Korea)', 'corp_code', true, 90, 'Measured viable 2026-08-29: a full 7.1 MB instance carrying ifrs-full:ProductsAndServicesAxis / SegmentsAxis / GeographicalAreasAxis — the same axes the parser already handles for Diageo. SK Gas reconciles exactly to 7,050,068,258,000 KRW. Enabled once security-kr-segments exists.');
INSERT INTO market.disclosure_source (code, name, identifier_label, enabled, priority, note) VALUES ('mops', 'TWSE MOPS (Taiwan)', 'co_id', false, 55, 'Measured NOT viable 2026-09-06: MediaTek (2454) FY2024 via t164sb01 is genuine inline XBRL — 1.24 MB, 4,542 ix: tags, 3,891 contextRefs — but carries only ifrs-full:ComponentsOfEquityAxis and a doubtful-accounts axis. No segment axis, and 部門 appears zero times. Same signature as ESEF and EDINET: the primary statements are tagged and the IFRS 8 note is not. Only the t164sb01 route was tested.');
INSERT INTO market.disclosure_source (code, name, identifier_label, enabled, priority, note) VALUES ('nse', 'NSE (India)', 'symbol', true, 85, 'Measured VIABLE 2026-09-06: Reliance''s NSE XBRL carries in-bse-fin:ReportableSegmentsAxis (plus FinanceCosts/Liabilities/Assets siblings) and the annual column reconciles EXACTLY to 11,094,900,000,000. Two structural traps: members are anonymous positional slots (OneReportableSegmentRevenue01Member), so the name comes from a sibling in-bse-fin:DescriptionOfReportableSegment fact on the same context; and the One/Four prefix is the PERIOD (3-month vs 12-month), so summing all ten members overstates by 26%. API needs a browser UA and a cookie handshake.');


