INSERT INTO market.exchange_sweep_type (security_type, sort_order, notes, figi_field) VALUES ('Depositary Receipt', 2, 'ADRs/GDRs. BABA, TSM, NVO and every other foreign company''s US line lives here, and a Common-Stock-only sweep loses all of them.', 'securityType2');
INSERT INTO market.exchange_sweep_type (security_type, sort_order, notes, figi_field) VALUES ('ETP', 3, 'Exchange-traded products — ETFs, ETNs, commodity trusts. Measured 2026-08-17: 6,664 on the US venue alone against the 74 ETFs the universe held, all of them hand-added. Filtered on securityType, NOT securityType2: SPY is securityType ETP inside securityType2 Mutual Fund, and that bucket returns 44,119 US rows of mostly open-end mutual funds, which are not exchange-traded and are over the paging ceiling.', 'securityType');


