INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('50-clear-stale-prices-cache', '2026-10-06 21:28:15.796544+00', 'prices_missing_at was set under symbols the resolver has since corrected; the resolver never cleared it because the hand-written clear list predated the column.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('53-point-swept-venues-at-receipts', '2026-10-06 21:28:15.904788+00', 'Venues that had finished Common Stock were moved to Depositary Receipt once, rather than re-enumerating rows already held.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('54-partition-the-us-sweep', '2026-10-06 21:28:15.938794+00', 'US holds exactly 15,000 of 20,107 common stocks — OpenFIGI pages no deeper. Restarted partitioned so the remaining ~5,100 and the 2,700 ADRs can be reached.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('55-clear-contradicted-performance-marks', '2026-10-06 21:28:15.973007+00', 'Cleared 0 performance_missing_at marks contradicted by price bars from the last 5 days (set by a batch tally during progressive yfinance throttling, 2026-08-11..13).');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('57-clear-throttle-burst-statement-marks', '2026-10-06 21:28:16.047473+00', 'Cleared 0 statements_missing_at marks set before 2026-08-13, when three bursts (518 + 725 + 1032 in one hour each, against a ~15/hour steady state) recorded securities as having no statements during yfinance throttling. ISRG, EXC and MLM each returned 12 rows when re-driven.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('58-promote-market-cap-from-fundamentals', '2026-10-06 21:28:16.0799+00', 'Promoted 0 market caps from security_fundamentals.raw into security.market_cap. equity/profile carries no cap for most non-US listings, so coverage was 8,163 of 12,348 (66%) while the values sat unread in the metrics payload.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('60-clear-marks-for-newly-known-jurisdictions', '2026-10-06 21:28:16.177204+00', 'Cleared 0 provider_country_missing_at marks after adding Macau, Monaco, Guernsey, Jersey, Isle of Man and Gibraltar — the profile had answered with those names and market.countries had no row to resolve them to.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('64-clear-marks-for-newly-swept-venues', '2026-10-06 21:28:16.294761+00', 'Re-asked OpenFIGI for 0 securities in KW, QA, VN and AR after migration 63 added their venues. NOTE: the original justification was wrong — the marks were not blocking symbol resolution, which the cron completed on its own with the marks still set. Kept as a cheap one-off re-ask, not as a precedent.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('68-drop-unattributable-corporate-actions', '2026-10-06 21:28:16.42111+00', 'Deleted 0 corporate-action rows written before observed_symbol existed. The resource asks Tiingo by US ticker while prices are stored for the primary listing, and those differed for 33 of the first 45 securities — a USD dividend recorded against a KRW price series. Re-earned by the restricted backlog.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('74-relabel-impossible-usd-caps', '2026-10-06 21:28:16.603543+00', 'Relabelled 0 securities claiming USD on a non-US venue with a market cap above $2tn. The largest real company is ~$5.5tn and US-listed, so a suffixed symbol at this scale is a unit error rather than a company — PT Barito read $442tn, 4x world GDP. Prior values are in market.currency_repair.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('clear-ifrs-xbrl-marks', '2026-10-06 21:28:17.550522+00', NULL);
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('drop-ytd-contaminated-quarters', '2026-10-06 21:28:17.69723+00', 'deleted 0 sec-xbrl quarterly rows contaminated with year-to-date figures; AAPL 2026-03-28 read 254,940M against a full year of 416,161M');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('114-derived-at-backfill', '2026-10-06 21:28:18.09393+00', 'Marked 0 already-derived statements so the first run after this deploy does not re-derive the whole table. The ones that genuinely qualify stay NULL.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('135-clear-moving-price-performance-marks', '2026-10-06 21:28:18.868711+00', 'Recurrence of the 055 defect found by market.data_defect on its first read: marks on securities whose price moves daily. The 15 flat-price marks were left alone deliberately.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('137-etf-does-not-owe-a-price-row', '2026-10-06 21:28:18.940156+00', 'pending_prices is equity-scoped, so an ETF can never have a security_price row. Requiring it reported all 74 ETFs as 0% complete for ever.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('140-backfill-price-history-from', '2026-10-06 21:28:19.057138+00', 'A scan of security_price for weekly history costs 7.9s cold against 8ms for a column, and sample_coverage is bounded by the 8s PostgREST statement timeout.');
INSERT INTO market.one_shot (key, applied_at, reason) VALUES ('segment-parser-v2-reconciled-to', '2026-10-06 21:28:19.595687+00', NULL);
