--

INSERT INTO market.segment_member_class (member_code, class, reason, as_of) VALUES ('us-gaap:ReportableSegmentAggregationBeforeOtherOperatingSegmentMember', 'subtotal', 'The sum of the reportable segments — Chevron FY2025 publishes it beside AllOther and the two reconcile exactly (230,789m + 581m = 231,370m), which made a subtotal plus a residual look like a business-line split.', '2026-10-06 21:28:20.441248+00');
INSERT INTO market.segment_member_class (member_code, class, reason, as_of) VALUES ('ifrs-full:ReportableSegmentsMember', 'subtotal', 'IFRS 8 aggregate of the reportable segments; same shape as the us-gaap member above.', '2026-10-06 21:28:20.441248+00');
INSERT INTO market.segment_member_class (member_code, class, reason, as_of) VALUES ('us-gaap:OperatingSegmentsMember', 'subtotal', 'The aggregate of the operating segments. It is a QUALIFIER member on the consolidation-items axis, but some filers also tag it on the segment axis itself, where it is the total rather than a segment.', '2026-10-06 21:28:20.441248+00');
INSERT INTO market.segment_member_class (member_code, class, reason, as_of) VALUES ('us-gaap:AllOtherSegmentsMember', 'residual', 'Everything not separately reportable. 27 served splits consist of it alone, ratios from 0.000 to 1.000 of their own target — and a split that is 100% "all other" is no more a breakdown than one that is 0.25%.', '2026-10-06 21:28:20.441248+00');
INSERT INTO market.segment_member_class (member_code, class, reason, as_of) VALUES ('us-gaap:CorporateAndOtherMember', 'residual', 'The corporate leftovers bucket. 16 served splits consist of it alone, up to 62.6% of the target — large, and still not a business line.', '2026-10-06 21:28:20.441248+00');
INSERT INTO market.segment_member_class (member_code, class, reason, as_of) VALUES ('ifrs-full:AllOtherSegmentsMember', 'residual', 'IFRS counterpart; 2 served splits consist of it alone, at 1.7% and 1.8% of target.', '2026-10-06 21:28:20.441248+00');


