--

CREATE INDEX attempt_facet_idx ON ingest.attempt USING btree (facet, started_at DESC);


--
-- Name: attempt_open_idx; Type: INDEX; Schema: ingest; Owner: -
--

CREATE INDEX attempt_open_idx ON ingest.attempt USING btree (started_at) WHERE (finished_at IS NULL);


--
-- Name: task_claim_idx; Type: INDEX; Schema: ingest; Owner: -
--

CREATE INDEX task_claim_idx ON ingest.task USING btree (facet, round, priority DESC, subject) WHERE (status = ANY (ARRAY['due'::ingest.task_status, 'backoff'::ingest.task_status]));


--
-- Name: task_due_idx; Type: INDEX; Schema: ingest; Owner: -
--

CREATE INDEX task_due_idx ON ingest.task USING btree (facet, next_due_at) WHERE (status = ANY (ARRAY['due'::ingest.task_status, 'backoff'::ingest.task_status]));


--
-- Name: task_lease_idx; Type: INDEX; Schema: ingest; Owner: -
--

CREATE INDEX task_lease_idx ON ingest.task USING btree (lease_expires_at) WHERE (status = 'leased'::ingest.task_status);


